INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('sl-teorema1', 'slides', '', 'Cap. 3 — Raízes de Equações', 'bissecao', 1, 'texto', 1, NULL, 'Pelo Teorema 1 dos slides, o que garante que existe pelo menos uma raiz de f em [a, b]?', NULL, 'f contínua em [a, b] e f(a)·f(b) < 0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"Se f é contínua em [a, b] e f(a)·f(b) < 0, existe pelo menos um x₀ em [a, b] com f(x₀) = 0. É a base dos métodos intervalares (Bisseção e Falsa Posição)."}', 'Se f é contínua em [a, b] e f(a)·f(b) < 0, existe pelo menos um x₀ em [a, b] com f(x₀) = 0. É a base dos métodos intervalares (Bisseção e Falsa Posição).', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('sl-teorema1', 'A', 'f(a)·f(b) > 0', 0, 'Sinais iguais nos extremos não garantem raiz nenhuma.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('sl-teorema1', 'B', 'f derivável e f′(a) = 0', 0, 'O teorema usa o sinal de f nos extremos, não a derivada.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('sl-teorema1', 'C', 'f crescente em [a, b]', 0, 'Crescer não basta: f(x) = x + 5 cresce em [0, 1] e não tem raiz ali.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('sl-teorema1', 'D', 'f contínua em [a, b] e f(a)·f(b) < 0', 1, NULL);
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('sl-bis-formula', 'slides', '', 'Cap. 3 — Raízes de Equações', 'bissecao', 1, 'texto', 1, NULL, 'Na Bisseção, como a professora calcula a aproximação xᵢ a cada iteração?', NULL, 'xᵢ = (aᵢ + bᵢ)/2', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"O valor médio do intervalo: xᵢ = (aᵢ + bᵢ)/2. Depois verifica o sinal de f(xᵢ) para escolher os novos extremos."}', 'O valor médio do intervalo: xᵢ = (aᵢ + bᵢ)/2. Depois verifica o sinal de f(xᵢ) para escolher os novos extremos.', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('sl-bis-formula', 'A', 'xᵢ = (aᵢ·f(bᵢ) − bᵢ·f(aᵢ)) / (f(bᵢ) − f(aᵢ))', 0, 'Essa é a média ponderada da Falsa Posição.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('sl-bis-formula', 'B', 'xᵢ = (aᵢ + bᵢ)/2', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('sl-bis-formula', 'C', 'xᵢ₊₁ = xᵢ − f(xᵢ)/f′(xᵢ)', 0, 'Essa é a fórmula do Newton-Raphson.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('sl-bis-formula', 'D', 'xᵢ = √(aᵢ·bᵢ)', 0, 'A Bisseção usa a média aritmética, não a geométrica.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('sl-bis-k', 'slides', '', 'Cap. 3 — Raízes de Equações', 'bissecao', 1, 'numero', 1, NULL, 'Pela fórmula dos slides, k > (log(b₀ − a₀) − log ε)/log 2. Quantas iterações da Bisseção são necessárias em [0, 1] com ε = 10⁻²?', NULL, '7', 7, NULL, NULL, NULL, NULL, 0, 0.1, '{"calc":"iteracoesBissecao","a":0,"b":1,"eps":0.01}', 'k > (log(1) − log(0,01))/log 2 = 6,6439, então k = 7.', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('sl-bis-k', 'A', '6', 0, 'k precisa ser o primeiro inteiro maior que (log(b₀ − a₀) − log ε)/log 2: arredondar para baixo deixa b − a ainda maior que ε.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('sl-bis-k', 'B', '8', 0, 'Uma a mais do que o necessário: k é o primeiro inteiro acima do limite.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('sl-bis-k', 'C', '10', 0, 'Confira a conta: k > (log(b₀ − a₀) − log ε)/log 2.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('sl-bis-k', 'D', '7', 1, NULL);
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('sl-bis-x1', 'slides', '', 'Cap. 3 — Raízes de Equações', 'bissecao', 1, 'numero', 1, NULL, 'Exemplo 05 dos slides: f(x) = x³ − 9x + 3 em [0, 1]. Qual é x₁ da Bisseção?', NULL, '0,50', 0.5, NULL, NULL, NULL, NULL, 2, NULL, '{"calc":"bissecao","f":"x^3-9x+3","a":0,"b":1,"iteracoes":1}', 'Bisseção: 1 iteração; x = 0,500000. 1 iteração, como pedido.
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('sl-bis-x1', 'A', '0,38', 0, 'Esse valor sai da Falsa Posição (média ponderada pelos valores de f). A Bisseção usa o valor médio xᵢ = (aᵢ + bᵢ)/2.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('sl-bis-x1', 'B', '0,47', 0, 'Não confere: refaça a conta passo a passo (veja a resolução).');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('sl-bis-x1', 'C', '0,50', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('sl-bis-x1', 'D', '0,25', 0, 'Esse é o resultado com 2 iterações: uma a mais do que o pedido.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('sl-bis-novo', 'slides', '', 'Cap. 3 — Raízes de Equações', 'bissecao', 1, 'texto', 1, NULL, 'Exemplo 05: f(x) = x³ − 9x + 3 em [0, 1]. Com x₁ = 0,5 e f(0,5) = −1,375 < 0, quais são os novos extremos?', NULL, 'a₂ = 0 e b₂ = 0,5', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"f(0) = 3 > 0 e f(0,5) < 0: a troca de sinal está em [0; 0,5]. Então a₂ = 0 e b₂ = x₁ = 0,5."}', 'f(0) = 3 > 0 e f(0,5) < 0: a troca de sinal está em [0; 0,5]. Então a₂ = 0 e b₂ = x₁ = 0,5.', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('sl-bis-novo', 'A', 'a₂ = 0,5 e b₂ = 1', 0, 'f(0,5) e f(1) são ambos negativos: ali não há troca de sinal.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('sl-bis-novo', 'B', 'a₂ = 0 e b₂ = 0,5', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('sl-bis-novo', 'C', 'a₂ = 0,25 e b₂ = 0,75', 0, 'Os novos extremos são um extremo antigo e o próprio x₁.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('sl-bis-novo', 'D', 'a₂ = 0 e b₂ = 1', 0, 'O intervalo precisa diminuir a cada iteração.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('sl-fp-formula', 'slides', '', 'Cap. 3 — Raízes de Equações', 'falsa-posicao', 1, 'texto', 1, NULL, 'Na Falsa Posição, o intervalo é dividido por qual ponto?', NULL, 'xᵢ = (aᵢ·f(bᵢ) − bᵢ·f(aᵢ)) / (f(bᵢ) − f(aᵢ))', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"Uma média aritmética ponderada que leva em conta o valor da função nos extremos: é onde a reta entre (a, f(a)) e (b, f(b)) corta o eixo x. O resto do algoritmo é igual ao da Bisseção."}', 'Uma média aritmética ponderada que leva em conta o valor da função nos extremos: é onde a reta entre (a, f(a)) e (b, f(b)) corta o eixo x. O resto do algoritmo é igual ao da Bisseção.', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('sl-fp-formula', 'A', 'xᵢ₊₁ = g(xᵢ)', 0, 'Essa é a iteração de ponto fixo.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('sl-fp-formula', 'B', 'xᵢ = (aᵢ·f(bᵢ) − bᵢ·f(aᵢ)) / (f(bᵢ) − f(aᵢ))', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('sl-fp-formula', 'C', 'xᵢ = (aᵢ·f(aᵢ) + bᵢ·f(bᵢ)) / (f(aᵢ) + f(bᵢ))', 0, 'Os pesos estão trocados e os sinais errados.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('sl-fp-formula', 'D', 'xᵢ = (aᵢ + bᵢ)/2', 0, 'Esse é o valor médio da Bisseção.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('sl-fp-x1', 'slides', '', 'Cap. 3 — Raízes de Equações', 'falsa-posicao', 1, 'numero', 1, NULL, 'Exemplo 06 dos slides: f(x) = x³ − 9x + 3 em [0, 1]. Qual é x₁ da Falsa Posição?', NULL, '0,375', 0.375, NULL, NULL, NULL, NULL, 3, NULL, '{"calc":"falsaPosicao","f":"x^3-9x+3","a":0,"b":1,"iteracoes":1}', 'Falsa Posição: 1 iteração; x = 0,375000. 1 iteração, como pedido.
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('sl-fp-x1', 'A', '0,500', 0, 'Esse valor sai da Bisseção (valor médio). A Falsa Posição usa xᵢ = (aᵢ·f(bᵢ) − bᵢ·f(aᵢ)) / (f(bᵢ) − f(aᵢ)).');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('sl-fp-x1', 'B', '0,339', 0, 'Esse é o resultado com 2 iterações: uma a mais do que o pedido.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('sl-fp-x1', 'C', '0,390', 0, 'Não confere: refaça a conta passo a passo (veja a resolução).');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('sl-fp-x1', 'D', '0,375', 1, NULL);
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('sl-fp-vs-bis', 'slides', '', 'Cap. 3 — Raízes de Equações', 'falsa-posicao', 1, 'texto', 1, NULL, 'No mesmo problema (x³ − 9x + 3 em [0, 1], ε = 10⁻²), o que os slides concluem ao comparar Bisseção e Falsa Posição?', NULL, 'A Falsa Posição converge mais rápido (4 iterações contra 9)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"A Bisseção precisou de 9 iterações e a Falsa Posição chegou a x₄ = 0,33761 em 4. A Bisseção tem convergência linear (p = 1)."}', 'A Bisseção precisou de 9 iterações e a Falsa Posição chegou a x₄ = 0,33761 em 4. A Bisseção tem convergência linear (p = 1).', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('sl-fp-vs-bis', 'A', 'A Falsa Posição converge mais rápido (4 iterações contra 9)', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('sl-fp-vs-bis', 'B', 'As duas levam o mesmo número de iterações', 0, 'A Falsa Posição usa os valores de f e chega antes.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('sl-fp-vs-bis', 'C', 'A Falsa Posição diverge nesse exemplo', 0, 'Ela é intervalar: com f(a)·f(b) < 0 a raiz fica sempre cercada.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('sl-fp-vs-bis', 'D', 'A Bisseção converge mais rápido', 0, 'No exemplo dos slides a Bisseção levou 9 iterações.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('sl-ea', 'slides', '', 'Cap. 3 — Raízes de Equações', 'newton', 1, 'texto', 1, NULL, 'Qual é o erro relativo aproximado usado como critério de parada nos slides?', NULL, 'εₐ = |(x_novo − x_velho)/x_novo| × 100%', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"Compara a aproximação nova com a anterior, relativa à nova: εₐ = |(xᵢ₊₁ − xᵢ)/xᵢ₊₁| × 100%. Para quando εₐ < ε (ou quando atinge o número máximo de iterações)."}', 'Compara a aproximação nova com a anterior, relativa à nova: εₐ = |(xᵢ₊₁ − xᵢ)/xᵢ₊₁| × 100%. Para quando εₐ < ε (ou quando atinge o número máximo de iterações).', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('sl-ea', 'A', 'εₐ = |(x_novo − x_velho)/x_velho| × 100%', 0, 'O denominador é a aproximação nova (a melhor que temos).');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('sl-ea', 'B', 'εₐ = |f(x_novo)|', 0, 'Esse é o resíduo; o estimador dos slides compara duas aproximações.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('sl-ea', 'C', 'εₐ = |(x_novo − x_velho)/x_novo| × 100%', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('sl-ea', 'D', 'εₐ = |x_novo − x_velho| × 100%', 0, 'Esse é o erro absoluto (em %), sem dividir pela aproximação.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('sl-nr-formula', 'slides', '', 'Cap. 3 — Raízes de Equações', 'newton', 1, 'texto', 1, NULL, 'Qual é a fórmula do Newton-Raphson, obtida prolongando a tangente em xᵢ até o eixo x?', NULL, 'xᵢ₊₁ = xᵢ − f(xᵢ)/f′(xᵢ)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"Da reta tangente: f′(xᵢ) = (f(xᵢ) − 0)/(xᵢ − xᵢ₊₁). Reorganizando: xᵢ₊₁ = xᵢ − f(xᵢ)/f′(xᵢ)."}', 'Da reta tangente: f′(xᵢ) = (f(xᵢ) − 0)/(xᵢ − xᵢ₊₁). Reorganizando: xᵢ₊₁ = xᵢ − f(xᵢ)/f′(xᵢ).', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('sl-nr-formula', 'A', 'xᵢ₊₁ = xᵢ − f(xᵢ)/f′(xᵢ)', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('sl-nr-formula', 'B', 'xᵢ₊₁ = xᵢ − f′(xᵢ)/f(xᵢ)', 0, 'A fração está invertida.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('sl-nr-formula', 'C', 'xᵢ₊₁ = xᵢ + f(xᵢ)/f′(xᵢ)', 0, 'O sinal é de menos: andamos contra a inclinação para chegar ao zero.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('sl-nr-formula', 'D', 'xᵢ₊₁ = xᵢ − f(xᵢ)(xᵢ − xᵢ₋₁)/(f(xᵢ) − f(xᵢ₋₁))', 0, 'Essa é a Secante, que troca f′ por uma diferença finita.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('sl-nr-x1', 'slides', '', 'Cap. 3 — Raízes de Equações', 'newton', 1, 'numero', 1, NULL, 'Exemplo 5 dos slides: f(x) = e⁻ˣ − x com x₀ = 0. Qual é x₁ pelo Newton-Raphson?', NULL, '0,50', 0.5, NULL, NULL, NULL, NULL, 2, NULL, '{"calc":"newton","f":"exp(-x)-x","df":"-exp(-x)-1","x0":0,"iteracoes":1}', 'Newton-Raphson: 1 iteração; x = 0,500000. 1 iterações, como pedido.
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('sl-nr-x1', 'A', '0,53', 0, 'Não confere: refaça a conta passo a passo (veja a resolução).');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('sl-nr-x1', 'B', '0,57', 0, 'Esse é o resultado com 2 iterações: uma a mais do que o pedido.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('sl-nr-x1', 'C', '−0,50', 0, 'Sinal trocado na fórmula: o certo é xᵢ₊₁ = xᵢ − f(xᵢ)/f′(xᵢ).');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('sl-nr-x1', 'D', '0,50', 1, NULL);
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('sl-nr-desv', 'slides', '', 'Cap. 3 — Raízes de Equações', 'newton', 1, 'texto', 1, NULL, 'Qual destas situações está entre as desvantagens do Newton-Raphson mostradas nos slides?', NULL, 'f′(xᵢ) = 0 ou perto de zero: a tangente fica horizontal e o passo explode', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"Os slides mostram casos de convergência muito lenta, de oscilação em torno de um mínimo local e o \"desastre\" quando f′(xᵣ) = 0: a tangente horizontal nunca corta o eixo x."}', 'Os slides mostram casos de convergência muito lenta, de oscilação em torno de um mínimo local e o "desastre" quando f′(xᵣ) = 0: a tangente horizontal nunca corta o eixo x.', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('sl-nr-desv', 'A', 'Precisa de duas aproximações iniciais', 0, 'Quem precisa de duas é a Secante.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('sl-nr-desv', 'B', 'Tem convergência linear', 0, 'Newton tem convergência quadrática (p = 2).');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('sl-nr-desv', 'C', 'f′(xᵢ) = 0 ou perto de zero: a tangente fica horizontal e o passo explode', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('sl-nr-desv', 'D', 'Precisa que f(a)·f(b) < 0', 0, 'Essa exigência é dos métodos intervalares.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('sl-sec-ordem', 'slides', '', 'Cap. 3 — Raízes de Equações', 'secante', 1, 'texto', 1, NULL, 'Qual é a ordem de convergência da Secante, segundo os slides?', NULL, 'p = 1,618', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"A Secante tem p = 1,618: maior que a dos métodos de convergência linear (p = 1) e menor que a do Newton-Raphson (p = 2)."}', 'A Secante tem p = 1,618: maior que a dos métodos de convergência linear (p = 1) e menor que a do Newton-Raphson (p = 2).', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('sl-sec-ordem', 'A', 'p = 3', 0, 'Nenhum dos métodos do capítulo chega a p = 3.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('sl-sec-ordem', 'B', 'p = 2', 0, 'p = 2 é a do Newton-Raphson.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('sl-sec-ordem', 'C', 'p = 1,618', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('sl-sec-ordem', 'D', 'p = 1', 0, 'p = 1 é a convergência linear (como a da Bisseção).');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('sl-sec-x2', 'slides', '', 'Cap. 3 — Raízes de Equações', 'secante', 1, 'numero', 1, NULL, 'Exemplo 7 dos slides: f(x) = e⁻ˣ − x com x₀ = 0 e x₁ = 1. Qual é x₂ pela Secante?', NULL, '0,6127', 0.61269983678, NULL, NULL, NULL, NULL, 4, NULL, '{"calc":"secante","f":"exp(-x)-x","x0":0,"x1":1,"iteracoes":1}', 'Secante: 1 iteração; x = 0,612700. 1 iterações, como pedido.
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('sl-sec-x2', 'A', '0,6678', 0, 'Não confere: refaça a conta passo a passo (veja a resolução).');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('sl-sec-x2', 'B', '0,6127', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('sl-sec-x2', 'C', '0,5882', 0, 'Não confere: refaça a conta passo a passo (veja a resolução).');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('sl-sec-x2', 'D', '0,5638', 0, 'Esse é o resultado com 2 iterações: uma a mais do que o pedido.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('sl-sec-vs-fp', 'slides', '', 'Cap. 3 — Raízes de Equações', 'secante', 1, 'texto', 1, NULL, 'Qual a diferença entre a Secante e a Falsa Posição?', NULL, 'A Secante usa sempre os dois últimos pontos, sem exigir troca de sinal; a Falsa Posição mantém a raiz cercada', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"As duas usam a reta entre dois pontos, mas a Falsa Posição é intervalar (guarda o par com f(a)·f(b) < 0) e a Secante é aberta: usa xᵢ₋₁ e xᵢ, mesmo que tenham o mesmo sinal."}', 'As duas usam a reta entre dois pontos, mas a Falsa Posição é intervalar (guarda o par com f(a)·f(b) < 0) e a Secante é aberta: usa xᵢ₋₁ e xᵢ, mesmo que tenham o mesmo sinal.', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('sl-sec-vs-fp', 'A', 'São o mesmo método com nomes diferentes', 0, 'A escolha dos pontos muda: uma é intervalar, a outra é aberta.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('sl-sec-vs-fp', 'B', 'A Falsa Posição usa o ponto médio', 0, 'O ponto médio é da Bisseção.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('sl-sec-vs-fp', 'C', 'A Secante usa a derivada exata', 0, 'A Secante troca a derivada por uma diferença finita.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('sl-sec-vs-fp', 'D', 'A Secante usa sempre os dois últimos pontos, sem exigir troca de sinal; a Falsa Posição mantém a raiz cercada', 1, NULL);
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('sl-op-elem', 'slides', '', 'Cap. 2 — Sistemas de Equações: Métodos Diretos', 'gauss', 1, 'texto', 1, NULL, 'Qual destas NÃO é uma das operações elementares do teorema dos slides (que não mudam a solução de AX = B)?', NULL, 'Multiplicar uma equação por zero', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"As operações são: multiplicar Eᵢ por λ ≠ 0; somar a Eᵢ um múltiplo λ de Eⱼ; trocar Eᵢ e Eⱼ de posição. Multiplicar por zero apaga a equação e muda o sistema."}', 'As operações são: multiplicar Eᵢ por λ ≠ 0; somar a Eᵢ um múltiplo λ de Eⱼ; trocar Eᵢ e Eⱼ de posição. Multiplicar por zero apaga a equação e muda o sistema.', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('sl-op-elem', 'A', 'Trocar Eᵢ e Eⱼ de posição', 0, 'Essa é a 3ª operação elementar.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('sl-op-elem', 'B', 'Multiplicar Eᵢ por λ ≠ 0', 0, 'Essa é a 1ª operação elementar.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('sl-op-elem', 'C', 'Multiplicar uma equação por zero', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('sl-op-elem', 'D', 'Somar a Eᵢ o múltiplo λ·Eⱼ', 0, 'Essa é a 2ª operação elementar.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('sl-pivo', 'slides', '', 'Cap. 2 — Sistemas de Equações: Métodos Diretos', 'gauss', 1, 'texto', 1, NULL, 'Para a professora, o que é o pivô na Eliminação de Gauss?', NULL, 'O primeiro elemento não nulo de cada equação (linha)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"Pivô é o primeiro elemento não nulo de cada equação; a linha que o contém é a equação pivô. O objetivo da eliminação é zerar os coeficientes abaixo de cada pivô."}', 'Pivô é o primeiro elemento não nulo de cada equação; a linha que o contém é a equação pivô. O objetivo da eliminação é zerar os coeficientes abaixo de cada pivô.', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('sl-pivo', 'A', 'O termo independente bᵢ', 0, 'O pivô está na matriz dos coeficientes.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('sl-pivo', 'B', 'O maior elemento da matriz', 0, 'O maior |aᵢₖ| da coluna é o critério do pivoteamento parcial, não a definição de pivô.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('sl-pivo', 'C', 'O determinante de A', 0, 'O determinante é o produto dos pivôs, mas não é o pivô.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('sl-pivo', 'D', 'O primeiro elemento não nulo de cada equação (linha)', 1, NULL);
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('sl-m31', 'slides', '', 'Cap. 2 — Sistemas de Equações: Métodos Diretos', 'gauss', 1, 'numero', 1, NULL, 'Exemplo 1 dos slides: A = [3 2 4; 1 1 2; 4 3 −2]. Na Etapa 1, qual é o multiplicador m₃₁?', NULL, '1,3333', 1.33333333333, NULL, NULL, NULL, NULL, 4, NULL, '{"calc":"gauss-multiplicador","A":[[3,2,4],[1,1,2],[4,3,-2]],"i":3,"k":1}', 'm₃₁ = a₃₁/a₁₁ = 4/3 = 1,3333.', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('sl-m31', 'A', '−1,3333', 0, 'Sinal trocado: mᵢₖ = aᵢₖ/aₖₖ, e a operação é Eᵢ − mᵢₖEₖ.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('sl-m31', 'B', '0,7500', 0, 'Fração invertida: mᵢₖ = aᵢₖ/aₖₖ (o pivô fica no denominador).');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('sl-m31', 'C', '1,3867', 0, 'Não confere: refaça a conta passo a passo (veja a resolução).');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('sl-m31', 'D', '1,3333', 1, NULL);
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('sl-ex1', 'slides', '', 'Cap. 2 — Sistemas de Equações: Métodos Diretos', 'gauss', 2, 'vetor', 0, NULL, 'Exemplo 1 dos slides: 3x₁ + 2x₂ + 4x₃ = 1; x₁ + x₂ + 2x₃ = 2; 4x₁ + 3x₂ − 2x₃ = 3. Qual é a solução pela Eliminação de Gauss?', NULL, '(−3,00; 5,00; 0,00)', NULL, NULL, '[-3,5,0]', NULL, NULL, 2, NULL, '{"calc":"gauss","A":[[3,2,4],[1,1,2],[4,3,-2]],"b":[1,2,3]}', 'Solução: X* = (−3; 5; 0). −8x₃ = 0 ⇒ x₃ = 0; (1/3)x₂ + (2/3)·0 = 5/3 ⇒ x₂ = 5; 3x₁ + 2·5 + 4·0 = 1 ⇒ x₁ = −3', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('sl-ex1', 'A', '(−3,36; 5,00; 0,00)', 0, 'A primeira componente não confere: refaça a conta.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('sl-ex1', 'B', '(5,00; −3,00; 0,00)', 0, 'Componentes trocadas de posição.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('sl-ex1', 'C', '(−3,00; 5,00; 0,00)', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('sl-ex1', 'D', '(−2,70; 4,50; −0,05)', 0, 'Não confere: refaça a conta passo a passo.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('sl-regressiva', 'slides', '', 'Cap. 2 — Sistemas de Equações: Métodos Diretos', 'gauss', 1, 'texto', 1, NULL, 'Depois da eliminação, por qual equação começa a substituição regressiva?', NULL, 'Pela última: xₙ = bₙ⁽ⁿ⁻¹⁾/aₙₙ⁽ⁿ⁻¹⁾', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"O sistema ficou triangular superior. A última equação tem só xₙ; o valor é substituído na (n − 1)-ésima para achar xₙ₋₁, e assim por diante."}', 'O sistema ficou triangular superior. A última equação tem só xₙ; o valor é substituído na (n − 1)-ésima para achar xₙ₋₁, e assim por diante.', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('sl-regressiva', 'A', 'Pela última: xₙ = bₙ⁽ⁿ⁻¹⁾/aₙₙ⁽ⁿ⁻¹⁾', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('sl-regressiva', 'B', 'Por qualquer uma, a ordem não importa', 0, 'Só a última tem uma incógnita sozinha.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('sl-regressiva', 'C', 'Pela equação com o maior pivô', 0, 'A ordem é fixa: de baixo para cima.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('sl-regressiva', 'D', 'Pela primeira: x₁ = b₁/a₁₁', 0, 'Na primeira equação ainda aparecem todas as incógnitas.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('sl-pivoteamento', 'slides', '', 'Cap. 2 — Sistemas de Equações: Métodos Diretos', 'pivoteamento', 1, 'texto', 1, NULL, 'Por que usar o pivoteamento parcial?', NULL, 'Pivôs próximos de zero geram multiplicadores grandes, que ampliam os erros de arredondamento', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"Escolhendo como pivô o maior |aᵢₖ| da coluna, todos os multiplicadores ficam com |mᵢₖ| ≤ 1 e os erros de arredondamento não são ampliados."}', 'Escolhendo como pivô o maior |aᵢₖ| da coluna, todos os multiplicadores ficam com |mᵢₖ| ≤ 1 e os erros de arredondamento não são ampliados.', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('sl-pivoteamento', 'A', 'Para dispensar a substituição regressiva', 0, 'A substituição regressiva continua necessária.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('sl-pivoteamento', 'B', 'Para deixar a matriz simétrica', 0, 'A troca de linhas não torna a matriz simétrica.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('sl-pivoteamento', 'C', 'Para a matriz ficar diagonal', 0, 'A eliminação continua produzindo uma triangular superior.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('sl-pivoteamento', 'D', 'Pivôs próximos de zero geram multiplicadores grandes, que ampliam os erros de arredondamento', 1, NULL);
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('sl-singular', 'slides', '', 'Cap. 2 — Sistemas de Equações: Métodos Diretos', 'gauss', 1, 'texto', 1, NULL, 'Nos slides, sistemas singulares aparecem graficamente como retas paralelas ou coincidentes. O que cada caso significa?', NULL, 'Paralelas: nenhuma solução; coincidentes: infinitas soluções', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"Duas retas paralelas nunca se cruzam (sistema sem solução); retas coincidentes se cruzam em todos os pontos (infinitas soluções). Retas quase paralelas formam um sistema mal condicionado."}', 'Duas retas paralelas nunca se cruzam (sistema sem solução); retas coincidentes se cruzam em todos os pontos (infinitas soluções). Retas quase paralelas formam um sistema mal condicionado.', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('sl-singular', 'A', 'As duas têm solução única', 0, 'Solução única é quando as retas se cruzam em um ponto só.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('sl-singular', 'B', 'Paralelas: nenhuma solução; coincidentes: infinitas soluções', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('sl-singular', 'C', 'Paralelas: sistema mal condicionado', 0, 'Mal condicionado é quando as inclinações são muito próximas, mas não iguais.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('sl-singular', 'D', 'Paralelas: infinitas soluções; coincidentes: nenhuma', 0, 'Está trocado.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('t1-bisseccao', 'teste-1', 'Questão 01', 'Teste 1', 'bissecao', 3, 'numero', 0, NULL, 'O método da bisseção foi usado para determinar o zero da função f(x) = x⁴ − 7x + 4 no intervalo inicial [0,5; 0,7]. Na 1ª iteração, foi obtida a aproximação x₁ = 0,600000, e o intervalo para a próxima iteração passou a ser [a, b] = [0,500000; 0,600000]. Continue os cálculos a partir da 2ª iteração e, após cada iteração, determine o erro relativo percentual (o primeiro erro usa a última aproximação fornecida). Use 6 casas decimais nos cálculos e 2 casas decimais no erro relativo percentual. Considere N = 15 e ε = 0,1%. Qual é a raiz aproximada?', NULL, '0,588673', 0.588673, NULL, NULL, NULL, NULL, 6, 0.000001, '{"calc":"bissecao","f":"x^4-7x+4","a":0.5,"b":0.6,"eps":0.1,"K":15,"criterio":"percentual","casas":6,"inicio":2,"anterior":0.6}', 'Bisseção: da 2ª à 9ª iteração; x = 0,588673. Na 9ª iteração o erro estimado é menor que o critério de parada: 0,0664206 ≤ 0,1.
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t1-bisseccao', 'A', '0,588673', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t1-bisseccao', 'B', '0,575000', 0, 'Parou cedo demais: com 2 iterações o erro ainda está bem acima de ε.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t1-bisseccao', 'C', '0,588572', 0, 'Esse valor sai da Falsa Posição (média ponderada pelos valores de f). A Bisseção usa o valor médio xᵢ = (aᵢ + bᵢ)/2.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t1-bisseccao', 'D', '0,587500', 0, 'Parou cedo demais: com 3 iterações o critério de parada ainda não foi atingido.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('t1-bisseccao-pratica', 'teste-1', 'Questão 01 (prática)', 'Teste 1', 'bissecao', 2, 'numero', 0, NULL, 'Use o método da bisseção para determinar uma aproximação de um zero de f(x) = x⁴ − 7x + 4 no intervalo inicial [0,58; 0,6], começando na 1ª iteração pelo ponto médio. A partir da 2ª iteração, calcule o erro relativo percentual entre a aproximação atual e a anterior. Use 6 casas decimais nos cálculos e 2 casas decimais no erro relativo percentual. Considere N = 6 e ε = 0,1%. Qual é a raiz aproximada?', '0,588438', '0,588438', 0.588438, 0.588438, NULL, NULL, NULL, 6, 0.000001, '{"calc":"bissecao","f":"x^4-7x+4","a":0.58,"b":0.6,"eps":0.1,"K":6,"criterio":"percentual","casas":6}', 'Bisseção: 6 iterações; x = 0,588438. Na 6ª iteração o erro estimado é menor que o critério de parada: 0,0531917 ≤ 0,1.
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t1-bisseccao-pratica', 'A', '0,588438', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t1-bisseccao-pratica', 'B', '0,587500', 0, 'Parou cedo demais: com 3 iterações o critério de parada ainda não foi atingido.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t1-bisseccao-pratica', 'C', '0,588572', 0, 'Esse valor sai da Falsa Posição (média ponderada pelos valores de f). A Bisseção usa o valor médio xᵢ = (aᵢ + bᵢ)/2.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t1-bisseccao-pratica', 'D', '0,585000', 0, 'Parou cedo demais: com 2 iterações o erro ainda está bem acima de ε.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('t1-bisseccao-4', 'teste-1', 'Questão 01 (4 iterações)', 'Teste 1', 'bissecao', 2, 'numero', 0, NULL, 'Teste 1: bisseção em f(x) = x⁴ − 7x + 4, no intervalo [0,58; 0,6]. Faça 4 iterações com 6 casas decimais. Qual é x₄?', NULL, '0,588750', 0.58875, NULL, NULL, NULL, NULL, 6, 0.000001, '{"calc":"bissecao","f":"x^4-7x+4","a":0.58,"b":0.6,"iteracoes":4,"casas":6}', 'Bisseção: 4 iterações; x = 0,588750. 4 iterações, como pedido.
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t1-bisseccao-4', 'A', '0,588750', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t1-bisseccao-4', 'B', '0,588572', 0, 'Esse valor sai da Falsa Posição (média ponderada pelos valores de f). A Bisseção usa o valor médio xᵢ = (aᵢ + bᵢ)/2.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t1-bisseccao-4', 'C', '0,588125', 0, 'Esse é o resultado com 5 iterações: uma a mais do que o pedido.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t1-bisseccao-4', 'D', '0,587500', 0, 'Esse é o resultado com 3 iterações: faltou uma.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('t1-newton', 'teste-1', 'Questão 03', 'Teste 1', 'newton', 3, 'numero', 0, NULL, 'Use o método de Newton-Raphson para determinar uma aproximação de um zero de f(x) = x·e⁻ˣ − 0,25, considerando x₀ = 2. Determine a derivada. Use 8 casas decimais nos cálculos (f(xᵢ) e f′(xᵢ) arredondados a 8 casas) e 6 casas no erro relativo percentual. Considere K = 15 e ε = 10⁻⁴%. Qual é a raiz aproximada?', '2,15329235', '2,15329235', 2.15329235, 2.15329235, NULL, NULL, NULL, 8, 2e-8, '{"calc":"newton","f":"x*exp(-x)-0.25","df":"(1-x)*exp(-x)","x0":2,"eps":0.0001,"K":15,"criterio":"percentual","casas":8}', 'Newton-Raphson: 3 iterações; x = 2,15329235. O método convergiu na 3ª iteração: εₐ = 0% ≤ ε = 0,0001.
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t1-newton', 'A', '2,34708866', 0, 'Não confere: refaça a conta passo a passo (veja a resolução).');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t1-newton', 'B', '0,84364272', 0, 'Sinal trocado na fórmula: o certo é xᵢ₊₁ = xᵢ − f(xᵢ)/f′(xᵢ).');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t1-newton', 'C', '2,15329235', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t1-newton', 'D', '2,06716066', 0, 'Não confere: refaça a conta passo a passo (veja a resolução).');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('t1-newton-2', 'teste-1', 'Newton (2 iterações)', 'Teste 1', 'newton', 2, 'numero', 0, NULL, 'Teste 1: Newton-Raphson em f(x) = x·e⁻ˣ − 0,25, com f′(x) = (1 − x)·e⁻ˣ e x₀ = 2. Faça 2 iterações com 8 casas decimais. Qual é x₂?', NULL, '2,153292', 2.15329235, NULL, NULL, NULL, NULL, 6, 0.000002, '{"calc":"newton","f":"x*exp(-x)-0.25","df":"(1-x)*exp(-x)","x0":2,"iteracoes":2,"casas":8}', 'Newton-Raphson: 2 iterações; x = 2,15329235. 2 iterações, como pedido.
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t1-newton-2', 'A', '2,239424', 0, 'Não confere: refaça a conta passo a passo (veja a resolução).');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t1-newton-2', 'B', '1,538443', 0, 'Sinal trocado na fórmula: o certo é xᵢ₊₁ = xᵢ − f(xᵢ)/f′(xᵢ).');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t1-newton-2', 'C', '2,152736', 0, 'Esse é o resultado com 1 iteração: faltou uma.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t1-newton-2', 'D', '2,153292', 1, NULL);
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('t1-derivada', 'teste-1', 'Newton: derivada', 'Teste 1', 'newton', 1, 'texto', 1, NULL, 'Teste 1: para aplicar Newton-Raphson em f(x) = x·e⁻ˣ − 0,25, qual é a derivada?', NULL, 'f′(x) = (1 − x)·e⁻ˣ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"Regra do produto: (x·e⁻ˣ)′ = 1·e⁻ˣ + x·(−e⁻ˣ) = (1 − x)·e⁻ˣ. A constante tem derivada zero."}', 'Regra do produto: (x·e⁻ˣ)′ = 1·e⁻ˣ + x·(−e⁻ˣ) = (1 − x)·e⁻ˣ. A constante tem derivada zero.', NULL, 0, 'azul', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t1-derivada', 'A', 'f′(x) = (1 − x)·e⁻ˣ', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t1-derivada', 'B', 'f′(x) = e⁻ˣ − 0,25', 0, 'A constante some na derivada, e falta o termo x·(−e⁻ˣ).');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t1-derivada', 'C', 'f′(x) = (1 + x)·e⁻ˣ', 0, 'A derivada de e⁻ˣ é −e⁻ˣ: o termo x·(−e⁻ˣ) entra com sinal de menos.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t1-derivada', 'D', 'f′(x) = −x·e⁻ˣ', 0, 'Regra do produto: falta o termo 1·e⁻ˣ.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('t1-gauss', 'teste-1', 'Questão 02', 'Teste 1', 'gauss', 2, 'vetor', 0, NULL, 'Teste 1: resolva o sistema 6x₁ + 2x₂ + x₃ = 5; 3x₁ + x₂ + 5x₃ = 16; x₁ + 3x₂ + 2x₃ = 1 pelo método de Eliminação de Gauss, com pivoteamento parcial se necessário. Qual é (x₁; x₂; x₃)?', '(1; −2; 3)', '(1; −2; 3)', NULL, NULL, '[1,-2,3]', '[1,-2,3]', NULL, 0, 0.01, '{"calc":"gauss","A":[[6,2,1],[3,1,5],[1,3,2]],"b":[5,16,1],"pivoteamento":"nenhum"}', 'Solução: X* = (1; −2; 3). (9/2)x₃ = 27/2 ⇒ x₃ = 3; (8/3)x₂ + (11/6)·3 = 1/6 ⇒ x₂ = −2; 6x₁ + 2·(−2) + 1·3 = 5 ⇒ x₁ = 1', NULL, 0, 'azul', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t1-gauss', 'A', '(6; −7; 8)', 0, 'Não confere: refaça a conta passo a passo (veja a resolução).');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t1-gauss', 'B', '(1; −2; 3)', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t1-gauss', 'C', '(1; −2; −3)', 0, 'Sinal da última componente trocado.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t1-gauss', 'D', '(−2; 1; 3)', 0, 'Componentes trocadas de posição.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('t2-bisseccao', 'teste-2', 'Questão 01', 'Teste 2', 'bissecao', 3, 'numero', 0, NULL, 'O método da bisseção foi usado para determinar o zero da função f(x) = 2,8 − 4e⁻ˣ − x no intervalo inicial [0,4; 0,8]. Na 3ª iteração, foi obtida a aproximação x₃ = 0,550000, e o intervalo para a próxima iteração passou a ser [a, b] = [0,550000; 0,600000]. Continue os cálculos a partir da 4ª iteração e, após cada iteração, determine o erro relativo percentual (o primeiro erro usa a última aproximação fornecida). Use 6 casas decimais nos cálculos e 2 casas decimais no erro relativo percentual. Considere N = 15 e ε = 0,1%. Qual é a raiz aproximada?', NULL, '0,595704', 0.595704, NULL, NULL, NULL, NULL, 6, 0.000001, '{"calc":"bissecao","f":"2.8-4exp(-x)-x","a":0.55,"b":0.6,"eps":0.1,"K":15,"criterio":"percentual","casas":6,"inicio":4,"anterior":0.55}', 'Bisseção: da 4ª à 10ª iteração; x = 0,595704. Na 10ª iteração o erro estimado é menor que o critério de parada: 0,0654688 ≤ 0,1.
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t2-bisseccao', 'A', '0,587500', 0, 'Parou cedo demais: com 2 iterações o erro ainda está bem acima de ε.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t2-bisseccao', 'B', '0,596038', 0, 'Esse valor sai da Falsa Posição (média ponderada pelos valores de f). A Bisseção usa o valor médio xᵢ = (aᵢ + bᵢ)/2.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t2-bisseccao', 'C', '0,593750', 0, 'Parou cedo demais: com 3 iterações o critério de parada ainda não foi atingido.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t2-bisseccao', 'D', '0,595704', 1, NULL);
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('t2-bisseccao-pratica', 'teste-2', 'Questão 01 (prática)', 'Teste 2', 'bissecao', 2, 'numero', 0, NULL, 'Use o método da bisseção para determinar uma aproximação de um zero de f(x) = 2,8 − 4e⁻ˣ − x no intervalo inicial [0,59; 0,61], começando na 1ª iteração pelo ponto médio. A partir da 2ª iteração, calcule o erro relativo percentual entre a aproximação atual e a anterior. Use 6 casas decimais nos cálculos e 2 casas decimais no erro relativo percentual. Considere N = 6 e ε = 0,1%. Qual é a raiz aproximada?', '0,595938', '0,595938', 0.595938, 0.595938, NULL, NULL, NULL, 6, 0.000001, '{"calc":"bissecao","f":"2.8-4exp(-x)-x","a":0.59,"b":0.61,"eps":0.1,"K":6,"criterio":"percentual","casas":6}', 'Bisseção: 6 iterações; x = 0,595938. Na 6ª iteração o erro estimado é menor que o critério de parada: 0,0525222 ≤ 0,1.
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t2-bisseccao-pratica', 'A', '0,595938', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t2-bisseccao-pratica', 'B', '0,597500', 0, 'Parou cedo demais: com 3 iterações o critério de parada ainda não foi atingido.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t2-bisseccao-pratica', 'C', '0,596038', 0, 'Esse valor sai da Falsa Posição (média ponderada pelos valores de f). A Bisseção usa o valor médio xᵢ = (aᵢ + bᵢ)/2.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t2-bisseccao-pratica', 'D', '0,595000', 0, 'Parou cedo demais: com 2 iterações o erro ainda está bem acima de ε.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('t2-bisseccao-4', 'teste-2', 'Questão 01 (4 iterações)', 'Teste 2', 'bissecao', 2, 'numero', 0, NULL, 'Teste 2: bisseção em f(x) = 2,8 − 4e⁻ˣ − x, no intervalo [0,59; 0,61]. Faça 4 iterações com 6 casas decimais. Qual é x₄?', NULL, '0,596250', 0.59625, NULL, NULL, NULL, NULL, 6, 0.000001, '{"calc":"bissecao","f":"2.8-4exp(-x)-x","a":0.59,"b":0.61,"iteracoes":4,"casas":6}', 'Bisseção: 4 iterações; x = 0,596250. 4 iterações, como pedido.
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t2-bisseccao-4', 'A', '0,596250', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t2-bisseccao-4', 'B', '0,596038', 0, 'Esse valor sai da Falsa Posição (média ponderada pelos valores de f). A Bisseção usa o valor médio xᵢ = (aᵢ + bᵢ)/2.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t2-bisseccao-4', 'C', '0,597500', 0, 'Esse é o resultado com 3 iterações: faltou uma.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t2-bisseccao-4', 'D', '0,595625', 0, 'Esse é o resultado com 5 iterações: uma a mais do que o pedido.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('t2-newton', 'teste-2', 'Questão 02 (b)', 'Teste 2', 'newton', 3, 'numero', 0, NULL, 'Use o método de Newton-Raphson para determinar uma aproximação de um zero de f(x) = e⁻²ˣ² − cos x, considerando x₀ = 1,5 (calculadora em radianos). Determine a derivada. Use 8 casas decimais nos cálculos (f(xᵢ) e f′(xᵢ) arredondados a 8 casas) e 6 casas no erro relativo percentual. Considere K = 15 e ε = 10⁻⁴%. Qual é a raiz aproximada?', '1,56325632', '1,56325632', 1.56325632, 1.56325632, NULL, NULL, NULL, 8, 2e-8, '{"calc":"newton","f":"exp(-2x^2)-cos(x)","df":"-4x*exp(-2x^2)+sin(x)","x0":1.5,"eps":0.0001,"K":15,"criterio":"percentual","casas":8}', 'Newton-Raphson: 3 iterações; x = 1,56325632. O método convergiu na 3ª iteração: εₐ = 5,757×10⁻⁶% ≤ ε = 0,0001.
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t2-newton', 'A', '1,56325641', 0, 'Esse é o resultado com 2 iterações: faltou uma.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t2-newton', 'B', '1,01331193', 0, 'Sinal trocado na fórmula: o certo é xᵢ₊₁ = xᵢ − f(xᵢ)/f′(xᵢ).');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t2-newton', 'C', '−27,40393849', 0, 'Calculadora em graus: nos métodos numéricos as funções trigonométricas usam radianos.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t2-newton', 'D', '1,56325632', 1, NULL);
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('t2-newton-2', 'teste-2', 'Newton (2 iterações)', 'Teste 2', 'newton', 2, 'numero', 0, NULL, 'Teste 2: Newton-Raphson em f(x) = e⁻²ˣ² − cos x, com f′(x) = −4x·e⁻²ˣ² + sen x e x₀ = 1,5 (radianos). Faça 2 iterações com 8 casas decimais. Qual é x₂?', NULL, '1,563256', 1.56325641, NULL, NULL, NULL, NULL, 6, 0.000002, '{"calc":"newton","f":"exp(-2x^2)-cos(x)","df":"-4x*exp(-2x^2)+sin(x)","x0":1.5,"iteracoes":2,"casas":8}', 'Newton-Raphson: 2 iterações; x = 1,56325641. 2 iterações, como pedido.
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t2-newton-2', 'A', '1,564058', 0, 'Esse é o resultado com 1 iteração: faltou uma.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t2-newton-2', 'B', '1,304240', 0, 'Sinal trocado na fórmula: o certo é xᵢ₊₁ = xᵢ − f(xᵢ)/f′(xᵢ).');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t2-newton-2', 'C', '−25,287198', 0, 'Calculadora em graus: nos métodos numéricos as funções trigonométricas usam radianos.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t2-newton-2', 'D', '1,563256', 1, NULL);
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('t2-derivada', 'teste-2', 'Newton: derivada', 'Teste 2', 'newton', 1, 'texto', 1, NULL, 'Teste 2: para aplicar Newton-Raphson em f(x) = e⁻²ˣ² − cos x, qual é a derivada?', NULL, 'f′(x) = −4x·e⁻²ˣ² + sen x', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"Regra da cadeia em e^(−kx²): a derivada do expoente é −2kx, e a derivada de −cos x é + sen x."}', 'Regra da cadeia em e^(−kx²): a derivada do expoente é −2kx, e a derivada de −cos x é + sen x.', NULL, 0, 'azul', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t2-derivada', 'A', 'f′(x) = −4x·e⁻²ˣ² − sen x', 0, 'A derivada de −cos x é + sen x.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t2-derivada', 'B', 'f′(x) = −4x·e⁻²ˣ² + sen x', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t2-derivada', 'C', 'f′(x) = −e⁻²ˣ² + sen x', 0, 'Faltou a regra da cadeia: o expoente −kx² tem derivada −2kx.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t2-derivada', 'D', 'f′(x) = e⁻ˣ² + sen x', 0, 'A derivada de e^(g(x)) é g′(x)·e^(g(x)).');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('t2-tvi', 'teste-2', 'Questão 02 (a)', 'Teste 2', 'newton', 1, 'texto', 1, NULL, 'Teste 2: como mostrar que f(x) = e⁻²ˣ² − cos x tem pelo menos uma raiz real em (1, 2)?', NULL, 'f é contínua e f(1)·f(2) < 0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"f(1) < 0 e f(2) > 0 (cos 2 é negativo e a exponencial é positiva). Como f é contínua e f(1)·f(2) < 0, o Teorema do Valor Intermediário (Teorema 1 dos slides) garante uma raiz em (1, 2)."}', 'f(1) < 0 e f(2) > 0 (cos 2 é negativo e a exponencial é positiva). Como f é contínua e f(1)·f(2) < 0, o Teorema do Valor Intermediário (Teorema 1 dos slides) garante uma raiz em (1, 2).', NULL, 0, 'azul', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t2-tvi', 'A', 'f(1,5) = 0', 0, 'A raiz não é 1,5: só sabemos que está em (1, 2).');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t2-tvi', 'B', 'f(1) e f(2) são positivos', 0, 'cos 1 > e⁻ᵏ faz f(1) < 0.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t2-tvi', 'C', 'f é contínua e f(1)·f(2) < 0 (Teorema 1)', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t2-tvi', 'D', 'f′(x) > 0 em (1, 2)', 0, 'O que garante a raiz é a troca de sinal de f, não o sinal de f′.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('t2-gauss', 'teste-2', 'Questão 03', 'Teste 2', 'pivoteamento', 2, 'vetor', 0, NULL, 'Teste 2: resolva o sistema 7x₂ + 2x₃ = 16; 4x₁ + 3x₂ + x₃ = 3; 8x₁ + x₂ + 6x₃ = 0 pelo método de Eliminação de Gauss, com pivoteamento parcial. Qual é (x₁; x₂; x₃)?', '(−1; 2; 1)', '(−1; 2; 1)', NULL, NULL, '[-1,2,1]', '[-1,2,1]', NULL, 0, 0.01, '{"calc":"gauss","A":[[0,7,2],[4,3,1],[8,1,6]],"b":[16,3,0],"pivoteamento":"parcial"}', 'Solução: X* = (−1; 2; 1). (−19/7)x₃ = −19/7 ⇒ x₃ = 1; 7x₂ + 2·1 = 16 ⇒ x₂ = 2; 8x₁ + 1·2 + 6·1 = 0 ⇒ x₁ = −1', NULL, 0, 'azul', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t2-gauss', 'A', '(−1; 2; 1)', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t2-gauss', 'B', '(−1; 2; −1)', 0, 'Sinal da última componente trocado.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t2-gauss', 'C', '(2; −1; 1)', 0, 'Componentes trocadas de posição.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t2-gauss', 'D', '(4; −3; 6)', 0, 'Não confere: refaça a conta passo a passo (veja a resolução).');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('t2-pivo', 'teste-2', 'Gauss: 1º pivô', 'Teste 2', 'pivoteamento', 1, 'texto', 1, NULL, 'Teste 2: no sistema 7x₂ + 2x₃ = 16; 4x₁ + 3x₂ + x₃ = 3; 8x₁ + x₂ + 6x₃ = 0, com pivoteamento parcial, qual equação vira a equação pivô na 1ª etapa?', NULL, 'A 3ª equação (|8| é o maior da 1ª coluna): troca E₁ ↔ E₃', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"Na 1ª coluna os candidatos são 0, 4, 8; o maior em módulo é 8, na 3ª equação. Troca-se E₁ ↔ E₃, incluindo o termo independente."}', 'Na 1ª coluna os candidatos são 0, 4, 8; o maior em módulo é 8, na 3ª equação. Troca-se E₁ ↔ E₃, incluindo o termo independente.', NULL, 0, 'azul', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t2-pivo', 'A', 'Não importa: qualquer equação com aᵢ₁ ≠ 0 serve', 0, 'O pivoteamento parcial escolhe o MAIOR |aᵢ₁|, para os multiplicadores ficarem com |m| ≤ 1.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t2-pivo', 'B', 'A 2ª equação: troca E₁ ↔ E₂', 0, '|4| não é o maior da coluna.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t2-pivo', 'C', 'A 1ª equação: o pivô fica onde está', 0, 'a₁₁ = 0: não dá para dividir por ele, e mesmo assim o pivoteamento parcial escolheria o maior |aᵢ₁|.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t2-pivo', 'D', 'A 3ª equação (|8| é o maior da 1ª coluna): troca E₁ ↔ E₃', 1, NULL);
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('t3-bisseccao', 'teste-3', 'Questão 01', 'Teste 3', 'bissecao', 3, 'numero', 0, NULL, 'O método da bisseção foi usado para determinar o zero da função f(x) = x⁴ − 9x + 5 no intervalo inicial [0,5; 0,7]. Na 1ª iteração, foi obtida a aproximação x₁ = 0,600000, e o intervalo para a próxima iteração passou a ser [a, b] = [0,500000; 0,600000]. Continue os cálculos a partir da 2ª iteração e, após cada iteração, determine o erro relativo percentual (o primeiro erro usa a última aproximação fornecida). Use 6 casas decimais nos cálculos e 2 casas decimais no erro relativo percentual. Considere N = 15 e ε = 0,1%. Qual é a raiz aproximada?', '0,566798', '0,566798', 0.566798, 0.566798, NULL, NULL, NULL, 6, 0.000001, '{"calc":"bissecao","f":"x^4-9x+5","a":0.5,"b":0.6,"eps":0.1,"K":15,"criterio":"percentual","casas":6,"inicio":2,"anterior":0.6}', 'Bisseção: da 2ª à 9ª iteração; x = 0,566798. Na 9ª iteração o erro estimado é menor que o critério de parada: 0,068984 ≤ 0,1.
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t3-bisseccao', 'A', '0,562500', 0, 'Parou cedo demais: com 3 iterações o critério de parada ainda não foi atingido.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t3-bisseccao', 'B', '0,567043', 0, 'Esse valor sai da Falsa Posição (média ponderada pelos valores de f). A Bisseção usa o valor médio xᵢ = (aᵢ + bᵢ)/2.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t3-bisseccao', 'C', '0,575000', 0, 'Parou cedo demais: com 2 iterações o erro ainda está bem acima de ε.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t3-bisseccao', 'D', '0,566798', 1, NULL);
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('t3-bisseccao-pratica', 'teste-3', 'Questão 01 (prática)', 'Teste 3', 'bissecao', 2, 'numero', 0, NULL, 'Use o método da bisseção para determinar uma aproximação de um zero de f(x) = x⁴ − 9x + 5 no intervalo inicial [0,56; 0,58], começando na 1ª iteração pelo ponto médio. A partir da 2ª iteração, calcule o erro relativo percentual entre a aproximação atual e a anterior. Use 6 casas decimais nos cálculos e 2 casas decimais no erro relativo percentual. Considere N = 6 e ε = 0,1%. Qual é a raiz aproximada?', NULL, '0,567188', 0.567188, NULL, NULL, NULL, NULL, 6, 0.000001, '{"calc":"bissecao","f":"x^4-9x+5","a":0.56,"b":0.58,"eps":0.1,"K":6,"criterio":"percentual","casas":6}', 'Bisseção: 6 iterações; x = 0,567188. Na 6ª iteração o erro estimado é menor que o critério de parada: 0,0551845 ≤ 0,1.
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t3-bisseccao-pratica', 'A', '0,567188', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t3-bisseccao-pratica', 'B', '0,565000', 0, 'Parou cedo demais: com 2 iterações o erro ainda está bem acima de ε.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t3-bisseccao-pratica', 'C', '0,567043', 0, 'Esse valor sai da Falsa Posição (média ponderada pelos valores de f). A Bisseção usa o valor médio xᵢ = (aᵢ + bᵢ)/2.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t3-bisseccao-pratica', 'D', '0,567500', 0, 'Parou cedo demais: com 3 iterações o critério de parada ainda não foi atingido.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('t3-bisseccao-4', 'teste-3', 'Questão 01 (4 iterações)', 'Teste 3', 'bissecao', 2, 'numero', 0, NULL, 'Teste 3: bisseção em f(x) = x⁴ − 9x + 5, no intervalo [0,56; 0,58]. Faça 4 iterações com 6 casas decimais. Qual é x₄?', NULL, '0,566250', 0.56625, NULL, NULL, NULL, NULL, 6, 0.000001, '{"calc":"bissecao","f":"x^4-9x+5","a":0.56,"b":0.58,"iteracoes":4,"casas":6}', 'Bisseção: 4 iterações; x = 0,566250. 4 iterações, como pedido.
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t3-bisseccao-4', 'A', '0,567500', 0, 'Esse é o resultado com 3 iterações: faltou uma.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t3-bisseccao-4', 'B', '0,566875', 0, 'Esse é o resultado com 5 iterações: uma a mais do que o pedido.');
