INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('t3-newton', 'teste-3', 'Questão 03', 'Teste 3', 'newton', 3, 'numero', 0, NULL, 'Use o método de Newton-Raphson para determinar uma aproximação de um zero de f(x) = x·e⁻ˣ − 0,15, considerando x₀ = 3. Determine a derivada. Use 8 casas decimais nos cálculos (f(xᵢ) e f′(xᵢ) arredondados a 8 casas) e 6 casas no erro relativo percentual. Considere K = 15 e ε = 10⁻⁴%. Qual é a raiz aproximada?', '2,99359499', '2,99359499', 2.99359499, 2.99359499, NULL, NULL, NULL, 8, 2e-8, '{"calc":"newton","f":"x*exp(-x)-0.15","df":"(1-x)*exp(-x)","x0":3,"eps":0.0001,"K":15,"criterio":"percentual","casas":8}', 'Newton-Raphson: 3 iterações; x = 2,99359499. O método convergiu na 3ª iteração: εₐ = 0% ≤ ε = 0,0001.
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t3-newton', 'A', '3,26301854', 0, 'Não confere: refaça a conta passo a passo (veja a resolução).');
