INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('t3-newton-2', 'teste-3', 'Newton (2 iterações)', 'Teste 3', 'newton', 2, 'numero', 0, NULL, 'Teste 3: Newton-Raphson em f(x) = x·e⁻ˣ − 0,15, com f′(x) = (1 − x)·e⁻ˣ e x₀ = 3. Faça 2 iterações com 8 casas decimais. Qual é x₂?', NULL, '2,993595', 2.99359499, NULL, NULL, NULL, NULL, 6, 0.000002, '{"calc":"newton","f":"x*exp(-x)-0.15","df":"(1-x)*exp(-x)","x0":3,"iteracoes":2,"casas":8}', 'Newton-Raphson: 2 iterações; x = 2,99359499. 2 iterações, como pedido.
