INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t3-newton-2', 'C', '3,019277', 0, 'Sinal trocado na fórmula: o certo é xᵢ₊₁ = xᵢ − f(xᵢ)/f′(xᵢ).');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t3-newton-2', 'D', '3,113339', 0, 'Não confere: refaça a conta passo a passo (veja a resolução).');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('t3-derivada', 'teste-3', 'Newton: derivada', 'Teste 3', 'newton', 1, 'texto', 1, NULL, 'Teste 3: para aplicar Newton-Raphson em f(x) = x·e⁻ˣ − 0,15, qual é a derivada?', NULL, 'f′(x) = (1 − x)·e⁻ˣ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"Regra do produto: (x·e⁻ˣ)′ = 1·e⁻ˣ + x·(−e⁻ˣ) = (1 − x)·e⁻ˣ. A constante tem derivada zero."}', 'Regra do produto: (x·e⁻ˣ)′ = 1·e⁻ˣ + x·(−e⁻ˣ) = (1 − x)·e⁻ˣ. A constante tem derivada zero.', NULL, 0, 'azul', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t3-derivada', 'A', 'f′(x) = −x·e⁻ˣ', 0, 'Regra do produto: falta o termo 1·e⁻ˣ.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t3-derivada', 'B', 'f′(x) = (1 − x)·e⁻ˣ', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t3-derivada', 'C', 'f′(x) = (1 + x)·e⁻ˣ', 0, 'A derivada de e⁻ˣ é −e⁻ˣ: o termo x·(−e⁻ˣ) entra com sinal de menos.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t3-derivada', 'D', 'f′(x) = e⁻ˣ − 0,25', 0, 'A constante some na derivada, e falta o termo x·(−e⁻ˣ).');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('t3-gauss', 'teste-3', 'Questão 02', 'Teste 3', 'gauss', 2, 'vetor', 0, NULL, 'Teste 3: resolva o sistema 7x₁ + x₂ + 2x₃ = 13; 2x₁ + 4x₂ + 3x₃ = 5; x₁ + 2x₂ + 5x₃ = −1 pelo método de Eliminação de Gauss, com pivoteamento parcial se necessário. Qual é (x₁; x₂; x₃)?', '(2; 1; −1)', '(2; 1; −1)', NULL, NULL, '[2,1,-1]', '[2,1,-1]', NULL, 0, 0.01, '{"calc":"gauss","A":[[7,1,2],[2,4,3],[1,2,5]],"b":[13,5,-1],"pivoteamento":"nenhum"}', 'Solução: X* = (2; 1; −1). (7/2)x₃ = −7/2 ⇒ x₃ = −1; (26/7)x₂ + (17/7)·(−1) = 9/7 ⇒ x₂ = 1; 7x₁ + 1·1 + 2·(−1) = 13 ⇒ x₁ = 2', NULL, 0, 'azul', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t3-gauss', 'A', '(2; 1; 1)', 0, 'Sinal da última componente trocado.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t3-gauss', 'B', '(2; 1; −1)', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t3-gauss', 'C', '(7; −4; 4)', 0, 'Não confere: refaça a conta passo a passo (veja a resolução).');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t3-gauss', 'D', '(1; 2; −1)', 0, 'Componentes trocadas de posição.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('t4-bisseccao', 'teste-4', 'Questão 01', 'Teste 4', 'bissecao', 3, 'numero', 0, NULL, 'O método da bisseção foi usado para determinar o zero da função f(x) = 3 − 4e⁻ˣ − x no intervalo inicial [0,3; 0,7]. Na 3ª iteração, foi obtida a aproximação x₃ = 0,450000, e o intervalo para a próxima iteração passou a ser [a, b] = [0,450000; 0,500000]. Continue os cálculos a partir da 4ª iteração e, após cada iteração, determine o erro relativo percentual (o primeiro erro usa a última aproximação fornecida). Use 6 casas decimais nos cálculos e 2 casas decimais no erro relativo percentual. Considere N = 15 e ε = 0,1%. Qual é a raiz aproximada?', NULL, '0,450391', 0.450391, NULL, NULL, NULL, NULL, 6, 0.000001, '{"calc":"bissecao","f":"3-4exp(-x)-x","a":0.45,"b":0.5,"eps":0.1,"K":15,"criterio":"percentual","casas":6,"inicio":4,"anterior":0.45}', 'Bisseção: da 4ª à 10ª iteração; x = 0,450391. Na 10ª iteração o erro estimado é menor que o critério de parada: 0,0868135 ≤ 0,1.
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t4-bisseccao', 'A', '0,462500', 0, 'Parou cedo demais: com 2 iterações o erro ainda está bem acima de ε.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t4-bisseccao', 'B', '0,456250', 0, 'Parou cedo demais: com 3 iterações o critério de parada ainda não foi atingido.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t4-bisseccao', 'C', '0,450391', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t4-bisseccao', 'D', '0,450331', 0, 'Esse valor sai da Falsa Posição (média ponderada pelos valores de f). A Bisseção usa o valor médio xᵢ = (aᵢ + bᵢ)/2.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('t4-bisseccao-pratica', 'teste-4', 'Questão 01 (prática)', 'Teste 4', 'bissecao', 2, 'numero', 0, NULL, 'Use o método da bisseção para determinar uma aproximação de um zero de f(x) = 3 − 4e⁻ˣ − x no intervalo inicial [0,44; 0,46], começando na 1ª iteração pelo ponto médio. A partir da 2ª iteração, calcule o erro relativo percentual entre a aproximação atual e a anterior. Use 6 casas decimais nos cálculos e 2 casas decimais no erro relativo percentual. Considere N = 6 e ε = 0,1%. Qual é a raiz aproximada?', '0,450313', '0,450313', 0.450313, 0.450313, NULL, NULL, NULL, 6, 0.000001, '{"calc":"bissecao","f":"3-4exp(-x)-x","a":0.44,"b":0.46,"eps":0.1,"K":6,"criterio":"percentual","casas":6}', 'Bisseção: 6 iterações; x = 0,450313. Na 6ª iteração o erro estimado é menor que o critério de parada: 0,0692851 ≤ 0,1.
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t4-bisseccao-pratica', 'A', '0,452500', 0, 'Parou cedo demais: com 3 iterações o critério de parada ainda não foi atingido.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t4-bisseccao-pratica', 'B', '0,450313', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t4-bisseccao-pratica', 'C', '0,455000', 0, 'Parou cedo demais: com 2 iterações o erro ainda está bem acima de ε.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t4-bisseccao-pratica', 'D', '0,450331', 0, 'Esse valor sai da Falsa Posição (média ponderada pelos valores de f). A Bisseção usa o valor médio xᵢ = (aᵢ + bᵢ)/2.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('t4-bisseccao-4', 'teste-4', 'Questão 01 (4 iterações)', 'Teste 4', 'bissecao', 2, 'numero', 0, NULL, 'Teste 4: bisseção em f(x) = 3 − 4e⁻ˣ − x, no intervalo [0,44; 0,46]. Faça 4 iterações com 6 casas decimais. Qual é x₄?', NULL, '0,451250', 0.45125, NULL, NULL, NULL, NULL, 6, 0.000001, '{"calc":"bissecao","f":"3-4exp(-x)-x","a":0.44,"b":0.46,"iteracoes":4,"casas":6}', 'Bisseção: 4 iterações; x = 0,451250. 4 iterações, como pedido.
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t4-bisseccao-4', 'A', '0,452500', 0, 'Esse é o resultado com 3 iterações: faltou uma.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t4-bisseccao-4', 'B', '0,450625', 0, 'Esse é o resultado com 5 iterações: uma a mais do que o pedido.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t4-bisseccao-4', 'C', '0,450331', 0, 'Esse valor sai da Falsa Posição (média ponderada pelos valores de f). A Bisseção usa o valor médio xᵢ = (aᵢ + bᵢ)/2.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t4-bisseccao-4', 'D', '0,451250', 1, NULL);
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('t4-newton', 'teste-4', 'Questão 02 (b)', 'Teste 4', 'newton', 3, 'numero', 0, NULL, 'Use o método de Newton-Raphson para determinar uma aproximação de um zero de f(x) = e⁻⁰ʼ⁷⁵ˣ² − cos x, considerando x₀ = 1,5 (calculadora em radianos). Determine a derivada. Use 8 casas decimais nos cálculos (f(xᵢ) e f′(xᵢ) arredondados a 8 casas) e 6 casas no erro relativo percentual. Considere K = 15 e ε = 10⁻⁴%. Qual é a raiz aproximada?', '1,26476253', '1,26476253', 1.26476253, 1.26476253, NULL, NULL, NULL, 8, 2e-8, '{"calc":"newton","f":"exp(-0.75x^2)-cos(x)","df":"-1.5x*exp(-0.75x^2)+sin(x)","x0":1.5,"eps":0.0001,"K":15,"criterio":"percentual","casas":8}', 'Newton-Raphson: 5 iterações; x = 1,26476253. O método convergiu na 5ª iteração: εₐ = 0% ≤ ε = 0,0001.
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t4-newton', 'A', '1,26476585', 0, 'Parou cedo demais: com 3 iterações o critério de parada ainda não foi atingido.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t4-newton', 'B', '5,10228051', 0, 'Sinal trocado na fórmula: o certo é xᵢ₊₁ = xᵢ − f(xᵢ)/f′(xᵢ).');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t4-newton', 'C', '1,26641338', 0, 'Parou cedo demais: com 2 iterações o erro ainda está bem acima de ε.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t4-newton', 'D', '1,26476253', 1, NULL);
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('t4-newton-2', 'teste-4', 'Newton (2 iterações)', 'Teste 4', 'newton', 2, 'numero', 0, NULL, 'Teste 4: Newton-Raphson em f(x) = e⁻⁰ʼ⁷⁵ˣ² − cos x, com f′(x) = −1,5x·e⁻⁰ʼ⁷⁵ˣ² + sen x e x₀ = 1,5 (radianos). Faça 2 iterações com 8 casas decimais. Qual é x₂?', NULL, '1,266413', 1.26641338, NULL, NULL, NULL, NULL, 6, 0.000002, '{"calc":"newton","f":"exp(-0.75x^2)-cos(x)","df":"-1.5x*exp(-0.75x^2)+sin(x)","x0":1.5,"iteracoes":2,"casas":8}', 'Newton-Raphson: 2 iterações; x = 1,26641338. 2 iterações, como pedido.
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t4-newton-2', 'A', '1,266413', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t4-newton-2', 'B', '1,303463', 0, 'Esse é o resultado com 1 iteração: faltou uma.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t4-newton-2', 'C', '1,264766', 0, 'Esse é o resultado com 3 iterações: uma a mais do que o pedido.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t4-newton-2', 'D', '2,041530', 0, 'Sinal trocado na fórmula: o certo é xᵢ₊₁ = xᵢ − f(xᵢ)/f′(xᵢ).');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('t4-derivada', 'teste-4', 'Newton: derivada', 'Teste 4', 'newton', 1, 'texto', 1, NULL, 'Teste 4: para aplicar Newton-Raphson em f(x) = e⁻⁰ʼ⁷⁵ˣ² − cos x, qual é a derivada?', NULL, 'f′(x) = −1,5x·e⁻⁰ʼ⁷⁵ˣ² + sen x', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"Regra da cadeia em e^(−kx²): a derivada do expoente é −2kx, e a derivada de −cos x é + sen x."}', 'Regra da cadeia em e^(−kx²): a derivada do expoente é −2kx, e a derivada de −cos x é + sen x.', NULL, 0, 'azul', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t4-derivada', 'A', 'f′(x) = e⁻ˣ² + sen x', 0, 'A derivada de e^(g(x)) é g′(x)·e^(g(x)).');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t4-derivada', 'B', 'f′(x) = −1,5x·e⁻⁰ʼ⁷⁵ˣ² + sen x', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t4-derivada', 'C', 'f′(x) = −1,5x·e⁻⁰ʼ⁷⁵ˣ² − sen x', 0, 'A derivada de −cos x é + sen x.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t4-derivada', 'D', 'f′(x) = −e⁻⁰ʼ⁷⁵ˣ² + sen x', 0, 'Faltou a regra da cadeia: o expoente −kx² tem derivada −2kx.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('t4-tvi', 'teste-4', 'Questão 02 (a)', 'Teste 4', 'newton', 1, 'texto', 1, NULL, 'Teste 4: como mostrar que f(x) = e⁻⁰ʼ⁷⁵ˣ² − cos x tem pelo menos uma raiz real em (1, 2)?', NULL, 'f é contínua e f(1)·f(2) < 0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"f(1) < 0 e f(2) > 0 (cos 2 é negativo e a exponencial é positiva). Como f é contínua e f(1)·f(2) < 0, o Teorema do Valor Intermediário (Teorema 1 dos slides) garante uma raiz em (1, 2)."}', 'f(1) < 0 e f(2) > 0 (cos 2 é negativo e a exponencial é positiva). Como f é contínua e f(1)·f(2) < 0, o Teorema do Valor Intermediário (Teorema 1 dos slides) garante uma raiz em (1, 2).', NULL, 0, 'azul', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t4-tvi', 'A', 'f′(x) > 0 em (1, 2)', 0, 'O que garante a raiz é a troca de sinal de f, não o sinal de f′.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t4-tvi', 'B', 'f(1) e f(2) são positivos', 0, 'cos 1 > e⁻ᵏ faz f(1) < 0.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t4-tvi', 'C', 'f é contínua e f(1)·f(2) < 0 (Teorema 1)', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t4-tvi', 'D', 'f(1,5) = 0', 0, 'A raiz não é 1,5: só sabemos que está em (1, 2).');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('t4-gauss', 'teste-4', 'Questão 03', 'Teste 4', 'pivoteamento', 2, 'vetor', 0, NULL, 'Teste 4: resolva o sistema 5x₂ + 3x₃ = 1; 2x₁ + 6x₂ + x₃ = −2; 6x₁ + 2x₂ + 7x₃ = 18 pelo método de Eliminação de Gauss, com pivoteamento parcial. Qual é (x₁; x₂; x₃)?', '(1; −1; 2)', '(1; −1; 2)', NULL, NULL, '[1,-1,2]', '[1,-1,2]', NULL, 0, 0.01, '{"calc":"gauss","A":[[0,5,3],[2,6,1],[6,2,7]],"b":[1,-2,18],"pivoteamento":"parcial"}', 'Solução: X* = (1; −1; 2). (17/4)x₃ = 17/2 ⇒ x₃ = 2; (16/3)x₂ − (4/3)·2 = −8 ⇒ x₂ = −1; 6x₁ + 2·(−1) + 7·2 = 18 ⇒ x₁ = 1', NULL, 0, 'azul', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t4-gauss', 'A', '(−1; 1; 2)', 0, 'Componentes trocadas de posição.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t4-gauss', 'B', '(1; −1; −2)', 0, 'Sinal da última componente trocado.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t4-gauss', 'C', '(6; −6; 7)', 0, 'Não confere: refaça a conta passo a passo (veja a resolução).');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t4-gauss', 'D', '(1; −1; 2)', 1, NULL);
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('t4-pivo', 'teste-4', 'Gauss: 1º pivô', 'Teste 4', 'pivoteamento', 1, 'texto', 1, NULL, 'Teste 4: no sistema 5x₂ + 3x₃ = 1; 2x₁ + 6x₂ + x₃ = −2; 6x₁ + 2x₂ + 7x₃ = 18, com pivoteamento parcial, qual equação vira a equação pivô na 1ª etapa?', NULL, 'A 3ª equação (|6| é o maior da 1ª coluna): troca E₁ ↔ E₃', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"Na 1ª coluna os candidatos são 0, 2, 6; o maior em módulo é 6, na 3ª equação. Troca-se E₁ ↔ E₃, incluindo o termo independente."}', 'Na 1ª coluna os candidatos são 0, 2, 6; o maior em módulo é 6, na 3ª equação. Troca-se E₁ ↔ E₃, incluindo o termo independente.', NULL, 0, 'azul', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t4-pivo', 'A', 'A 1ª equação: o pivô fica onde está', 0, 'a₁₁ = 0: não dá para dividir por ele, e mesmo assim o pivoteamento parcial escolheria o maior |aᵢ₁|.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t4-pivo', 'B', 'Não importa: qualquer equação com aᵢ₁ ≠ 0 serve', 0, 'O pivoteamento parcial escolhe o MAIOR |aᵢ₁|, para os multiplicadores ficarem com |m| ≤ 1.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t4-pivo', 'C', 'A 3ª equação (|6| é o maior da 1ª coluna): troca E₁ ↔ E₃', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t4-pivo', 'D', 'A 2ª equação: troca E₁ ↔ E₂', 0, '|2| não é o maior da coluna.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('t5-bisseccao', 'teste-5', 'Questão 01', 'Teste 5', 'bissecao', 3, 'numero', 0, NULL, 'O método da bisseção foi usado para determinar o zero da função f(x) = x⁴ − 6x + 3 no intervalo inicial [0,5; 0,7]. Na 1ª iteração, foi obtida a aproximação x₁ = 0,600000, e o intervalo para a próxima iteração passou a ser [a, b] = [0,500000; 0,600000]. Continue os cálculos a partir da 2ª iteração e, após cada iteração, determine o erro relativo percentual (o primeiro erro usa a última aproximação fornecida). Use 6 casas decimais nos cálculos e 2 casas decimais no erro relativo percentual. Considere N = 15 e ε = 0,1%. Qual é a raiz aproximada?', NULL, '0,511329', 0.511329, NULL, NULL, NULL, NULL, 6, 0.000001, '{"calc":"bissecao","f":"x^4-6x+3","a":0.5,"b":0.6,"eps":0.1,"K":15,"criterio":"percentual","casas":6,"inicio":2,"anterior":0.6}', 'Bisseção: da 2ª à 9ª iteração; x = 0,511329. Na 9ª iteração o erro estimado é menor que o critério de parada: 0,0762718 ≤ 0,1.
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t5-bisseccao', 'A', '0,512500', 0, 'Parou cedo demais: com 3 iterações o critério de parada ainda não foi atingido.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t5-bisseccao', 'B', '0,511400', 0, 'Esse valor sai da Falsa Posição (média ponderada pelos valores de f). A Bisseção usa o valor médio xᵢ = (aᵢ + bᵢ)/2.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t5-bisseccao', 'C', '0,525000', 0, 'Parou cedo demais: com 2 iterações o erro ainda está bem acima de ε.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t5-bisseccao', 'D', '0,511329', 1, NULL);
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('t5-bisseccao-pratica', 'teste-5', 'Questão 01 (prática)', 'Teste 5', 'bissecao', 2, 'numero', 0, NULL, 'Use o método da bisseção para determinar uma aproximação de um zero de f(x) = x⁴ − 6x + 3 no intervalo inicial [0,5; 0,52], começando na 1ª iteração pelo ponto médio. A partir da 2ª iteração, calcule o erro relativo percentual entre a aproximação atual e a anterior. Use 6 casas decimais nos cálculos e 2 casas decimais no erro relativo percentual. Considere N = 6 e ε = 0,1%. Qual é a raiz aproximada?', NULL, '0,511563', 0.511563, NULL, NULL, NULL, NULL, 6, 0.000001, '{"calc":"bissecao","f":"x^4-6x+3","a":0.5,"b":0.52,"eps":0.1,"K":6,"criterio":"percentual","casas":6}', 'Bisseção: 6 iterações; x = 0,511563. Na 6ª iteração o erro estimado é menor que o critério de parada: 0,0609896 ≤ 0,1.
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t5-bisseccao-pratica', 'A', '0,511563', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t5-bisseccao-pratica', 'B', '0,512500', 0, 'Parou cedo demais: com 3 iterações o critério de parada ainda não foi atingido.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t5-bisseccao-pratica', 'C', '0,515000', 0, 'Parou cedo demais: com 2 iterações o erro ainda está bem acima de ε.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t5-bisseccao-pratica', 'D', '0,511400', 0, 'Esse valor sai da Falsa Posição (média ponderada pelos valores de f). A Bisseção usa o valor médio xᵢ = (aᵢ + bᵢ)/2.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('t5-bisseccao-4', 'teste-5', 'Questão 01 (4 iterações)', 'Teste 5', 'bissecao', 2, 'numero', 0, NULL, 'Teste 5: bisseção em f(x) = x⁴ − 6x + 3, no intervalo [0,5; 0,52]. Faça 4 iterações com 6 casas decimais. Qual é x₄?', NULL, '0,511250', 0.51125, NULL, NULL, NULL, NULL, 6, 0.000001, '{"calc":"bissecao","f":"x^4-6x+3","a":0.5,"b":0.52,"iteracoes":4,"casas":6}', 'Bisseção: 4 iterações; x = 0,511250. 4 iterações, como pedido.
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t5-bisseccao-4', 'A', '0,511250', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t5-bisseccao-4', 'B', '0,511875', 0, 'Esse é o resultado com 5 iterações: uma a mais do que o pedido.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t5-bisseccao-4', 'C', '0,511400', 0, 'Esse valor sai da Falsa Posição (média ponderada pelos valores de f). A Bisseção usa o valor médio xᵢ = (aᵢ + bᵢ)/2.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t5-bisseccao-4', 'D', '0,512500', 0, 'Esse é o resultado com 3 iterações: faltou uma.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('t5-newton', 'teste-5', 'Questão 03', 'Teste 5', 'newton', 3, 'numero', 0, NULL, 'Use o método de Newton-Raphson para determinar uma aproximação de um zero de f(x) = x·e⁻ˣ − 0,30, considerando x₀ = 2. Determine a derivada. Use 8 casas decimais nos cálculos (f(xᵢ) e f′(xᵢ) arredondados a 8 casas) e 6 casas no erro relativo percentual. Considere K = 15 e ε = 10⁻⁴%. Qual é a raiz aproximada?', NULL, '1,78133702', 1.78133702, NULL, NULL, NULL, NULL, 8, 2e-8, '{"calc":"newton","f":"x*exp(-x)-0.3","df":"(1-x)*exp(-x)","x0":2,"eps":0.0001,"K":15,"criterio":"percentual","casas":8}', 'Newton-Raphson: 3 iterações; x = 1,78133702. O método convergiu na 3ª iteração: εₐ = 2,975×10⁻⁵% ≤ ε = 0,0001.
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t5-newton', 'A', '1,78133755', 0, 'Esse é o resultado com 2 iterações: faltou uma.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t5-newton', 'B', '1,78133702', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t5-newton', 'C', '3,63552057', 0, 'Sinal trocado na fórmula: o certo é xᵢ₊₁ = xᵢ − f(xᵢ)/f′(xᵢ).');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t5-newton', 'D', '1,71008354', 0, 'Não confere: refaça a conta passo a passo (veja a resolução).');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('t5-newton-2', 'teste-5', 'Newton (2 iterações)', 'Teste 5', 'newton', 2, 'numero', 0, NULL, 'Teste 5: Newton-Raphson em f(x) = x·e⁻ˣ − 0,30, com f′(x) = (1 − x)·e⁻ˣ e x₀ = 2. Faça 2 iterações com 8 casas decimais. Qual é x₂?', NULL, '1,781338', 1.78133755, NULL, NULL, NULL, NULL, 6, 0.000002, '{"calc":"newton","f":"x*exp(-x)-0.3","df":"(1-x)*exp(-x)","x0":2,"iteracoes":2,"casas":8}', 'Newton-Raphson: 2 iterações; x = 1,78133755. 2 iterações, como pedido.
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t5-newton-2', 'A', '1,710084', 0, 'Não confere: refaça a conta passo a passo (veja a resolução).');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t5-newton-2', 'B', '1,783283', 0, 'Esse é o resultado com 1 iteração: faltou uma.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t5-newton-2', 'C', '2,657599', 0, 'Sinal trocado na fórmula: o certo é xᵢ₊₁ = xᵢ − f(xᵢ)/f′(xᵢ).');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t5-newton-2', 'D', '1,781338', 1, NULL);
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('t5-derivada', 'teste-5', 'Newton: derivada', 'Teste 5', 'newton', 1, 'texto', 1, NULL, 'Teste 5: para aplicar Newton-Raphson em f(x) = x·e⁻ˣ − 0,30, qual é a derivada?', NULL, 'f′(x) = (1 − x)·e⁻ˣ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"Regra do produto: (x·e⁻ˣ)′ = 1·e⁻ˣ + x·(−e⁻ˣ) = (1 − x)·e⁻ˣ. A constante tem derivada zero."}', 'Regra do produto: (x·e⁻ˣ)′ = 1·e⁻ˣ + x·(−e⁻ˣ) = (1 − x)·e⁻ˣ. A constante tem derivada zero.', NULL, 0, 'azul', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t5-derivada', 'A', 'f′(x) = (1 + x)·e⁻ˣ', 0, 'A derivada de e⁻ˣ é −e⁻ˣ: o termo x·(−e⁻ˣ) entra com sinal de menos.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t5-derivada', 'B', 'f′(x) = −x·e⁻ˣ', 0, 'Regra do produto: falta o termo 1·e⁻ˣ.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t5-derivada', 'C', 'f′(x) = (1 − x)·e⁻ˣ', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t5-derivada', 'D', 'f′(x) = e⁻ˣ − 0,25', 0, 'A constante some na derivada, e falta o termo x·(−e⁻ˣ).');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('t5-gauss', 'teste-5', 'Questão 02', 'Teste 5', 'gauss', 2, 'vetor', 0, NULL, 'Teste 5: resolva o sistema 4x₁ + 2x₂ + x₃ = −3; 2x₁ + x₂ + 3x₃ = 6; x₁ + 4x₂ + 2x₃ = 8 pelo método de Eliminação de Gauss, com pivoteamento parcial se necessário. Qual é (x₁; x₂; x₃)?', NULL, '(−2; 1; 3)', NULL, NULL, '[-2,1,3]', NULL, NULL, 0, 0.01, '{"calc":"gauss","A":[[4,2,1],[2,1,3],[1,4,2]],"b":[-3,6,8],"pivoteamento":"nenhum"}', 'Solução: X* = (−2; 1; 3). (5/2)x₃ = 15/2 ⇒ x₃ = 3; (7/2)x₂ + (7/4)·3 = 35/4 ⇒ x₂ = 1; 4x₁ + 2·1 + 1·3 = −3 ⇒ x₁ = −2', NULL, 0, 'azul', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t5-gauss', 'A', '(3; −4; 8)', 0, 'Não confere: refaça a conta passo a passo (veja a resolução).');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t5-gauss', 'B', '(−2; 1; 3)', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t5-gauss', 'C', '(−2; 1; −3)', 0, 'Sinal da última componente trocado.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t5-gauss', 'D', '(1; −2; 3)', 0, 'Componentes trocadas de posição.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('t6-bisseccao', 'teste-6', 'Questão 01', 'Teste 6', 'bissecao', 3, 'numero', 0, NULL, 'O método da bisseção foi usado para determinar o zero da função f(x) = 2,5 − 3e⁻ˣ − x no intervalo inicial [0,2; 0,6]. Na 3ª iteração, foi obtida a aproximação x₃ = 0,350000, e o intervalo para a próxima iteração passou a ser [a, b] = [0,300000; 0,350000]. Continue os cálculos a partir da 4ª iteração e, após cada iteração, determine o erro relativo percentual (o primeiro erro usa a última aproximação fornecida). Use 6 casas decimais nos cálculos e 2 casas decimais no erro relativo percentual. Considere N = 15 e ε = 0,1%. Qual é a raiz aproximada?', NULL, '0,318555', 0.318555, NULL, NULL, NULL, NULL, 6, 0.000001, '{"calc":"bissecao","f":"2.5-3exp(-x)-x","a":0.3,"b":0.35,"eps":0.1,"K":15,"criterio":"percentual","casas":6,"inicio":4,"anterior":0.35}', 'Bisseção: da 4ª à 11ª iteração; x = 0,318555. Na 11ª iteração o erro estimado é menor que o critério de parada: 0,0612139 ≤ 0,1.
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t6-bisseccao', 'A', '0,312500', 0, 'Parou cedo demais: com 2 iterações o erro ainda está bem acima de ε.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t6-bisseccao', 'B', '0,318750', 0, 'Parou cedo demais: com 3 iterações o critério de parada ainda não foi atingido.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t6-bisseccao', 'C', '0,318684', 0, 'Esse valor sai da Falsa Posição (média ponderada pelos valores de f). A Bisseção usa o valor médio xᵢ = (aᵢ + bᵢ)/2.');
