INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('t6-bisseccao-4', 'teste-6', 'Questão 01 (4 iterações)', 'Teste 6', 'bissecao', 2, 'numero', 0, NULL, 'Teste 6: bisseção em f(x) = 2,5 − 3e⁻ˣ − x, no intervalo [0,31; 0,32]. Faça 4 iterações com 6 casas decimais. Qual é x₄?', NULL, '0,318125', 0.318125, NULL, NULL, NULL, NULL, 6, 0.000001, '{"calc":"bissecao","f":"2.5-3exp(-x)-x","a":0.31,"b":0.32,"iteracoes":4,"casas":6}', 'Bisseção: 4 iterações; x = 0,318125. 4 iterações, como pedido.
