INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('t6-newton', 'teste-6', 'Questão 02 (b)', 'Teste 6', 'newton', 3, 'numero', 0, NULL, 'Use o método de Newton-Raphson para determinar uma aproximação de um zero de f(x) = e⁻¹ʼ⁵ˣ² − cos x, considerando x₀ = 1,4 (calculadora em radianos). Determine a derivada. Use 8 casas decimais nos cálculos (f(xᵢ) e f′(xᵢ) arredondados a 8 casas) e 6 casas no erro relativo percentual. Considere K = 15 e ε = 10⁻⁴%. Qual é a raiz aproximada?', NULL, '1,54262354', 1.54262354, NULL, NULL, NULL, NULL, 8, 2e-8, '{"calc":"newton","f":"exp(-1.5x^2)-cos(x)","df":"-3x*exp(-1.5x^2)+sin(x)","x0":1.4,"eps":0.0001,"K":15,"criterio":"percentual","casas":8}', 'Newton-Raphson: 4 iterações; x = 1,54262354. O método convergiu na 4ª iteração: εₐ = 0% ≤ ε = 0,0001.
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t6-newton', 'A', '−25,33267119', 0, 'Calculadora em graus: nos métodos numéricos as funções trigonométricas usam radianos.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t6-newton', 'B', '1,60432848', 0, 'Não confere: refaça a conta passo a passo (veja a resolução).');
