INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t6-newton', 'D', '5,29314548', 0, 'Sinal trocado na fórmula: o certo é xᵢ₊₁ = xᵢ − f(xᵢ)/f′(xᵢ).');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('t6-newton-2', 'teste-6', 'Newton (2 iterações)', 'Teste 6', 'newton', 2, 'numero', 0, NULL, 'Teste 6: Newton-Raphson em f(x) = e⁻¹ʼ⁵ˣ² − cos x, com f′(x) = −3x·e⁻¹ʼ⁵ˣ² + sen x e x₀ = 1,4 (radianos). Faça 2 iterações com 8 casas decimais. Qual é x₂?', NULL, '1,542659', 1.54265855, NULL, NULL, NULL, NULL, 6, 0.000002, '{"calc":"newton","f":"exp(-1.5x^2)-cos(x)","df":"-3x*exp(-1.5x^2)+sin(x)","x0":1.4,"iteracoes":2,"casas":8}', 'Newton-Raphson: 2 iterações; x = 1,54265855. 2 iterações, como pedido.
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t6-newton-2', 'A', '1,542624', 0, 'Esse é o resultado com 3 iterações: uma a mais do que o pedido.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t6-newton-2', 'B', '1,553392', 0, 'Esse é o resultado com 1 iteração: faltou uma.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t6-newton-2', 'C', '0,867865', 0, 'Sinal trocado na fórmula: o certo é xᵢ₊₁ = xᵢ − f(xᵢ)/f′(xᵢ).');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t6-newton-2', 'D', '1,542659', 1, NULL);
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('t6-derivada', 'teste-6', 'Newton: derivada', 'Teste 6', 'newton', 1, 'texto', 1, NULL, 'Teste 6: para aplicar Newton-Raphson em f(x) = e⁻¹ʼ⁵ˣ² − cos x, qual é a derivada?', NULL, 'f′(x) = −3x·e⁻¹ʼ⁵ˣ² + sen x', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"Regra da cadeia em e^(−kx²): a derivada do expoente é −2kx, e a derivada de −cos x é + sen x."}', 'Regra da cadeia em e^(−kx²): a derivada do expoente é −2kx, e a derivada de −cos x é + sen x.', NULL, 0, 'azul', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t6-derivada', 'A', 'f′(x) = −3x·e⁻¹ʼ⁵ˣ² − sen x', 0, 'A derivada de −cos x é + sen x.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t6-derivada', 'B', 'f′(x) = −3x·e⁻¹ʼ⁵ˣ² + sen x', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t6-derivada', 'C', 'f′(x) = e⁻ˣ² + sen x', 0, 'A derivada de e^(g(x)) é g′(x)·e^(g(x)).');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t6-derivada', 'D', 'f′(x) = −e⁻¹ʼ⁵ˣ² + sen x', 0, 'Faltou a regra da cadeia: o expoente −kx² tem derivada −2kx.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('t6-tvi', 'teste-6', 'Questão 02 (a)', 'Teste 6', 'newton', 1, 'texto', 1, NULL, 'Teste 6: como mostrar que f(x) = e⁻¹ʼ⁵ˣ² − cos x tem pelo menos uma raiz real em (1, 2)?', NULL, 'f é contínua e f(1)·f(2) < 0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"f(1) < 0 e f(2) > 0 (cos 2 é negativo e a exponencial é positiva). Como f é contínua e f(1)·f(2) < 0, o Teorema do Valor Intermediário (Teorema 1 dos slides) garante uma raiz em (1, 2)."}', 'f(1) < 0 e f(2) > 0 (cos 2 é negativo e a exponencial é positiva). Como f é contínua e f(1)·f(2) < 0, o Teorema do Valor Intermediário (Teorema 1 dos slides) garante uma raiz em (1, 2).', NULL, 0, 'azul', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t6-tvi', 'A', 'f(1) e f(2) são positivos', 0, 'cos 1 > e⁻ᵏ faz f(1) < 0.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t6-tvi', 'B', 'f(1,5) = 0', 0, 'A raiz não é 1,5: só sabemos que está em (1, 2).');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t6-tvi', 'C', 'f é contínua e f(1)·f(2) < 0 (Teorema 1)', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t6-tvi', 'D', 'f′(x) > 0 em (1, 2)', 0, 'O que garante a raiz é a troca de sinal de f, não o sinal de f′.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('t6-gauss', 'teste-6', 'Questão 03', 'Teste 6', 'pivoteamento', 2, 'vetor', 0, NULL, 'Teste 6: resolva o sistema 6x₂ + x₃ = −5; 3x₁ + 2x₂ + 4x₃ = 8; 9x₁ + x₂ + 5x₃ = 22 pelo método de Eliminação de Gauss, com pivoteamento parcial. Qual é (x₁; x₂; x₃)?', NULL, '(2; −1; 1)', NULL, NULL, '[2,-1,1]', NULL, NULL, 0, 0.01, '{"calc":"gauss","A":[[0,6,1],[3,2,4],[9,1,5]],"b":[-5,8,22],"pivoteamento":"parcial"}', 'Solução: X* = (2; −1; 1). (37/18)x₃ = 37/18 ⇒ x₃ = 1; 6x₂ + 1·1 = −5 ⇒ x₂ = −1; 9x₁ + 1·(−1) + 5·1 = 22 ⇒ x₁ = 2', NULL, 0, 'azul', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t6-gauss', 'A', '(2; −1; 1)', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t6-gauss', 'B', '(−1; 2; 1)', 0, 'Componentes trocadas de posição.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t6-gauss', 'C', '(2; −1; −1)', 0, 'Sinal da última componente trocado.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t6-gauss', 'D', '(7; −6; 6)', 0, 'Não confere: refaça a conta passo a passo (veja a resolução).');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('t6-pivo', 'teste-6', 'Gauss: 1º pivô', 'Teste 6', 'pivoteamento', 1, 'texto', 1, NULL, 'Teste 6: no sistema 6x₂ + x₃ = −5; 3x₁ + 2x₂ + 4x₃ = 8; 9x₁ + x₂ + 5x₃ = 22, com pivoteamento parcial, qual equação vira a equação pivô na 1ª etapa?', NULL, 'A 3ª equação (|9| é o maior da 1ª coluna): troca E₁ ↔ E₃', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"Na 1ª coluna os candidatos são 0, 3, 9; o maior em módulo é 9, na 3ª equação. Troca-se E₁ ↔ E₃, incluindo o termo independente."}', 'Na 1ª coluna os candidatos são 0, 3, 9; o maior em módulo é 9, na 3ª equação. Troca-se E₁ ↔ E₃, incluindo o termo independente.', NULL, 0, 'azul', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t6-pivo', 'A', 'A 2ª equação: troca E₁ ↔ E₂', 0, '|3| não é o maior da coluna.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t6-pivo', 'B', 'Não importa: qualquer equação com aᵢ₁ ≠ 0 serve', 0, 'O pivoteamento parcial escolhe o MAIOR |aᵢ₁|, para os multiplicadores ficarem com |m| ≤ 1.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t6-pivo', 'C', 'A 1ª equação: o pivô fica onde está', 0, 'a₁₁ = 0: não dá para dividir por ele, e mesmo assim o pivoteamento parcial escolheria o maior |aᵢ₁|.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('t6-pivo', 'D', 'A 3ª equação (|9| é o maior da 1ª coluna): troca E₁ ↔ E₃', 1, NULL);
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('ib4-01', 'ibmec-04', '1', '4ª Lista de Cálculo Numérico', 'bissecao', 2, 'numero', 0, NULL, 'Utilizando o método da Bisseção, determine o zero da função f(x) = eˣ − 3x, onde [a, b] = [1, 2]. Após cada iteração, determine os erros absoluto e relativo (teste de parada). Considere o número máximo de iterações N = 20 e ε = 10⁻⁵.', NULL, '1,5121', 1.5121383667, NULL, NULL, NULL, NULL, 4, 0.0001, '{"calc":"bissecao","f":"exp(x)-3x","a":1,"b":2,"eps":0.00001,"K":20,"criterio":"largura"}', 'Bisseção: 17 iterações; x = 1,512138. b − a = 7,629×10⁻⁶ < ε = 1,000×10⁻⁵ na 17ª iteração.', NULL, 0, 'azul', 17);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('ib4-01', 'A', '1,5121', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('ib4-01', 'B', '1,7500', 0, 'Parou cedo demais: com 2 iterações o erro ainda está bem acima de ε.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('ib4-01', 'C', '1,6250', 0, 'Parou cedo demais: com 3 iterações o critério de parada ainda não foi atingido.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('ib4-01', 'D', '1,5726', 0, 'Não confere: refaça a conta passo a passo (veja a resolução).');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('ib4-01-r', 'ibmec-04', '1 · 1º passo', '4ª Lista de Cálculo Numérico', 'bissecao', 1, 'numero', 1, 'ib4-01', 'Bisseção, 1º passo: f(x) = eˣ − 3x em [1; 2]. Qual é x₁?', NULL, '1,5000', 1.5, NULL, NULL, NULL, NULL, 4, NULL, '{"calc":"bissecao","f":"exp(x)-3x","a":1,"b":2,"iteracoes":1}', 'Bisseção: 1 iteração; x = 1,500000. 1 iteração, como pedido.
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('ib4-01-r', 'A', '1,1686', 0, 'Esse valor sai da Falsa Posição (média ponderada pelos valores de f). A Bisseção usa o valor médio xᵢ = (aᵢ + bᵢ)/2.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('ib4-01-r', 'B', '1,4400', 0, 'Não confere: refaça a conta passo a passo (veja a resolução).');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('ib4-01-r', 'C', '1,5000', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('ib4-01-r', 'D', '1,7500', 0, 'Esse é o resultado com 2 iterações: uma a mais do que o pedido.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('ib4-02a', 'ibmec-04', '2 (a)', '4ª Lista de Cálculo Numérico', 'bissecao', 2, 'numero', 0, NULL, 'Use o método da Bisseção para obter a menor raiz positiva de x/2 − tg x = 0 com precisão ε = 10⁻⁴, no intervalo [4; 4,5]. Após cada iteração, determine os erros absoluto e relativo (teste de parada). Considere N = 20.', NULL, '4,2748', 4.27484130859, NULL, NULL, NULL, NULL, 4, 0.001, '{"calc":"bissecao","f":"x/2-tan(x)","a":4,"b":4.5,"eps":0.0001,"K":20,"criterio":"largura"}', 'Bisseção: 13 iterações; x = 4,274841. b − a = 6,104×10⁻⁵ < ε = 0,0001 na 13ª iteração.
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('ib4-02a', 'A', '4,3125', 0, 'Parou cedo demais: com 3 iterações o critério de parada ainda não foi atingido.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('ib4-02a', 'B', '4,1038', 0, 'Não confere: refaça a conta passo a passo (veja a resolução).');
