INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('ib4-02b', 'ibmec-04', '2 (b)', '4ª Lista de Cálculo Numérico', 'bissecao', 2, 'numero', 0, NULL, 'Use o método da Bisseção para obter a menor raiz positiva de 2cos x = eˣ/2 com precisão ε = 10⁻⁴, no intervalo [0, 1]. Após cada iteração, determine os erros absoluto e relativo (teste de parada). Considere N = 20.', NULL, '0,9048', 0.904846191406, NULL, NULL, NULL, NULL, 4, 0.001, '{"calc":"bissecao","f":"2cos(x)-exp(x)/2","a":0,"b":1,"eps":0.0001,"K":20,"criterio":"largura"}', 'Bisseção: 14 iterações; x = 0,904846. b − a = 6,104×10⁻⁵ < ε = 0,0001 na 14ª iteração.
