INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('ib5-01', 'ibmec-05', '1', '5ª Lista de Cálculo Numérico', 'newton', 2, 'numero', 0, NULL, 'Utilizando o método de Newton-Raphson, determine o zero da função f(x) = eˣ − 3x, onde x₀ = 2. Após cada iteração, determine os erros absoluto e relativo (teste de parada). Considere N = 10 e ε = 10⁻⁷.', NULL, '1,512135', 1.51213455166, NULL, NULL, NULL, NULL, 6, 0.000001, '{"calc":"newton","f":"exp(x)-3x","df":"exp(x)-3","x0":2,"eps":1e-7,"K":10,"criterio":"relativo"}', 'Newton-Raphson: 6 iterações; x = 1,512135. O método convergiu na 6ª iteração: εₐ = 7,109×10⁻¹² ≤ ε = 1,000×10⁻⁷.
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('ib5-01', 'A', '1,513489', 0, 'Parou cedo demais: com 3 iterações o critério de parada ainda não foi atingido.');
