INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('ib5-03', 'ibmec-05', '3', '5ª Lista de Cálculo Numérico', 'newton', 3, 'texto', 0, NULL, 'Com o uso da calculadora, aplique o método de Newton-Raphson à equação x³ − 2x² − 3x + 10 = 0 com x₀ = 1,9. O que acontece?', NULL, 'O primeiro passo é enorme (x₁ ≈ −4,92) porque f′(1,9) ≈ 0,23 é quase zero; depois o método vai para a única raiz real, x ≈ −2', NULL, NULL, NULL, NULL, NULL, NULL, 0.0001, '{"calc":"texto","resumo":"f′(x) = 3x² − 4x − 3 e f′(1,9) = 0,23: a tangente é quase horizontal e x₁ = 1,9 − f(1,9)/f′(1,9) ≈ 1,9 − 1,569/0,23 ≈ −4,92 cai longe. Daí em diante o método ainda acha a raiz real x ≈ −2, mas o primeiro passo mostra o perigo de f′(xᵢ) ≈ 0 (um dos itens de \"desvantagens\" dos slides)."}', 'f′(x) = 3x² − 4x − 3 e f′(1,9) = 0,23: a tangente é quase horizontal e x₁ = 1,9 − f(1,9)/f′(1,9) ≈ 1,9 − 1,569/0,23 ≈ −4,92 cai longe. Daí em diante o método ainda acha a raiz real x ≈ −2, mas o primeiro passo mostra o perigo de f′(xᵢ) ≈ 0 (um dos itens de "desvantagens" dos slides).', NULL, 0, 'azul', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('ib5-03', 'A', 'f′(1,9) ≈ 0,23 é quase zero: x₁ ≈ −4,92 vai para longe, e só depois o método caminha para a raiz real x ≈ −2', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('ib5-03', 'B', 'O método fica oscilando entre 1,9 e 2,1 para sempre', 0, 'O primeiro passo já sai para x ≈ −4,92.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('ib5-03', 'C', 'O método para: f′(1,9) = 0', 0, 'f′(1,9) = 0,23, pequeno mas diferente de zero.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('ib5-03', 'D', 'O método converge rapidamente para uma raiz perto de 1,9', 0, 'A equação não tem raiz perto de 1,9: f(1,9) ≈ 1,57 e f tem mínimo local positivo ali.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('ib5-04', 'ibmec-05', '4', '5ª Lista de Cálculo Numérico', 'newton', 2, 'numero', 0, NULL, 'Seja a equação f(x) = x − x·ln x = 0. Utilize o método de Newton-Raphson para determinar a raiz positiva desta equação, partindo de x₀ = 2. Considere ε = 10⁻⁵ e N = 10.', NULL, '2,71828', 2.71828182846, NULL, NULL, NULL, NULL, 5, 0.0001, '{"calc":"newton","f":"x-x*ln(x)","df":"-ln(x)","x0":2,"eps":0.00001,"K":10,"criterio":"relativo"}', 'Newton-Raphson: 4 iterações; x = 2,718282. O método convergiu na 4ª iteração: εₐ = 1,464×10⁻⁶ ≤ ε = 1,000×10⁻⁵.
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('ib5-04', 'A', '2,71828', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('ib5-04', 'B', '2,47364', 0, 'Não confere: refaça a conta passo a passo (veja a resolução).');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('ib5-04', 'C', '2,82701', 0, 'Não confere: refaça a conta passo a passo (veja a resolução).');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('ib5-04', 'D', '3,12602', 0, 'Não confere: refaça a conta passo a passo (veja a resolução).');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('ib5-04-r', 'ibmec-05', '4 · 1º passo', '5ª Lista de Cálculo Numérico', 'newton', 1, 'numero', 1, 'ib5-04', 'Newton-Raphson, 1º passo: f(x) = x − x·ln x, f′(x) = −ln x e x₀ = 2. Qual é x₁?', NULL, '2,88539', 2.88539008178, NULL, NULL, NULL, NULL, 5, NULL, '{"calc":"newton","f":"x-x*ln(x)","df":"-ln(x)","x0":2,"iteracoes":1}', 'Newton-Raphson: 1 iteração; x = 2,885390. 1 iterações, como pedido.
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('ib5-04-r', 'A', '2,72294', 0, 'Esse é o resultado com 2 iterações: uma a mais do que o pedido.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('ib5-04-r', 'B', '2,88539', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('ib5-04-r', 'C', '2,76997', 0, 'Não confere: refaça a conta passo a passo (veja a resolução).');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('ib5-04-r', 'D', '1,11461', 0, 'Sinal trocado na fórmula: o certo é xᵢ₊₁ = xᵢ − f(xᵢ)/f′(xᵢ).');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('ib5-05a', 'ibmec-05', '5 (a)', '5ª Lista de Cálculo Numérico', 'bissecao', 1, 'texto', 1, NULL, 'Considere a equação não linear 1 + sen x = x. Mostre que existe uma raiz real x̄ no intervalo (1, 2).', NULL, 'f(1) = 0,8415 > 0 e f(2) = −0,0907 < 0; f é contínua, então pelo Teorema 1 há raiz em (1, 2)', NULL, NULL, NULL, NULL, NULL, NULL, 0.0001, '{"calc":"texto","resumo":"Com f(x) = 1 + sen x − x: f(1) = 1 + 0,8415 − 1 = 0,8415 > 0 e f(2) = 1 + 0,9093 − 2 = −0,0907 < 0. Como f é contínua e f(1)·f(2) < 0, o Teorema 1 garante uma raiz em (1, 2)."}', 'Com f(x) = 1 + sen x − x: f(1) = 1 + 0,8415 − 1 = 0,8415 > 0 e f(2) = 1 + 0,9093 − 2 = −0,0907 < 0. Como f é contínua e f(1)·f(2) < 0, o Teorema 1 garante uma raiz em (1, 2).', NULL, 0, 'azul', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('ib5-05a', 'A', 'f(1,5) = 0', 0, 'f(1,5) ≈ 0,4975, não é zero.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('ib5-05a', 'B', 'f(1)·f(2) < 0 e f é contínua (Teorema 1)', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('ib5-05a', 'C', 'f(1) e f(2) são positivos', 0, 'f(2) = 1 + sen 2 − 2 ≈ −0,09 é negativo.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('ib5-05a', 'D', 'f′(x) > 0 em todo o intervalo', 0, 'O que garante a raiz é a troca de sinal de f, não o sinal de f′.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('ib5-05b', 'ibmec-05', '5 (b)', '5ª Lista de Cálculo Numérico', 'bissecao', 1, 'numero', 1, NULL, 'Para a equação 1 + sen x = x no intervalo (1, 2), estime quantas iterações seriam necessárias para aproximar x̄ com precisão ε = 0,01, utilizando o método da Bisseção.', NULL, '7', 7, NULL, NULL, NULL, NULL, 0, 0.1, '{"calc":"iteracoesBissecao","a":1,"b":2,"eps":0.01}', 'k > (log(1) − log(0,01))/log 2 = 6,6439, então k = 7.', NULL, 0, 'azul', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('ib5-05b', 'A', '10', 0, 'Confira a conta: k > (log(b₀ − a₀) − log ε)/log 2.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('ib5-05b', 'B', '8', 0, 'Uma a mais do que o necessário: k é o primeiro inteiro acima do limite.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('ib5-05b', 'C', '7', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('ib5-05b', 'D', '6', 0, 'k precisa ser o primeiro inteiro maior que (log(b₀ − a₀) − log ε)/log 2: arredondar para baixo deixa b − a ainda maior que ε.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('ib5-05c', 'ibmec-05', '5 (c)', '5ª Lista de Cálculo Numérico', 'newton', 2, 'numero', 0, NULL, 'Utilizando o método de Newton-Raphson, obtenha uma aproximação para a raiz de 1 + sen x = x em (1, 2), com precisão ε = 0,01, partindo de x₀ = 2.', NULL, '1,9346', 1.93456387382, NULL, NULL, NULL, NULL, 4, 0.005, '{"calc":"newton","f":"1+sin(x)-x","df":"cos(x)-1","x0":2,"eps":0.01,"K":10,"criterio":"relativo"}', 'Newton-Raphson: 2 iterações; x = 1,934564. O método convergiu na 2ª iteração: εₐ = 0,000717101 ≤ ε = 0,01.
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('ib5-05c', 'A', '−698,6058', 0, 'Calculadora em graus: nos métodos numéricos as funções trigonométricas usam radianos.');
