INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('ib5-06', 'ibmec-05', '6', '5ª Lista de Cálculo Numérico', 'newton', 2, 'programa', 0, NULL, 'Faça um programa que determine a raiz de uma equação através do método de Newton-Raphson. Refaça os exercícios 1, 2, 3, 4 e 5 utilizando este programa.', NULL, 'Atividade de programação: confira os exercícios no Terminal do site.', NULL, NULL, NULL, NULL, NULL, NULL, 0.0001, '{"calc":"texto","resumo":"Use o Terminal do site (aba Newton-Raphson) para conferir cada exercício: ele mostra a tabela i, xᵢ, f(xᵢ), f′(xᵢ), xᵢ₊₁ e Eᵣ%, igual à dos slides."}', 'Use o Terminal do site (aba Newton-Raphson) para conferir cada exercício: ele mostra a tabela i, xᵢ, f(xᵢ), f′(xᵢ), xᵢ₊₁ e Eᵣ%, igual à dos slides.', NULL, 0, 'azul', NULL);
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('ib5-07', 'ibmec-05', '7', '5ª Lista de Cálculo Numérico', 'secante', 2, 'numero', 0, NULL, 'Aplique o método da Secante (a derivada do Newton-Raphson substituída por f′(x) ≅ (f(xₖ) − f(xₖ₋₁))/(xₖ − xₖ₋₁)) à equação x − x·ln x = 0, com x₀ = 2 e x₁ = 3, ε = 10⁻⁵ e N = 10.', NULL, '2,71828', 2.71828182184, NULL, NULL, NULL, NULL, 5, 0.0001, '{"calc":"secante","f":"x-x*ln(x)","x0":2,"x1":3,"eps":0.00001,"K":10,"criterio":"relativo"}', 'Secante: 4 iterações; x = 2,718282. O método convergiu na 4ª iteração: εₐ = 6,291×10⁻⁶ ≤ ε = 1,000×10⁻⁵.
