INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('ib5-10-r', 'D', '1,3326', 0, 'Não confere: refaça a conta passo a passo (veja a resolução).');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l01-erros-01', 'lista-01', '1ª', 'Representação de Números e Erros', 'ponto-flutuante', 1, 'numero', 1, NULL, 'Para fazer contas, um engenheiro tem à sua disposição um dispositivo eletrônico que usa o sistema decimal de ponto flutuante (β, t, L, U) = (10, 4, −1023, 1024). A representação em ponto flutuante de um número α é denotada por fl(α). Nesse dispositivo, arredonda-se a parcela de α que não pode ser incorporada à mantissa de fl(α). Qual é o resultado final da operação fl(fl(x) + fl(y)), onde x = 273,95 e y = 21,13?', '0,2951 × 10³', '295,1', 295.1, 295.1, NULL, NULL, NULL, 1, NULL, '{"calc":"fl","t":4,"m":-1023,"M":1024,"modo":"arredondamento","expr":["+",273.95,21.13]}', 'fl(274 + 21,13) = fl(295,13) = 295,1. Resultado: 0,2951 × 10³.', NULL, 0, 'vermelha', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l01-erros-01', 'A', '295,0', 0, 'Esse resultado é com truncamento; o sistema do enunciado faz arredondamento.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l01-erros-01', 'B', '29,5', 0, 'Expoente errado: confira a normalização 0,d₁d₂d₃d₄ × 10ᵉ.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l01-erros-01', 'C', '2951,0', 0, 'Expoente errado: confira a normalização 0,d₁d₂d₃d₄ × 10ᵉ.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l01-erros-01', 'D', '295,1', 1, NULL);
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l01-erros-02', 'lista-01', '2ª', 'Representação de Números e Erros', 'ponto-flutuante', 2, 'numero', 0, NULL, 'Considere o sistema de ponto flutuante F(10, 4, −6, 9), que trunca a parcela que não pode ser incorporada à mantissa, e os números a = 0,9450 × 10⁴ e b = 0,1382 × 10². Nesse sistema, qual o resultado de (a × b) − (a + b)?', '0,1211 × 10⁶', '121000', 121000, 121100, NULL, NULL, NULL, 0, NULL, '{"calc":"fl","t":4,"m":-6,"M":9,"modo":"truncamento","expr":["-",["*",9450,13.82],["+",9450,13.82]]}', 'fl(9450 × 13,82) = fl(130599) = 130500; fl(9450 + 13,82) = fl(9463,82) = 9463; fl(130500 − 9463) = fl(121037) = 121000. Resultado: 0,1210 × 10⁶.', 'Com truncamento, como diz o enunciado, o resultado é 0,1210 × 10⁶. O gabarito da lista (0,1211 × 10⁶) é o que sai com arredondamento.', 1, 'vermelha', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l01-erros-02', 'A', '121100', 0, 'Esse resultado é com arredondamento; o sistema do enunciado faz truncamento. (É o valor que aparece no gabarito da lista: veja a observação da questão.)');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l01-erros-02', 'B', '1210000', 0, 'Expoente errado: confira a normalização 0,d₁d₂d₃d₄ × 10ᵉ.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l01-erros-02', 'C', '121000', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l01-erros-02', 'D', '12100', 0, 'Expoente errado: confira a normalização 0,d₁d₂d₃d₄ × 10ᵉ.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l01-erros-03', 'lista-01', '3ª', 'Representação de Números e Erros', 'ponto-flutuante', 2, 'numero', 0, NULL, 'Considere o sistema de ponto flutuante F(10, 4, −6, 6). Calcule S = 43560 + Σₖ₌₁¹⁰ 3 (somando da esquerda para a direita).', '0,4356 × 10⁵', '43560', 43560, 43560, NULL, NULL, NULL, 0, NULL, '{"calc":"fl","t":4,"m":-6,"M":6,"modo":"arredondamento","expr":["soma",43560,3,3,3,3,3,3,3,3,3,3]}', 'fl(43560 + 3) = 43560; fl(43560 + 3) = 43560; fl(43560 + 3) = 43560; fl(43560 + 3) = 43560; fl(43560 + 3) = 43560; fl(43560 + 3) = 43560; fl(43560 + 3) = 43560; fl(43560 + 3) = 43560; fl(43560 + 3) = 43560; fl(43560 + 3) = 43560. Resultado: 0,4356 × 10⁵.', NULL, 0, 'vermelha', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l01-erros-03', 'A', '43560', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l01-erros-03', 'B', '435600', 0, 'Expoente errado: confira a normalização 0,d₁d₂d₃d₄ × 10ᵉ.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l01-erros-03', 'C', '43590', 0, 'Somou na outra ordem: em ponto flutuante a ordem das parcelas muda o resultado.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l01-erros-03', 'D', '4356', 0, 'Expoente errado: confira a normalização 0,d₁d₂d₃d₄ × 10ᵉ.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l01-erros-04', 'lista-01', '4ª', 'Representação de Números e Erros', 'ponto-flutuante', 2, 'numero', 0, NULL, 'Considere o sistema de ponto flutuante F(10, 4, −6, 6). Calcule S = (Σₖ₌₁¹⁰ 3) + 43560.', '0,4359 × 10⁵', '43590', 43590, 43590, NULL, NULL, NULL, 0, NULL, '{"calc":"fl","t":4,"m":-6,"M":6,"modo":"arredondamento","expr":["soma",3,3,3,3,3,3,3,3,3,3,43560]}', 'fl(3 + 3) = 6; fl(6 + 3) = 9; fl(9 + 3) = 12; fl(12 + 3) = 15; fl(15 + 3) = 18; fl(18 + 3) = 21; fl(21 + 3) = 24; fl(24 + 3) = 27; fl(27 + 3) = 30; fl(30 + 43560) = 43590. Resultado: 0,4359 × 10⁵.', NULL, 0, 'vermelha', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l01-erros-04', 'A', '43590', 1, NULL);
