INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l01-erros-04', 'D', '43560', 0, 'Somou na outra ordem: em ponto flutuante a ordem das parcelas muda o resultado.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l01-erros-05', 'lista-01', '5ª', 'Representação de Números e Erros', 'ponto-flutuante', 2, 'numero', 0, NULL, 'Considere o sistema F(10, 4, −6, 6) e as somas S₁ = 43560 + Σₖ₌₁¹⁰ 3 e S₂ = (Σₖ₌₁¹⁰ 3) + 43560. Determine ε = (S₂ − S₁)/S₂, em porcentagem.', '0,07%', '0,07%', 0.0688231245699, 0.07, NULL, NULL, NULL, 2, NULL, '{"calc":"fl-erro","t":4,"modo":"arredondamento","s1":["soma",43560,3,3,3,3,3,3,3,3,3,3],"s2":["soma",3,3,3,3,3,3,3,3,3,3,43560]}', 'S₁ = 0,4356 × 10⁵ e S₂ = 0,4359 × 10⁵: ε = (S₂ − S₁)/S₂ = 0,0688%.', NULL, 0, 'vermelha', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l01-erros-05', 'A', '0,04%', 0, 'Não confere: refaça a conta passo a passo (veja a resolução).');
