INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l01-erros-06', 'lista-01', '6ª', 'Representação de Números e Erros', 'ponto-flutuante', 1, 'numero', 1, NULL, 'Considere o sistema de ponto flutuante F(β, t, L, U) = F(10, 3, −3, 4), que trunca a parcela que não pode ser incorporada à mantissa. Nesse sistema, qual o resultado de 10³ + 1 − 10³?', '0', '0', 0, 0, NULL, NULL, NULL, 0, NULL, '{"calc":"fl","t":3,"m":-3,"M":4,"modo":"truncamento","expr":["-",["+",1000,1],1000]}', 'fl(1000 + 1) = fl(1001) = 1000; fl(1000 − 1000) = fl(0) = 0. Resultado: 0.', NULL, 0, 'vermelha', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l01-erros-06', 'A', '3', 0, 'Não confere: refaça a conta passo a passo (veja a resolução).');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l01-erros-06', 'B', '1', 0, 'Conta exata, sem passar cada operação por fl(·): numa máquina de t dígitos cada resultado parcial é arredondado ou truncado.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l01-erros-06', 'C', '−6', 0, 'Não confere: refaça a conta passo a passo (veja a resolução).');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l01-erros-06', 'D', '0', 1, NULL);
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l01-erros-07', 'lista-01', '7ª', 'Representação de Números e Erros', 'ponto-flutuante', 1, 'numero', 1, NULL, 'Um dispositivo usa o sistema decimal de ponto flutuante (β, t, L, U) = (10, 4, −63, 64) e arredonda a parcela de α que não cabe na mantissa de fl(α). Qual é o resultado final da operação fl(fl(x) + fl(y)), onde x = 192,86 e y = 19,21?', '0,2121 × 10³', '212,1', 212.1, 212.1, NULL, NULL, NULL, 1, NULL, '{"calc":"fl","t":4,"m":-63,"M":64,"modo":"arredondamento","expr":["+",192.86,19.21]}', 'fl(192,9 + 19,21) = fl(212,11) = 212,1. Resultado: 0,2121 × 10³.', NULL, 0, 'vermelha', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l01-erros-07', 'A', '212,1', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l01-erros-07', 'B', '212,0', 0, 'Esse resultado é com truncamento; o sistema do enunciado faz arredondamento.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l01-erros-07', 'C', '2121,0', 0, 'Expoente errado: confira a normalização 0,d₁d₂d₃d₄ × 10ᵉ.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l01-erros-07', 'D', '21,2', 0, 'Expoente errado: confira a normalização 0,d₁d₂d₃d₄ × 10ᵉ.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l01-erros-08', 'lista-01', '8ª', 'Representação de Números e Erros', 'ponto-flutuante', 1, 'vetor', 1, NULL, 'Considere o sistema de ponto flutuante F(β, t, m, M) = (10, 3, −5, 5). Quais são o menor e o maior número em módulo representados nesse sistema, respectivamente?', '0,100 × 10⁻⁵ e 0,999 × 10⁵', '0,100 × 10⁻⁵ e 0,999 × 10⁵', NULL, NULL, '[0.000001,99900]', '[0.000001,99900]', NULL, 0, NULL, '{"calc":"fl-limites","t":3,"m":-5,"M":5}', 'Menor: 0,100 × 10⁻⁵; maior: 0,999 × 10⁵.', NULL, 0, 'vermelha', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l01-erros-08', 'A', '0,999 × 10⁻⁵ e 0,999 × 10⁴', 0, 'Expoentes deslocados: confira m e M.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l01-erros-08', 'B', '0,100 × 10⁻⁵ e 0,100 × 10⁶', 0, 'O maior número é 0,999… × 10ᴹ, que é menor que 10ᴹ.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l01-erros-08', 'C', '0,100 × 10⁻⁴ e 0,100 × 10⁶', 0, 'O menor positivo é 0,100… × 10ᵐ (não 10ᵐ) e o maior é 0,999… × 10ᴹ.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l01-erros-08', 'D', '0,100 × 10⁻⁵ e 0,999 × 10⁵', 1, NULL);
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l01-erros-09', 'lista-01', '9ª', 'Representação de Números e Erros', 'ponto-flutuante', 1, 'numero', 1, NULL, 'A região de overflow de um sistema de ponto flutuante F(β, t, m, M) = (10, 3, −3, M) é o conjunto O = {x ∈ ℝ | |x| > 9990}. Qual o valor da cota superior M?', 'M = +4', '4', 4, 4, NULL, NULL, NULL, 0, NULL, '{"calc":"fl-overflow-M","t":3,"limite":9990}', 'O maior número é 0,999 × 10ᴹ = 9990 ⇒ M = 4.', NULL, 0, 'vermelha', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l01-erros-09', 'A', '3', 0, 'Confira: o maior número é 0,999… × 10ᴹ e o menor positivo é 0,100… × 10ᵐ.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l01-erros-09', 'B', '4', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l01-erros-09', 'C', '−4', 0, 'Sinal do expoente trocado.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l01-erros-09', 'D', '5', 0, 'Confira: o maior número é 0,999… × 10ᴹ e o menor positivo é 0,100… × 10ᵐ.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l01-erros-10', 'lista-01', '10ª', 'Representação de Números e Erros', 'ponto-flutuante', 1, 'numero', 1, NULL, 'A região de underflow de um sistema de ponto flutuante F(β, t, m, M) = (10, 3, m, 4) é o conjunto U = {x ∈ ℝ | x ≠ 0 e |x| < 0,0001}. Qual o valor da cota inferior m?', 'm = −3 (na lista está escrito "a = −3")', '−3', -3, -3, NULL, NULL, NULL, 0, NULL, '{"calc":"fl-underflow-m","t":3,"limite":0.0001}', 'O menor positivo é 0,100 × 10ᵐ = 10ᵐ⁻¹ = 0,0001 ⇒ m = -3.', NULL, 0, 'vermelha', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l01-erros-10', 'A', '−2', 0, 'Confira: o maior número é 0,999… × 10ᴹ e o menor positivo é 0,100… × 10ᵐ.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l01-erros-10', 'B', '−3', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l01-erros-10', 'C', '3', 0, 'Sinal do expoente trocado.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l01-erros-10', 'D', '−4', 0, 'Confira: o maior número é 0,999… × 10ᴹ e o menor positivo é 0,100… × 10ᵐ.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l01-erros-11', 'lista-01', '11ª', 'Representação de Números e Erros', 'ponto-flutuante', 2, 'numero', 0, NULL, 'Considere o sistema de ponto flutuante F(10, 4, −10, 10), que trunca a parcela que não pode ser incorporada à mantissa, e os números a = 0,7237 × 10⁴, b = 0,2145 × 10⁻³ e c = 0,2885 × 10¹ (na lista, o terceiro aparece como "a"). Nesse sistema, qual o resultado de a + b − c?', '0,7234 × 10⁴', '7234', 7234, 7234, NULL, NULL, NULL, 0, NULL, '{"calc":"fl","t":4,"m":-10,"M":10,"modo":"truncamento","expr":["-",["+",7237,0.0002145],2.885]}', 'fl(7237 + 0,0002145) = fl(7237) = 7237; fl(7237 − 2,885) = fl(7234,11) = 7234. Resultado: 0,7234 × 10⁴.', NULL, 0, 'vermelha', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l01-erros-11', 'A', '6945', 0, 'Não confere: refaça a conta passo a passo (veja a resolução).');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l01-erros-11', 'B', '723', 0, 'Expoente errado: confira a normalização 0,d₁d₂d₃d₄ × 10ᵉ.');
