INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l01-zeros-01', 'lista-01', '1ª', 'Zeros de Funções Reais', 'newton', 2, 'numero', 0, NULL, 'Considere a equação não linear x − cos x = 0. Determine, com duas iterações, a raiz real no intervalo (0, 1), usando o método de Newton-Raphson. Use 5 casas decimais nos cálculos.', '0,73914', '0,73914', 0.73914, 0.73914, NULL, NULL, NULL, 5, NULL, '{"calc":"newton","f":"x-cos(x)","df":"1+sin(x)","x0":0.5,"iteracoes":2,"casas":5}', 'Newton-Raphson: 2 iterações; x = 0,73914. 2 iterações, como pedido.
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l01-zeros-01', 'A', '0,73909', 0, 'Esse é o resultado com 3 iterações: uma a mais do que o pedido.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l01-zeros-01', 'B', '0,73914', 1, NULL);
