INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l01-zeros-08', 'lista-01', '8ª', 'Zeros de Funções Reais', 'newton', 2, 'numero', 0, NULL, 'Seja a função f(x) = eˣ/2 − cos(2x). Depois de três iterações do método de Newton, com chute inicial x₀ = −1, determine aproximadamente o zero dessa função.', '−0,65388', '−0,65388', -0.653880945168, -0.65388, NULL, NULL, NULL, 5, NULL, '{"calc":"newton","f":"exp(x)/2-cos(2x)","df":"exp(x)/2+2sin(2x)","x0":-1,"iteracoes":3}', 'Newton-Raphson: 3 iterações; x = −0,653881. 3 iterações, como pedido.
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l01-zeros-08', 'A', '−4,03722', 0, 'Sinal trocado na fórmula: o certo é xᵢ₊₁ = xᵢ − f(xᵢ)/f′(xᵢ).');
