INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l01-zeros-08-r', 'lista-01', '8ª · 1º passo', 'Zeros de Funções Reais', 'newton', 1, 'numero', 1, 'l01-zeros-08', 'Newton-Raphson, 1º passo: f(x) = eˣ/2 − cos(2x), f′(x) = eˣ/2 + 2sen(2x) e x₀ = −1. Qual é x₁?', NULL, '−0,63290', -0.632897150601, NULL, NULL, NULL, NULL, 5, NULL, '{"calc":"newton","f":"exp(x)/2-cos(2x)","df":"exp(x)/2+2sin(2x)","x0":-1,"iteracoes":1}', 'Newton-Raphson: 1 iteração; x = −0,632897. 1 iterações, como pedido.
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l01-zeros-08-r', 'A', '−0,63290', 1, NULL);
