INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l01-zeros-28', 'lista-01', '28ª', 'Zeros de Funções Reais', 'bissecao', 1, 'numero', 0, NULL, 'Seja a função f(x) = x² − sen x. Usando o método da Bisseção no intervalo [0,86; 0,89] e 4 iterações, encontre uma aproximação para a raiz.', '0,87688', '0,87688', 0.876875, 0.87688, NULL, NULL, NULL, 5, NULL, '{"calc":"bissecao","f":"x^2-sin(x)","a":0.86,"b":0.89,"iteracoes":4}', 'Bisseção: 4 iterações; x = 0,876875. 4 iterações, como pedido.
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l01-zeros-28', 'A', '0,87594', 0, 'Esse é o resultado com 5 iterações: uma a mais do que o pedido.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l01-zeros-28', 'B', '0,87673', 0, 'Esse valor sai da Falsa Posição (média ponderada pelos valores de f). A Bisseção usa o valor médio xᵢ = (aᵢ + bᵢ)/2.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l01-zeros-28', 'C', '0,87688', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l01-zeros-28', 'D', '0,87875', 0, 'Esse é o resultado com 3 iterações: faltou uma.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l01-zeros-28-r', 'lista-01', '28ª · 1º passo', 'Zeros de Funções Reais', 'bissecao', 1, 'numero', 1, 'l01-zeros-28', 'Bisseção, 1º passo: f(x) = x² − sen x em [0,86; 0,89]. Qual é x₁?', NULL, '0,87500', 0.875, NULL, NULL, NULL, NULL, 5, NULL, '{"calc":"bissecao","f":"x^2-sin(x)","a":0.86,"b":0.89,"iteracoes":1}', 'Bisseção: 1 iteração; x = 0,875000. 1 iteração, como pedido.
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l01-zeros-28-r', 'A', '0,88250', 0, 'Esse é o resultado com 2 iterações: uma a mais do que o pedido.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l01-zeros-28-r', 'B', '0,87500', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l01-zeros-28-r', 'C', '0,87645', 0, 'Esse valor sai da Falsa Posição (média ponderada pelos valores de f). A Bisseção usa o valor médio xᵢ = (aᵢ + bᵢ)/2.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l01-zeros-28-r', 'D', '0,84000', 0, 'Não confere: refaça a conta passo a passo (veja a resolução).');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l02-01', 'lista-02', '1ª', 'Resolução de Sistemas Lineares', 'lu', 2, 'sistema', 0, NULL, 'Depois de aplicar o processo de fatoração LU ao sistema AX = B, com B = (9; 3; −2)ᵀ, foram encontradas as matrizes U = [3 −4 1; 0 10/3 5/3; 0 0 −7] e L = [1 0 0; 1/3 1 0; 4/3 8/5 1]. Qual é o sistema AX = B?', '3x₁ − 4x₂ + x₃ = 9; x₁ + 2x₂ + 2x₃ = 3; 4x₁ − 3x₃ = −2', '3x₁ − 4x₂ + x₃ = 9; x₁ + 2x₂ + 2x₃ = 3; 4x₁ − 3x₃ = −2', NULL, NULL, NULL, NULL, '{"A":[[3,-4,1],[1,2,2],[4,0,-3]],"b":[9,3,-2]}', 4, NULL, '{"calc":"lu-sistema","L":[[1,0,0],[0.3333333333333333,1,0],[1.3333333333333333,1.6,1]],"U":[[3,-4,1],[0,3.3333333333333335,1.6666666666666667],[0,0,-7]],"b":[9,3,-2]}', 'A = L·U (multiplique as matrizes) e o lado direito é o próprio B.', NULL, 0, 'vermelha', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l02-01', 'A', '3x₁ − 2,4x₂ + x₃ = 9; (10/3)x₁ + 6x₂ + (5/3)x₃ = 3; −(28/3)x₁ − 11,2x₂ − 7x₃ = −2', 0, 'Multiplicou U·L; o certo é A = L·U.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l02-01', 'B', '3x₁ − 4x₂ + x₃ = 9; x₁ + 2x₂ + 2x₃ = 3; 4x₁ − 3x₃ = −2', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l02-01', 'C', '3x₁ − 4x₂ + x₃ = 9; −x₁ + (14/3)x₂ + (4/3)x₃ = 3; −4x₁ − 11x₃ = −2', 0, 'Sinal dos multiplicadores trocado em L.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l02-01', 'D', '3x₁ − 4x₂ + x₃ = 9; (10/3)x₂ + (5/3)x₃ = 3; −7x₃ = −2', 0, 'Esse é o sistema triangular U·X = B: faltou multiplicar por L (A = L·U).');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l02-02', 'lista-02', '2ª', 'Resolução de Sistemas Lineares', 'erro-vetor', 1, 'numero', 1, NULL, 'Um processo iterativo para a determinação do vetor solução de um sistema linear fornece, nos passos k e k + 1, x⁽ᵏ⁾ = (1,573; 0,988; −2,034) e x⁽ᵏ⁺¹⁾ = (1,512; 1,012; −2,008). Qual a melhor aproximação do erro relativo?', '3%', '3%', 3.03784860558, 3, NULL, NULL, NULL, 0, 0.1, '{"calc":"erro-vetor","novo":[1.512,1.012,-2.008],"velho":[1.573,0.988,-2.034],"percentual":true}', 'd = máx|Δx| / máx|x| = 0,06100 / 2,00800 = 0,0304 = 3,04%.', NULL, 0, 'vermelha', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l02-02', 'A', '0%', 0, 'Esse é o erro relativo sem multiplicar por 100: a questão pede em porcentagem.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l02-02', 'B', '3%', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l02-02', 'C', '6%', 0, 'Somou todas as diferenças; o critério usa só a maior delas, máx|Δx|.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l02-02', 'D', '9%', 0, 'Não confere: refaça a conta passo a passo (veja a resolução).');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l02-03', 'lista-02', '3ª', 'Resolução de Sistemas Lineares', 'lu', 1, 'texto', 1, NULL, 'Considere o sistema linear Ma = c, com M ∈ ℝⁿˣⁿ e c ∈ ℝⁿ. Suponha que são conhecidas duas matrizes quadradas Q e R tais que QR = M, onde Q é triangular inferior e R é triangular superior. Então, pode-se resolver o sistema Ma = c resolvendo-se quais sistemas lineares?', 'Qb = c e Ra = b', 'Qb = c e Ra = b', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"Ma = c ⇔ Q(Ra) = c. Chamando b = Ra: primeiro Qb = c (substituição progressiva, Q é triangular inferior) e depois Ra = b (substituição regressiva, R é triangular superior)."}', 'Ma = c ⇔ Q(Ra) = c. Chamando b = Ra: primeiro Qb = c (substituição progressiva, Q é triangular inferior) e depois Ra = b (substituição regressiva, R é triangular superior).', NULL, 0, 'vermelha', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l02-03', 'A', 'Ra = c e Qb = a', 0, 'A ordem é ao contrário: Q (inferior) recebe o lado direito c.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l02-03', 'B', 'Qa = c e Rb = a', 0, 'A incógnita a aparece no sistema com R, porque M·a = Q·(R·a).');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l02-03', 'C', 'Rb = c e Qa = b', 0, 'R é a triangular superior: ela fica com a incógnita original a, no segundo sistema.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l02-03', 'D', 'Qb = c e Ra = b', 1, NULL);
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l02-04', 'lista-02', '4ª', 'Resolução de Sistemas Lineares', 'gauss', 2, 'matriz', 0, NULL, 'Depois da primeira etapa do Método de Eliminação de Gauss efetuada sobre a matriz ampliada [A|B] = [−2 5 −3 | 1; 3 2 −2 | −5; 5 1 3 | 8], qual é [A⁽¹⁾|B⁽¹⁾]?', '[−2 5 −3 | 1; 0 19/2 −13/2 | −7/2; 0 27/2 −9/2 | 21/2]', '[−2 5 −3 | 1; 0 9,5 −6,5 | −3,5; 0 13,5 −4,5 | 10,5]', NULL, NULL, NULL, NULL, '[[-2,5,-3,1],[0,9.5,-6.5,-3.5],[0,13.5,-4.5,10.5]]', 4, NULL, '{"calc":"gauss-etapa","A":[[-2,5,-3],[3,2,-2],[5,1,3]],"b":[1,-5,8],"etapa":1}', 'E₂⁽¹⁾ → E₂⁽⁰⁾ − (−3/2)E₁⁽⁰⁾; E₃⁽¹⁾ → E₃⁽⁰⁾ − (−5/2)E₁⁽⁰⁾', NULL, 0, 'vermelha', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l02-04', 'A', '[−2 5 −3 | 1; 6 −5,5 2,5 | −6,5; 10 −11,5 10,5 | 5,5]', 0, 'Somou m·E₁ em vez de subtrair: Eᵢ⁽¹⁾ → Eᵢ⁽⁰⁾ − mᵢ₁E₁⁽⁰⁾.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l02-04', 'B', '[−2 5 −3 | 1; 5/3 16/3 −4 | −13/3; 4,2 3 1,8 | 8,4]', 0, 'Multiplicador invertido: mᵢ₁ = aᵢ₁/a₁₁ (o pivô fica no denominador).');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l02-04', 'C', '[−2 5 −3 | 1; 0 9,5 −6,5 | −5; 0 13,5 −4,5 | 8]', 0, 'Esqueceu de aplicar a operação ao lado direito B.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l02-04', 'D', '[−2 5 −3 | 1; 0 9,5 −6,5 | −3,5; 0 13,5 −4,5 | 10,5]', 1, NULL);
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l02-04-r', 'lista-02', '4ª · multiplicador', 'Resolução de Sistemas Lineares', 'gauss', 1, 'numero', 1, 'l02-04', 'Etapa 1 da Eliminação de Gauss em [A|B] = [−2 5 −3 | 1; 3 2 −2 | −5; 5 1 3 | 8]: qual é o multiplicador m₂₁?', NULL, '−1,5000', -1.5, NULL, NULL, NULL, NULL, 4, NULL, '{"calc":"gauss-multiplicador","A":[[-2,5,-3],[3,2,-2],[5,1,3]],"i":2,"k":1}', 'm₂₁ = a₂₁/a₁₁ = 3/−2 = −1,5000.', NULL, 0, 'vermelha', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l02-04-r', 'A', '−1,5000', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l02-04-r', 'B', '−0,6667', 0, 'Fração invertida: mᵢₖ = aᵢₖ/aₖₖ (o pivô fica no denominador).');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l02-04-r', 'C', '1,5000', 0, 'Sinal trocado: mᵢₖ = aᵢₖ/aₖₖ, e a operação é Eᵢ − mᵢₖEₖ.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l02-04-r', 'D', '−1,4400', 0, 'Não confere: refaça a conta passo a passo (veja a resolução).');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l02-05', 'lista-02', '5ª', 'Resolução de Sistemas Lineares', 'lu', 2, 'sistema', 0, NULL, 'Depois de aplicar o processo de fatoração LU ao sistema Ax = b, com b = (3; 5; 1)ᵀ, foram encontradas as matrizes U = [2 −3 5; 0 −1 4; 0 0 3] e L = [1 0 0; 1 1 0; −2 −1 1]. Qual é o sistema Ax = b?', '2x₁ − 3x₂ + 5x₃ = 3; 2x₁ − 4x₂ + 9x₃ = 5; −4x₁ + 7x₂ − 11x₃ = 1', '2x₁ − 3x₂ + 5x₃ = 3; 2x₁ − 4x₂ + 9x₃ = 5; −4x₁ + 7x₂ − 11x₃ = 1', NULL, NULL, NULL, NULL, '{"A":[[2,-3,5],[2,-4,9],[-4,7,-11]],"b":[3,5,1]}', 4, NULL, '{"calc":"lu-sistema","L":[[1,0,0],[1,1,0],[-2,-1,1]],"U":[[2,-3,5],[0,-1,4],[0,0,3]],"b":[3,5,1]}', 'A = L·U (multiplique as matrizes) e o lado direito é o próprio B.', NULL, 0, 'vermelha', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l02-05', 'A', '2x₁ − 3x₂ + 5x₃ = 3; 2x₁ − 4x₂ + 9x₃ = 5; −4x₁ + 7x₂ − 11x₃ = 1', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l02-05', 'B', '2x₁ − 3x₂ + 5x₃ = 3; −x₂ + 4x₃ = 5; 3x₃ = 1', 0, 'Esse é o sistema triangular U·X = B: faltou multiplicar por L (A = L·U).');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l02-05', 'C', '−11x₁ − 8x₂ + 5x₃ = 3; −9x₁ − 5x₂ + 4x₃ = 5; −6x₁ − 3x₂ + 3x₃ = 1', 0, 'Multiplicou U·L; o certo é A = L·U.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l02-05', 'D', '2x₁ − 3x₂ + 5x₃ = 3; −2x₁ + 2x₂ − x₃ = 5; 4x₁ − 7x₂ + 17x₃ = 1', 0, 'Sinal dos multiplicadores trocado em L.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l02-06', 'lista-02', '6ª', 'Resolução de Sistemas Lineares', 'erro-vetor', 1, 'numero', 1, NULL, 'Um processo iterativo fornece, nos passos 6 e 7, x⁽⁶⁾ = (7,079; 2,038; 0,971) e x⁽⁷⁾ = (6,991; 1,981; 1,009). Qual a melhor aproximação do erro relativo?', '1,3%', '1,3%', 1.25876126448, 1.3, NULL, NULL, NULL, 1, NULL, '{"calc":"erro-vetor","novo":[6.991,1.981,1.009],"velho":[7.079,2.038,0.971],"percentual":true}', 'd = máx|Δx| / máx|x| = 0,08800 / 6,99100 = 0,0126 = 1,26%.', NULL, 0, 'vermelha', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l02-06', 'A', '0,0%', 0, 'Esse é o erro relativo sem multiplicar por 100: a questão pede em porcentagem.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l02-06', 'B', '1,3%', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l02-06', 'C', '2,6%', 0, 'Somou todas as diferenças; o critério usa só a maior delas, máx|Δx|.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l02-06', 'D', '0,1%', 0, 'Esse é o erro absoluto máx|Δx|: faltou dividir pelo maior |x|.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l02-07', 'lista-02', '7ª', 'Resolução de Sistemas Lineares', 'lu', 2, 'matriz', 0, NULL, 'Dada a matriz A = [1 1 1; 2 1 −1; 3 2 0], determine as matrizes L e U da fatoração LU.', 'L = [1 0 0; 2 1 0; 3 1 1] e U = [1 1 1; 0 −1 −3; 0 0 0]', 'L = [1 0 0; 2 1 0; 3 1 1] e U = [1 1 1; 0 −1 −3; 0 0 0]', NULL, NULL, NULL, NULL, '{"L":[[1,0,0],[2,1,0],[3,1,1]],"U":[[1,1,1],[0,-1,-3],[0,0,0]]}', 4, NULL, '{"calc":"lu","A":[[1,1,1],[2,1,-1],[3,2,0]]}', 'L guarda os multiplicadores; U é a matriz triangular superior da eliminação. det(A) = 0.', NULL, 0, 'vermelha', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l02-07', 'A', 'L = [1 0 0; 1 −1 0; 1 −3 0] e U = [1 2 3; 0 1 1; 0 0 1]', 0, 'Matrizes transpostas: L é a triangular inferior com 1 na diagonal, U é a triangular superior.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l02-07', 'B', 'L = [1 0 0; 2 1 0; 3 1 1] e U = [1 1 1; 0 −1 −3; 0 0 0]', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l02-07', 'C', 'L = [1 0 0; −2 1 0; −3 −1 1] e U = [1 1 1; 0 −1 −3; 0 0 0]', 0, 'Sinal dos multiplicadores trocado: em L ficam os mᵢₖ = aᵢₖ/aₖₖ, com o mesmo sinal.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l02-07', 'D', 'L = [1 0 0; 2 1 0; 3 1 1] e U = [1 1 1; 0 −1 −3; 0 0 2]', 0, 'A última etapa não confere: refaça E₃ − m₃₂E₂.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l02-08', 'lista-02', '7ª (repetida)', 'Resolução de Sistemas Lineares', 'lu', 2, 'sistema', 0, NULL, 'Depois de aplicar o processo de fatoração LU ao sistema AX = B, com B = (1; 4; 4)ᵀ, foram encontradas as matrizes U = [1 1 1; 0 −1 −3; 0 0 1] e L = [1 0 0; 2 1 0; 3 1 1]. Qual é o sistema AX = B?', 'x₁ + x₂ + x₃ = 1; 2x₁ + x₂ − x₃ = 4; 3x₁ + 2x₂ + x₃ = 4', 'x₁ + x₂ + x₃ = 1; 2x₁ + x₂ − x₃ = 4; 3x₁ + 2x₂ + x₃ = 4', NULL, NULL, NULL, NULL, '{"A":[[1,1,1],[2,1,-1],[3,2,1]],"b":[1,4,4]}', 4, NULL, '{"calc":"lu-sistema","L":[[1,0,0],[2,1,0],[3,1,1]],"U":[[1,1,1],[0,-1,-3],[0,0,1]],"b":[1,4,4]}', 'A = L·U (multiplique as matrizes) e o lado direito é o próprio B.', 'Na lista esta questão aparece numerada de novo como 7ª.', 0, 'vermelha', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l02-08', 'A', 'x₁ + x₂ + x₃ = 1; 2x₁ + x₂ − x₃ = 4; 3x₁ + 2x₂ + x₃ = 4', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l02-08', 'B', 'x₁ + x₂ + x₃ = 1; −x₂ − 3x₃ = 4; x₃ = 4', 0, 'Esse é o sistema triangular U·X = B: faltou multiplicar por L (A = L·U).');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l02-08', 'C', '6x₁ + 2x₂ + x₃ = 1; −11x₁ − 4x₂ − 3x₃ = 4; 3x₁ + x₂ + x₃ = 4', 0, 'Multiplicou U·L; o certo é A = L·U.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l02-08', 'D', 'x₁ + x₂ + x₃ = 1; −2x₁ − 3x₂ − 5x₃ = 4; −3x₁ − 2x₂ + x₃ = 4', 0, 'Sinal dos multiplicadores trocado em L.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l02-09', 'lista-02', '9ª', 'Resolução de Sistemas Lineares', 'erro-vetor', 1, 'numero', 1, NULL, 'Um processo iterativo fornece, nos passos 8 e 9, x⁽⁸⁾ = (0,17780; 0,66953; −0,59288; −0,21891; −0,59286) e x⁽⁹⁾ = (0,15008; 0,64623; −0,60945; −0,25199; −0,60947). Determine o erro relativo.', '0,051', '0,051', 0.0511892050818, 0.051, NULL, NULL, NULL, 3, NULL, '{"calc":"erro-vetor","novo":[0.15008,0.64623,-0.60945,-0.25199,-0.60947],"velho":[0.1778,0.66953,-0.59288,-0.21891,-0.59286]}', 'd = máx|Δx| / máx|x| = 0,03308 / 0,64623 = 0,0512.', NULL, 0, 'vermelha', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l02-09', 'A', '5,119', 0, 'Esse é o erro em porcentagem; a questão pede o valor relativo, sem multiplicar por 100.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l02-09', 'B', '0,051', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l02-09', 'C', '0,049', 0, 'Dividiu pelo maior |x| da iteração anterior; o critério usa o vetor novo: d = máx|Δx| / máx|x⁽ᵏ⁺¹⁾|.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l02-09', 'D', '0,181', 0, 'Somou todas as diferenças; o critério usa só a maior delas, máx|Δx|.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l02-10', 'lista-02', '10ª', 'Resolução de Sistemas Lineares', 'pivoteamento', 3, 'texto', 0, NULL, 'Resolva o sistema 10⁻⁸x₁ + x₂ = 2 + 10⁻⁸; x₁ + x₂ = 3 por eliminação gaussiana (EG) e por eliminação gaussiana com pivoteamento parcial (EGPP), num sistema de ponto flutuante de base 10 com precisão 5 (mantissa de 5 dígitos) e expoentes entre −10 e 10. Quais são os resultados?', 'EG = (0; 2), EGPP = (1; 2)', 'EG = (0,0000; 2,0000), EGPP = (1,0000; 2,0000)', NULL, NULL, '[0,2,1,2]', '[0,2,1,2]', NULL, NULL, NULL, '{"calc":"gauss-eg-egpp","A":[[1e-8,1],[1,1]],"b":[2.00000001,3],"t":5}', 'Com 5 dígitos na mantissa: sem pivoteamento, EG = (0,0000; 2,0000); com pivoteamento parcial (troca para o maior |aᵢ₁|), EGPP = (1,0000; 2,0000).', NULL, 0, 'vermelha', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l02-10', 'A', 'EG = (1; 2), EGPP = (0; 2)', 0, 'É o contrário: o pivoteamento parcial é que salva o x₁.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l02-10', 'B', 'EG = (0; 2), EGPP = (1; 2)', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l02-10', 'C', 'EG = (0; 2), EGPP = (0; 2)', 0, 'Com a troca de linhas o multiplicador fica 10⁻⁸ e o x₁ = 1 aparece certo.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l02-10', 'D', 'EG = (1; 2), EGPP = (1; 2)', 0, 'Com só 5 dígitos, o pivô 10⁻⁸ gera m₂₁ = 10⁸ e o x₁ da EG se perde.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l02-11', 'lista-02', '11ª', 'Resolução de Sistemas Lineares', 'pivoteamento', 3, 'texto', 0, NULL, 'Resolva o sistema 10⁻⁵x₁ + x₂ = 2 + 10⁻⁵; x₁ + x₂ = 3 por EG e por EGPP, num sistema de ponto flutuante de base 10 com precisão 10 e expoentes entre −10 e 10. Quais são os resultados?', 'EG = (1; 2), EGPP = (1; 2)', 'EG = (1,0000; 2,0000), EGPP = (1,0000; 2,0000)', NULL, NULL, '[1,2,1,2]', '[1,2,1,2]', NULL, NULL, NULL, '{"calc":"gauss-eg-egpp","A":[[0.00001,1],[1,1]],"b":[2.00001,3],"t":10}', 'Com 10 dígitos na mantissa: sem pivoteamento, EG = (1,0000; 2,0000); com pivoteamento parcial (troca para o maior |aᵢ₁|), EGPP = (1,0000; 2,0000).', NULL, 0, 'vermelha', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l02-11', 'A', 'EG = (0; 3), EGPP = (1; 2)', 0, 'x₂ = 2 sai igual nas duas: só x₁ corre risco.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l02-11', 'B', 'EG = (0; 2), EGPP = (1; 2)', 0, 'Isso acontece com 5 dígitos e pivô 10⁻⁸ (questão anterior). Com 10 dígitos o 10⁻⁵ ainda cabe na conta.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l02-11', 'C', 'EG = (1; 2), EGPP = (0; 2)', 0, 'O pivoteamento parcial nunca piora este caso.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l02-11', 'D', 'EG = (1; 2), EGPP = (1; 2)', 1, NULL);
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l02-12', 'lista-02', '12ª', 'Resolução de Sistemas Lineares', 'pivoteamento', 2, 'texto', 0, NULL, 'Durante o uso do algoritmo de eliminação gaussiana com pivoteamento parcial, ao encontrarmos um pivô nulo, qual ou quais das três situações são possíveis? 1. O sistema tem uma única solução. 2. O sistema tem infinitas soluções. 3. O sistema não tem solução.', 'Todas as três podem ocorrer', 'Todas as três podem ocorrer', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"Um zero na posição do pivô, por si só, não decide nada: se existir um elemento não nulo abaixo dele, trocamos as linhas (pivoteamento) e a solução pode ser única. Se a coluna inteira abaixo for nula, A é singular e o sistema tem infinitas soluções ou nenhuma, conforme o lado direito (slides: sistemas singulares)."}', 'Um zero na posição do pivô, por si só, não decide nada: se existir um elemento não nulo abaixo dele, trocamos as linhas (pivoteamento) e a solução pode ser única. Se a coluna inteira abaixo for nula, A é singular e o sistema tem infinitas soluções ou nenhuma, conforme o lado direito (slides: sistemas singulares).', NULL, 0, 'vermelha', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l02-12', 'A', 'Nenhuma: o algoritmo sempre para com erro', 0, 'O pivoteamento existe justamente para contornar o pivô nulo.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l02-12', 'B', 'Todas as três podem ocorrer', 1, 'Se houver um elemento não nulo abaixo, a troca de linhas resolve e a solução pode ser única; se a coluna inteira for nula, A é singular e sobram infinitas soluções ou nenhuma.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l02-12', 'C', 'Só a 2 e a 3', 0, 'Um zero na diagonal antes da troca não impede solução única: basta trocar a equação pivô.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l02-12', 'D', 'Só a 1 (solução única)', 0, 'Quando toda a coluna é nula, a matriz é singular e não há solução única.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l02-13', 'lista-02', '13ª', 'Resolução de Sistemas Lineares', 'lu', 1, 'numero', 1, NULL, 'Considere a matriz B = LU, onde L = [1 0 0 0; 1/2 1 0 0; 0 −1/4 1 0; 0 0 −2 1] e U = [2 −4 0 0; 0 4 12 0; 0 0 −1 −5; 0 0 0 1]. Qual o determinante de B?', '−8', '−8', -8, -8, NULL, NULL, NULL, 0, NULL, '{"calc":"det-lu","L":[[1,0,0,0],[0.5,1,0,0],[0,-0.25,1,0],[0,0,-2,1]],"U":[[2,-4,0,0],[0,4,12,0],[0,0,-1,-5],[0,0,0,1]]}', 'det(B) = det(L)·det(U) = 1 · (2 · 4 · −1 · 1) = −8.', NULL, 0, 'vermelha', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l02-13', 'A', '−5', 0, 'Não confere: refaça a conta passo a passo (veja a resolução).');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l02-13', 'B', '−8', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l02-13', 'C', '6', 0, 'Isso é a soma da diagonal de U (o traço); o determinante é o produto.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l02-13', 'D', '8', 0, 'Sinal trocado: det(B) = det(L)·det(U), com det(L) = 1.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l02-14', 'lista-02', '14ª', 'Resolução de Sistemas Lineares', 'lu', 2, 'matriz', 0, NULL, 'Dada a matriz A = [1 1 1; 2 1 −1; 3 2 0], determine as matrizes L e U.', 'L = [1 0 0; 2 1 0; 3 1 1] e U = [1 1 1; 0 −1 −3; 0 0 0]', 'L = [1 0 0; 2 1 0; 3 1 1] e U = [1 1 1; 0 −1 −3; 0 0 0]', NULL, NULL, NULL, NULL, '{"L":[[1,0,0],[2,1,0],[3,1,1]],"U":[[1,1,1],[0,-1,-3],[0,0,0]]}', 4, NULL, '{"calc":"lu","A":[[1,1,1],[2,1,-1],[3,2,0]]}', 'L guarda os multiplicadores; U é a matriz triangular superior da eliminação. det(A) = 0.', 'Igual à 7ª questão desta lista.', 0, 'vermelha', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l02-14', 'A', 'L = [1 0 0; 2 1 0; 3 1 1] e U = [1 1 1; 0 −1 −3; 0 0 2]', 0, 'A última etapa não confere: refaça E₃ − m₃₂E₂.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l02-14', 'B', 'L = [1 0 0; 2 1 0; 3 1 1] e U = [1 1 1; 0 −1 −3; 0 0 0]', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l02-14', 'C', 'L = [1 0 0; 1 −1 0; 1 −3 0] e U = [1 2 3; 0 1 1; 0 0 1]', 0, 'Matrizes transpostas: L é a triangular inferior com 1 na diagonal, U é a triangular superior.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l02-14', 'D', 'L = [1 0 0; −2 1 0; −3 −1 1] e U = [1 1 1; 0 −1 −3; 0 0 0]', 0, 'Sinal dos multiplicadores trocado: em L ficam os mᵢₖ = aᵢₖ/aₖₖ, com o mesmo sinal.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l02-15', 'lista-02', '15ª', 'Resolução de Sistemas Lineares', 'gauss', 2, 'matriz', 0, NULL, 'Depois da primeira etapa do Método de Eliminação de Gauss sobre [A|B] = [−2 5 −3 | 1; 3 2 −2 | −5; 5 1 3 | 8], qual é [A⁽¹⁾|B⁽¹⁾]?', '[−2 5 −3 | 1; 0 19/2 −13/2 | −7/2; 0 27/2 −9/2 | 21/2]', '[−2 5 −3 | 1; 0 9,5 −6,5 | −3,5; 0 13,5 −4,5 | 10,5]', NULL, NULL, NULL, NULL, '[[-2,5,-3,1],[0,9.5,-6.5,-3.5],[0,13.5,-4.5,10.5]]', 4, NULL, '{"calc":"gauss-etapa","A":[[-2,5,-3],[3,2,-2],[5,1,3]],"b":[1,-5,8],"etapa":1}', 'E₂⁽¹⁾ → E₂⁽⁰⁾ − (−3/2)E₁⁽⁰⁾; E₃⁽¹⁾ → E₃⁽⁰⁾ − (−5/2)E₁⁽⁰⁾', 'Igual à 4ª questão desta lista.', 0, 'vermelha', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l02-15', 'A', '[−2 5 −3 | 1; 6 −5,5 2,5 | −6,5; 10 −11,5 10,5 | 5,5]', 0, 'Somou m·E₁ em vez de subtrair: Eᵢ⁽¹⁾ → Eᵢ⁽⁰⁾ − mᵢ₁E₁⁽⁰⁾.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l02-15', 'B', '[−2 5 −3 | 1; 0 9,5 −6,5 | −5; 0 13,5 −4,5 | 8]', 0, 'Esqueceu de aplicar a operação ao lado direito B.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l02-15', 'C', '[−2 5 −3 | 1; 0 9,5 −6,5 | −3,5; 0 13,5 −4,5 | 10,5]', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l02-15', 'D', '[−2 5 −3 | 1; 5/3 16/3 −4 | −13/3; 4,2 3 1,8 | 8,4]', 0, 'Multiplicador invertido: mᵢ₁ = aᵢ₁/a₁₁ (o pivô fica no denominador).');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l02-16', 'lista-02', '16ª', 'Resolução de Sistemas Lineares', 'criterios', 2, 'numero', 0, NULL, 'Seja o sistema linear x₁ + 0,4x₂ − 0,1x₃ + 0,1x₄ = 0,3; 0,3x₁ + 0,2x₂ − 0,2x₃ − 0,1x₄ = −2,5; −0,1x₁ − 0,2x₂ + 0,6x₃ + 0,2x₄ = 1,2; 0,1x₁ + 0,3x₂ + 0,2x₃ + x₄ = −2,4. Para essa disposição de linhas e colunas, o critério de Sassenfeld fornece que valor para β?', 'β = 0,6', '2,40', 2.4, 0.6, NULL, NULL, NULL, 2, NULL, '{"calc":"sassenfeld","A":[[1,0.4,-0.1,0.1],[0.3,0.2,-0.2,-0.1],[-0.1,-0.2,0.6,0.2],[0.1,0.3,0.2,1]]}', 'β = (0,6000; 2,4000; 1,2333; 1,0267); β = máx βᵢ = 2,4000.', 'O gabarito da lista (β = 0,6) é só o β₁. O critério de Sassenfeld usa β = máx βᵢ, e aqui β₂ = 2,4: como β > 1, o critério não garante a convergência nessa disposição.', 1, 'vermelha', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l02-16', 'A', '2,40', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l02-16', 'B', '3,00', 0, 'Esse é o máx αᵢ do critério das linhas, não o β de Sassenfeld.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l02-16', 'C', '0,60', 0, 'Esse é só o β₁. O critério de Sassenfeld usa β = máx βᵢ. (É o valor que aparece no gabarito da lista: veja a observação da questão.)');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l02-16', 'D', '1,23', 0, 'Esse é o β₃; o critério usa o maior βᵢ.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l02-16-r', 'lista-02', '16ª · β₁', 'Resolução de Sistemas Lineares', 'criterios', 1, 'numero', 1, 'l02-16', 'Critério de Sassenfeld para A = [1 0,4 −0,1 0,1; 0,3 0,2 −0,2 −0,1; −0,1 −0,2 0,6 0,2; 0,1 0,3 0,2 1]: qual é β₁ = (|a₁₂| + … + |a₁ₙ|)/|a₁₁|?', NULL, '0,6000', 0.6, NULL, NULL, NULL, NULL, 4, NULL, '{"calc":"sassenfeld","A":[[1,0.4,-0.1,0.1],[0.3,0.2,-0.2,-0.1],[-0.1,-0.2,0.6,0.2],[0.1,0.3,0.2,1]],"indice":1}', 'β₁ = 0,6000 (β = (0,6000; 2,4000; 1,2333; 1,0267)).', NULL, 0, 'vermelha', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l02-16-r', 'A', '3,0000', 0, 'Esse é o máx αᵢ do critério das linhas, não o β de Sassenfeld.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l02-16-r', 'B', '0,6000', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l02-16-r', 'C', '2,4000', 0, 'Esse é o β₂.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l02-16-r', 'D', '1,2333', 0, 'Esse é o β₃.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l02-17', 'lista-02', '17ª', 'Resolução de Sistemas Lineares', 'erro-vetor', 1, 'numero', 1, NULL, 'Um processo iterativo fornece, nos passos 8 e 9, x⁽⁸⁾ = (−0,17621; −0,63841; 0,57311; 0,20738; 0,57194) e x⁽⁹⁾ = (−0,15998; −0,64912; 0,61725; 0,26008; 0,61336). Qual a melhor aproximação do erro relativo no 9º passo?', '6,4%', '8,1%', 8.11868375647, 6.4, NULL, NULL, NULL, 1, NULL, '{"calc":"erro-vetor","novo":[-0.15998,-0.64912,0.61725,0.26008,0.61336],"velho":[-0.17621,-0.63841,0.57311,0.20738,0.57194],"percentual":true}', 'd = máx|Δx| / máx|x| = 0,05270 / 0,64912 = 0,0812 = 8,12%.', 'O gabarito da lista (6,4%) não sai da fórmula d = máx|Δx| / máx|x|: a maior diferença é 0,05270 (4ª componente) e o maior |x⁽⁹⁾| é 0,64912, o que dá 8,1%.', 1, 'vermelha', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l02-17', 'A', '8,3%', 0, 'Dividiu pelo maior |x| da iteração anterior; o critério usa o vetor novo: d = máx|Δx| / máx|x⁽ᵏ⁺¹⁾|.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l02-17', 'B', '0,1%', 0, 'Esse é o erro relativo sem multiplicar por 100: a questão pede em porcentagem.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l02-17', 'C', '8,1%', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l02-17', 'D', '25,4%', 0, 'Somou todas as diferenças; o critério usa só a maior delas, máx|Δx|.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l02-18', 'lista-02', '18ª', 'Resolução de Sistemas Lineares', 'erro-vetor', 1, 'numero', 1, NULL, 'Um processo iterativo fornece, nos passos 6 e 7, x⁽⁶⁾ = (0,16791; 0,71865; −0,53142; −0,22716; −0,59173) e x⁽⁷⁾ = (0,17382; 0,73170; −0,51010; −0,18119; −0,57937). Qual a melhor aproximação do erro relativo na 7ª iteração?', '0,063', '0,063', 0.0628262949296, 0.063, NULL, NULL, NULL, 3, NULL, '{"calc":"erro-vetor","novo":[0.17382,0.7317,-0.5101,-0.18119,-0.57937],"velho":[0.16791,0.71865,-0.53142,-0.22716,-0.59173]}', 'd = máx|Δx| / máx|x| = 0,04597 / 0,73170 = 0,0628.', NULL, 0, 'vermelha', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l02-18', 'A', '0,063', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l02-18', 'B', '0,064', 0, 'Dividiu pelo maior |x| da iteração anterior; o critério usa o vetor novo: d = máx|Δx| / máx|x⁽ᵏ⁺¹⁾|.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l02-18', 'C', '6,283', 0, 'Esse é o erro em porcentagem; a questão pede o valor relativo, sem multiplicar por 100.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l02-18', 'D', '0,135', 0, 'Somou todas as diferenças; o critério usa só a maior delas, máx|Δx|.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l03-01', 'lista-03', '1ª', 'Gauss-Jacobi e Gauss-Seidel', 'seidel', 2, 'vetor', 0, NULL, 'Efetuando os cálculos com três casas decimais e apenas duas iterações, determine a solução do sistema AX = B pelo método de Gauss-Seidel, onde A = [8 1 −1; 1 −7 2; 2 1 9], B = (8; −4; 12) e X⁽⁰⁾ = (0; 0; 0).', '(1,03968; 1,01474; 0,98954)', '(1,0397; 1,0147; 0,9895)', NULL, NULL, '[1.03968253968,1.01473922902,0.989543965734]', '[1.03968,1.01474,0.98954]', NULL, 4, 0.002, '{"calc":"seidel","A":[[8,1,-1],[1,-7,2],[2,1,9]],"b":[8,-4,12],"x0":[0,0,0],"iteracoes":2}', 'Gauss-Seidel: X⁽2⁾ = (1,03968; 1,01474; 0,98954).
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l03-01', 'A', '(1,0397; 1,0147; 0,9895)', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l03-01', 'B', '(1,0952; 1,0952; 1,0476)', 0, 'Esse é o resultado do Gauss-Jacobi. No Seidel, cada valor novo entra na hora no cálculo dos seguintes.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l03-01', 'C', '(1,0000; 0,7143; 1,0317)', 0, 'Esse é o vetor depois de 1 iteração: faltou uma.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l03-01', 'D', '(0,9969; 0,9966; 1,0011)', 0, 'Esse é o vetor depois de 3 iterações: uma a mais.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l03-01-r', 'lista-03', '1ª · 1ª componente', 'Gauss-Jacobi e Gauss-Seidel', 'seidel', 1, 'numero', 1, 'l03-01', 'Gauss-Seidel, 1ª iteração: A = [8 1 −1; 1 −7 2; 2 1 9], B = (8; −4; 12) e X⁽⁰⁾ = (0; 0; 0). Qual é x₁⁽¹⁾?', NULL, '1,0000', 1, NULL, NULL, NULL, NULL, 4, NULL, '{"calc":"seidel","A":[[8,1,-1],[1,-7,2],[2,1,9]],"b":[8,-4,12],"x0":[0,0,0],"iteracoes":1,"componente":1}', 'Gauss-Seidel: x₁⁽¹⁾ = 1,00000.
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l03-01-r', 'A', '1,5000', 0, 'Não confere: x₁ = b₁/a₁₁ quando X⁽⁰⁾ = 0.');
