INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l03-03', 'lista-03', '3ª', 'Gauss-Jacobi e Gauss-Seidel', 'seidel', 1, 'vetor', 0, NULL, 'Considere o sistema x₁ + x₂ + x₃ = 10; x₁ − 2x₂ + x₃ = 4; x₁ + x₃ = 8 e o vetor obtido no passo 6 pelo método de Gauss-Seidel, x⁽⁶⁾ = (7,079; 2,038; 0,971). Obtenha o resultado para o 7º passo.', '(6,991; 1,981; 1,009)', '(6,991; 1,981; 1,009)', NULL, NULL, '[6.991,1.981,1.009]', '[6.991,1.981,1.009]', NULL, 3, NULL, '{"calc":"seidel","A":[[1,1,1],[1,-2,1],[1,0,1]],"b":[10,4,8],"x0":[7.079,2.038,0.971],"iteracoes":1}', 'Gauss-Seidel: X⁽1⁾ = (6,99100; 1,98100; 1,00900).
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l03-03', 'A', '(6,991; 2,025; 0,921)', 0, 'Esse é o resultado do Gauss-Jacobi. No Seidel, cada valor novo entra na hora no cálculo dos seguintes.');
