INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l03-03-r', 'lista-03', '3ª · 1ª componente', 'Gauss-Jacobi e Gauss-Seidel', 'seidel', 1, 'numero', 1, 'l03-03', 'Gauss-Seidel, 1ª iteração: A = [1 1 1; 1 −2 1; 1 0 1], B = (10; 4; 8) e X⁽⁰⁾ = (7,079; 2,038; 0,971). Qual é x₁⁽¹⁾?', NULL, '6,9910', 6.991, NULL, NULL, NULL, NULL, 4, NULL, '{"calc":"seidel","A":[[1,1,1],[1,-2,1],[1,0,1]],"b":[10,4,8],"x0":[7.079,2.038,0.971],"iteracoes":1,"componente":1}', 'Gauss-Seidel: x₁⁽¹⁾ = 6,99100.
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l03-03-r', 'A', '13,0090', 0, 'Sinal trocado: x₁ = (b₁ − a₁₂x₂ − a₁₃x₃ − …)/a₁₁.');
