INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l03-12', 'lista-03', '12ª', 'Gauss-Jacobi e Gauss-Seidel', 'jacobi', 2, 'vetor', 0, NULL, 'Aplique o método de Gauss-Jacobi ao sistema 4x₁ − 2x₂ − x₃ = 10; −2x₁ + 9x₂ − 5x₄ = −5; −x₁ + 6x₃ − 3x₄ = 0; −5x₂ − 3x₃ + 10x₄ = 0, com apenas três iterações e X⁽⁰⁾ = (2,0; 0,1; 0,5; 0,2).', '(2,7115; 0,0963; 0,4997; 0,2388)', '(2,7115; 0,0963; 0,4997; 0,2388)', NULL, NULL, '[2.71145833333,0.0962962962963,0.499722222222,0.23875]', '[2.7115,0.0963,0.4997,0.2388]', NULL, 4, NULL, '{"calc":"jacobi","A":[[4,-2,-1,0],[-2,9,0,-5],[-1,0,6,-3],[0,-5,-3,10]],"b":[10,-5,0,0],"x0":[2,0.1,0.5,0.2],"iteracoes":3}', 'Gauss-Jacobi: X⁽3⁾ = (2,71146; 0,09630; 0,49972; 0,23875).
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l03-12', 'A', '(2,6083; 0,1500; 0,5458; 0,1300)', 0, 'Esse é o vetor depois de 2 iterações: faltou uma.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l03-12', 'B', '(2,7326; 0,1968; 0,5860; 0,2742)', 0, 'Esse é o resultado do Gauss-Seidel. No Jacobi, toda a iteração usa só os valores da iteração anterior.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l03-12', 'C', '(2,6731; 0,1796; 0,5713; 0,1981)', 0, 'Esse é o vetor depois de 4 iterações: uma a mais.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l03-12', 'D', '(2,7115; 0,0963; 0,4997; 0,2388)', 1, NULL);
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l03-12-r', 'lista-03', '12ª · 1ª componente', 'Gauss-Jacobi e Gauss-Seidel', 'jacobi', 1, 'numero', 1, 'l03-12', 'Gauss-Jacobi, 1ª iteração: A = [4 −2 −1 0; −2 9 0 −5; −1 0 6 −3; 0 −5 −3 10], B = (10; −5; 0; 0) e X⁽⁰⁾ = (2; 0,1; 0,5; 0,2). Qual é x₁⁽¹⁾?', NULL, '2,6750', 2.675, NULL, NULL, NULL, NULL, 4, NULL, '{"calc":"jacobi","A":[[4,-2,-1,0],[-2,9,0,-5],[-1,0,6,-3],[0,-5,-3,10]],"b":[10,-5,0,0],"x0":[2,0.1,0.5,0.2],"iteracoes":1,"componente":1}', 'Gauss-Jacobi: x₁⁽¹⁾ = 2,67500.
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l03-12-r', 'A', '2,5000', 0, 'Ignorou os termos com os valores de X⁽⁰⁾.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l03-12-r', 'B', '2,6750', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l03-12-r', 'C', '10,7000', 0, 'Faltou dividir por a₁₁.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l03-12-r', 'D', '2,3250', 0, 'Sinal trocado: x₁ = (b₁ − a₁₂x₂ − a₁₃x₃ − …)/a₁₁.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l03-13', 'lista-03', '13ª', 'Gauss-Jacobi e Gauss-Seidel', 'cholesky', 1, 'matriz', 1, NULL, 'A matriz M admite uma fatoração de Cholesky cuja matriz triangular superior é R = [2 1 −2; 0 3 2; 0 0 1]. Qual é a matriz M?', 'M = [4 2 −4; 2 10 4; −4 4 9]', 'M = [4 2 −4; 2 10 4; −4 4 9]', NULL, NULL, NULL, NULL, '{"M":[[4,2,-4],[2,10,4],[-4,4,9]]}', 4, NULL, '{"calc":"cholesky-M","R":[[2,1,-2],[0,3,2],[0,0,1]]}', 'M = Rᵀ·R (a transposta da triangular superior vezes ela mesma).', NULL, 0, 'vermelha', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l03-13', 'A', 'M = [9 −1 −2; −1 13 2; −2 2 1]', 0, 'Multiplicou R·Rᵀ; com R triangular superior, M = Rᵀ·R.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l03-13', 'B', 'M = [4 1 −2; 1 9 2; −2 2 1]', 0, 'Elevou só a diagonal ao quadrado: cada mᵢⱼ é uma soma de produtos (Rᵀ·R).');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l03-13', 'C', 'M = [4 2 −4; 2 10 4; −4 4 9]', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l03-13', 'D', 'M = [4 −2 4; −2 10 −4; 4 −4 9]', 0, 'Sinais fora da diagonal trocados.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l03-14', 'lista-03', '14ª', 'Gauss-Jacobi e Gauss-Seidel', 'criterios', 2, 'texto', 0, NULL, 'Usando o critério das linhas, para que valores de k o método de Gauss-Jacobi vai gerar uma sequência convergente à solução do sistema 3x₁ + kx₂ − x₃ = 1; −2x₁ − 3x₂ = 1; kx₁ − x₂ + 3x₃ = 1?', '0,3770', '|k| < 2, ou seja, −2 < k < 2', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"α₁ = (|k| + 1)/3, α₂ = 2/3 e α₃ = (|k| + 1)/3. O critério pede máx αᵢ < 1, ou seja, |k| + 1 < 3: |k| < 2 (−2 < k < 2)."}', 'α₁ = (|k| + 1)/3, α₂ = 2/3 e α₃ = (|k| + 1)/3. O critério pede máx αᵢ < 1, ou seja, |k| + 1 < 3: |k| < 2 (−2 < k < 2).', 'O gabarito da lista ("0,3770") não responde à pergunta: pelo critério das linhas a condição é |k| < 2.', 0, 'vermelha', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l03-14', 'A', '|k| < 3', 0, 'Faltou somar o 1 do coeficiente −x₃: (|k| + 1)/3 < 1.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l03-14', 'B', '|k| < 1', 0, 'Isso vem de exigir |k|/3 < 1/3; o critério soma todos os módulos fora da diagonal.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l03-14', 'C', '|k| < 2 (−2 < k < 2)', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l03-14', 'D', 'k < 2', 0, 'O critério usa |k|: k = −5 também falha.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l03-15', 'lista-03', '15ª', 'Gauss-Jacobi e Gauss-Seidel', 'criterios', 1, 'texto', 1, NULL, 'Dada uma matriz quadrada A e um sistema linear Ax = b, o que podemos dizer das afirmações? (A) Caso a matriz seja diagonal dominante, posso garantir que o método de Jacobi converge. (B) Caso não haja diagonal dominância, mas seja possível fazer trocas entre as linhas da matriz e torná-la diagonal dominante (fazendo as mesmas alterações no lado direito), então o método de Gauss-Seidel converge, caso aplicado nesse novo sistema.', 'Ambas são verdadeiras', 'Ambas são verdadeiras', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"Diagonal dominante (estrita) é exatamente o critério das linhas: garante a convergência de Jacobi e de Seidel. Trocar linhas junto com o lado direito não muda a solução, então vale aplicar o método no sistema reordenado."}', 'Diagonal dominante (estrita) é exatamente o critério das linhas: garante a convergência de Jacobi e de Seidel. Trocar linhas junto com o lado direito não muda a solução, então vale aplicar o método no sistema reordenado.', NULL, 0, 'vermelha', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l03-15', 'A', 'Só (A) é verdadeira', 0, 'Reordenar as equações (com o lado direito junto) não muda a solução; o novo sistema satisfaz o critério.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l03-15', 'B', 'Ambas são falsas', 0, 'As duas são consequências do critério das linhas.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l03-15', 'C', 'Ambas são verdadeiras', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l03-15', 'D', 'Só (B) é verdadeira', 0, 'A diagonal dominante estrita garante Jacobi também.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l03-16', 'lista-03', '16ª', 'Gauss-Jacobi e Gauss-Seidel', 'jacobi', 1, 'vetor', 0, NULL, 'Considere o sistema 2x₁ + x₂ + x₃ = 2; x₁ − 4x₂ + x₃ = 8; x₁ + 2x₃ = 4. Ache a aproximação da solução calculada no segundo passo do método de Gauss-Jacobi, usando como vetor inicial um vetor todo de 1s.', '(0,25; −1,25; 4,00)', '(1,000; −1,625; 2,000)', NULL, NULL, '[1,-1.625,2]', '[0.25,-1.25,4]', NULL, 3, NULL, '{"calc":"jacobi","A":[[2,1,1],[1,-4,1],[1,0,2]],"b":[2,8,4],"x0":[1,1,1],"iteracoes":2}', 'Gauss-Jacobi: X⁽2⁾ = (1,00000; −1,62500; 2,00000).
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l03-16', 'A', '(0,000; −1,500; 1,500)', 0, 'Esse é o vetor depois de 1 iteração: faltou uma.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l03-16', 'B', '(0,875; −1,281; 1,563)', 0, 'Esse é o resultado do Gauss-Seidel. No Jacobi, toda a iteração usa só os valores da iteração anterior.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l03-16', 'C', '(1,000; −1,625; 2,000)', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l03-16', 'D', '(0,813; −1,250; 1,500)', 0, 'Esse é o vetor depois de 3 iterações: uma a mais.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l03-16-r', 'lista-03', '16ª · 1ª componente', 'Gauss-Jacobi e Gauss-Seidel', 'jacobi', 1, 'numero', 1, 'l03-16', 'Gauss-Jacobi, 1ª iteração: A = [2 1 1; 1 −4 1; 1 0 2], B = (2; 8; 4) e X⁽⁰⁾ = (1; 1; 1). Qual é x₁⁽¹⁾?', NULL, '0,0000', 0, NULL, NULL, NULL, NULL, 4, NULL, '{"calc":"jacobi","A":[[2,1,1],[1,-4,1],[1,0,2]],"b":[2,8,4],"x0":[1,1,1],"iteracoes":1,"componente":1}', 'Gauss-Jacobi: x₁⁽¹⁾ = 0,00000.
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l03-16-r', 'A', '1,0000', 0, 'Ignorou os termos com os valores de X⁽⁰⁾.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l03-16-r', 'B', '0,0000', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l03-16-r', 'C', '2,0000', 0, 'Sinal trocado: x₁ = (b₁ − a₁₂x₂ − a₁₃x₃ − …)/a₁₁.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l03-16-r', 'D', '−0,4000', 0, 'Não confere: refaça a conta passo a passo (veja a resolução).');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l03-17', 'lista-03', '17ª', 'Gauss-Jacobi e Gauss-Seidel', 'jacobi', 2, 'vetor', 0, NULL, 'Considere o sistema 10x₁ + 2x₂ + x₃ = 7; x₁ + 5x₂ + x₃ = −8; 2x₁ + 3x₂ + 10x₃ = 6 e o vetor X⁽⁰⁾ = (0,7; −1,6; 0,6). Pelo método de Gauss-Jacobi, obtenha o resultado após a terceira iteração.', '(0,9944; −1,9888; 0,9984)', '(0,9994; −1,9888; 0,9984)', NULL, NULL, '[0.9994,-1.9888,0.9984]', '[0.9944,-1.9888,0.9984]', NULL, 4, NULL, '{"calc":"jacobi","A":[[10,2,1],[1,5,1],[2,3,10]],"b":[7,-8,6],"x0":[0.7,-1.6,0.6],"iteracoes":3}', 'Gauss-Jacobi: X⁽3⁾ = (0,99940; −1,98880; 0,99840).
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l03-17', 'A', '(0,9979; −1,9996; 0,9968)', 0, 'Esse é o vetor depois de 4 iterações: uma a mais.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l03-17', 'B', '(0,9780; −1,9800; 0,9660)', 0, 'Esse é o vetor depois de 2 iterações: faltou uma.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l03-17', 'C', '(0,9985; −1,9999; 1,0003)', 0, 'Esse é o resultado do Gauss-Seidel. No Jacobi, toda a iteração usa só os valores da iteração anterior.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l03-17', 'D', '(0,9994; −1,9888; 0,9984)', 1, NULL);
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l03-17-r', 'lista-03', '17ª · 1ª componente', 'Gauss-Jacobi e Gauss-Seidel', 'jacobi', 1, 'numero', 1, 'l03-17', 'Gauss-Jacobi, 1ª iteração: A = [10 2 1; 1 5 1; 2 3 10], B = (7; −8; 6) e X⁽⁰⁾ = (0,7; −1,6; 0,6). Qual é x₁⁽¹⁾?', NULL, '0,9600', 0.96, NULL, NULL, NULL, NULL, 4, NULL, '{"calc":"jacobi","A":[[10,2,1],[1,5,1],[2,3,10]],"b":[7,-8,6],"x0":[0.7,-1.6,0.6],"iteracoes":1,"componente":1}', 'Gauss-Jacobi: x₁⁽¹⁾ = 0,96000.
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l03-17-r', 'A', '0,9600', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l03-17-r', 'B', '9,6000', 0, 'Faltou dividir por a₁₁.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l03-17-r', 'C', '0,7000', 0, 'Ignorou os termos com os valores de X⁽⁰⁾.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l03-17-r', 'D', '0,4400', 0, 'Sinal trocado: x₁ = (b₁ − a₁₂x₂ − a₁₃x₃ − …)/a₁₁.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l03-18', 'lista-03', '18ª', 'Gauss-Jacobi e Gauss-Seidel', 'seidel', 2, 'vetor', 0, NULL, 'Considere o sistema 10x₁ + 2x₂ + x₃ = 7; x₁ + 5x₂ + x₃ = −8; 2x₁ + 3x₂ + 10x₃ = 6 e o vetor X⁽⁰⁾ = (0,7; −1,6; 0,6). Pelo método de Gauss-Seidel, obtenha o resultado após a terceira iteração.', '(0,99852; −1,99993; 1,00027)', '(0,99852; −1,99993; 1,00027)', NULL, NULL, '[0.99852336,-1.999925152,1.0002728736]', '[0.99852,-1.99993,1.00027]', NULL, 5, NULL, '{"calc":"seidel","A":[[10,2,1],[1,5,1],[2,3,10]],"b":[7,-8,6],"x0":[0.7,-1.6,0.6],"iteracoes":3}', 'Gauss-Seidel: X⁽3⁾ = (0,99852; −1,99993; 1,00027).
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l03-18', 'A', '(0,99852; −1,99993; 1,00027)', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l03-18', 'B', '(0,98424; −1,99317; 1,00110)', 0, 'Esse é o vetor depois de 2 iterações: faltou uma.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l03-18', 'C', '(0,99940; −1,98880; 0,99840)', 0, 'Esse é o resultado do Gauss-Jacobi. No Seidel, cada valor novo entra na hora no cálculo dos seguintes.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l03-18', 'D', '(0,99996; −2,00005; 1,00002)', 0, 'Esse é o vetor depois de 4 iterações: uma a mais.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l03-18-r', 'lista-03', '18ª · 1ª componente', 'Gauss-Jacobi e Gauss-Seidel', 'seidel', 1, 'numero', 1, 'l03-18', 'Gauss-Seidel, 1ª iteração: A = [10 2 1; 1 5 1; 2 3 10], B = (7; −8; 6) e X⁽⁰⁾ = (0,7; −1,6; 0,6). Qual é x₁⁽¹⁾?', NULL, '0,9600', 0.96, NULL, NULL, NULL, NULL, 4, NULL, '{"calc":"seidel","A":[[10,2,1],[1,5,1],[2,3,10]],"b":[7,-8,6],"x0":[0.7,-1.6,0.6],"iteracoes":1,"componente":1}', 'Gauss-Seidel: x₁⁽¹⁾ = 0,96000.
