INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l03-18-r', 'D', '0,7000', 0, 'Ignorou os termos com os valores de X⁽⁰⁾.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l03-19', 'lista-03', '19ª', 'Gauss-Jacobi e Gauss-Seidel', 'jacobi', 2, 'vetor', 0, NULL, 'Considere o sistema 10x₁ + 2x₂ − x₃ = 10; x₁ + 10x₂ + x₃ = 12; 2x₁ − x₂ + 10x₃ = 11 e o vetor X⁽⁰⁾ = (0; 0; 0). Pelo método de Gauss-Jacobi, obtenha o resultado após a terceira iteração.', '(0,99852; −1,99993; 1,00027)', '(0,9040; 1,0110; 1,0250)', NULL, NULL, '[0.904,1.011,1.025]', '[0.99852,-1.99993,1.00027]', NULL, 4, NULL, '{"calc":"jacobi","A":[[10,2,-1],[1,10,1],[2,-1,10]],"b":[10,12,11],"x0":[0,0,0],"iteracoes":3}', 'Gauss-Jacobi: X⁽3⁾ = (0,90400; 1,01100; 1,02500).
