INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l03-19-r', 'lista-03', '19ª · 1ª componente', 'Gauss-Jacobi e Gauss-Seidel', 'jacobi', 1, 'numero', 1, 'l03-19', 'Gauss-Jacobi, 1ª iteração: A = [10 2 −1; 1 10 1; 2 −1 10], B = (10; 12; 11) e X⁽⁰⁾ = (0; 0; 0). Qual é x₁⁽¹⁾?', NULL, '1,0000', 1, NULL, NULL, NULL, NULL, 4, NULL, '{"calc":"jacobi","A":[[10,2,-1],[1,10,1],[2,-1,10]],"b":[10,12,11],"x0":[0,0,0],"iteracoes":1,"componente":1}', 'Gauss-Jacobi: x₁⁽¹⁾ = 1,00000.
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l03-19-r', 'A', '1,0400', 0, 'Não confere: refaça a conta passo a passo (veja a resolução).');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l03-19-r', 'B', '1,5000', 0, 'Não confere: x₁ = b₁/a₁₁ quando X⁽⁰⁾ = 0.');
