INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l03-20', 'lista-03', '20ª', 'Gauss-Jacobi e Gauss-Seidel', 'seidel', 2, 'vetor', 0, NULL, 'Considere o sistema 10x₁ + 2x₂ + x₃ = 7; x₁ + 5x₂ + x₃ = −8; 2x₁ + 3x₂ + 10x₃ = 6 e o vetor X⁽⁰⁾ = (0,5; −1,0; 0,4). Pelo método de Gauss-Seidel, obtenha o resultado após a segunda iteração.', '(0,97204; −1,99113; 1,00293)', '(0,97204; −1,99113; 1,00293)', NULL, NULL, '[0.97204,-1.991128,1.0029304]', '[0.97204,-1.99113,1.00293]', NULL, 5, NULL, '{"calc":"seidel","A":[[10,2,1],[1,5,1],[2,3,10]],"b":[7,-8,6],"x0":[0.5,-1,0.4],"iteracoes":2}', 'Gauss-Seidel: X⁽2⁾ = (0,97204; −1,99113; 1,00293).
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l03-20', 'A', '(0,99793; −2,00017; 1,00047)', 0, 'Esse é o vetor depois de 3 iterações: uma a mais.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l03-20', 'B', '(0,97204; −1,99113; 1,00293)', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l03-20', 'C', '(0,86000; −1,85200; 0,98360)', 0, 'Esse é o vetor depois de 1 iteração: faltou uma.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l03-20', 'D', '(0,97600; −1,93200; 0,96200)', 0, 'Esse é o resultado do Gauss-Jacobi. No Seidel, cada valor novo entra na hora no cálculo dos seguintes.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l03-20-r', 'lista-03', '20ª · 1ª componente', 'Gauss-Jacobi e Gauss-Seidel', 'seidel', 1, 'numero', 1, 'l03-20', 'Gauss-Seidel, 1ª iteração: A = [10 2 1; 1 5 1; 2 3 10], B = (7; −8; 6) e X⁽⁰⁾ = (0,5; −1; 0,4). Qual é x₁⁽¹⁾?', NULL, '0,8600', 0.86, NULL, NULL, NULL, NULL, 4, NULL, '{"calc":"seidel","A":[[10,2,1],[1,5,1],[2,3,10]],"b":[7,-8,6],"x0":[0.5,-1,0.4],"iteracoes":1,"componente":1}', 'Gauss-Seidel: x₁⁽¹⁾ = 0,86000.
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l03-20-r', 'A', '8,6000', 0, 'Faltou dividir por a₁₁.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l03-20-r', 'B', '0,5400', 0, 'Sinal trocado: x₁ = (b₁ − a₁₂x₂ − a₁₃x₃ − …)/a₁₁.');
