INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l03-21', 'lista-03', '21ª', 'Gauss-Jacobi e Gauss-Seidel', 'seidel', 2, 'vetor', 0, NULL, 'Considere o sistema 10x₁ + 2x₂ − x₃ = 10; x₁ + 10x₂ + x₃ = 12; 2x₁ − x₂ + 10x₃ = 11 e o vetor X⁽⁰⁾ = (0,5; −1,0; 0,4). Pelo método de Gauss-Seidel, obtenha o resultado após a segunda iteração.', '(0,9931; 1,0030; 1,0017)', '(0,8884; 1,0156; 1,0239)', NULL, NULL, '[0.88836,1.015604,1.0238884]', '[0.9931,1.003,1.0017]', NULL, 4, NULL, '{"calc":"seidel","A":[[10,2,-1],[1,10,1],[2,-1,10]],"b":[10,12,11],"x0":[0.5,-1,0.4],"iteracoes":2}', 'Gauss-Seidel: X⁽2⁾ = (0,88836; 1,01560; 1,02389).
