INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l03-23-r', 'lista-03', '23ª · 1ª componente', 'Gauss-Jacobi e Gauss-Seidel', 'seidel', 1, 'numero', 1, 'l03-23', 'Gauss-Seidel, 1ª iteração: A = [8 1 2 3; 2 7 1 1; 1 1 9 2; 1 2 3 11], B = (13; 3; 7; 10) e X⁽⁰⁾ = (1,2; −0,05; 0,2; 0,5). Qual é x₁⁽¹⁾?', NULL, '1,3938', 1.39375, NULL, NULL, NULL, NULL, 4, NULL, '{"calc":"seidel","A":[[8,1,2,3],[2,7,1,1],[1,1,9,2],[1,2,3,11]],"b":[13,3,7,10],"x0":[1.2,-0.05,0.2,0.5],"iteracoes":1,"componente":1}', 'Gauss-Seidel: x₁⁽¹⁾ = 1,39375.
