INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l03-24', 'lista-03', '24ª', 'Gauss-Jacobi e Gauss-Seidel', 'cholesky', 1, 'numero', 1, NULL, 'A matriz M admite uma fatoração de Cholesky cuja matriz triangular superior é R = [1 2 3; 0 2 3; 0 0 3]. Qual é o determinante da matriz M?', '36', '36', 36, 36, NULL, NULL, NULL, 0, NULL, '{"calc":"cholesky-det","R":[[1,2,3],[0,2,3],[0,0,3]]}', 'det M = (produto da diagonal)² = (1·2·3)² = 36.', NULL, 0, 'vermelha', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l03-24', 'A', '39', 0, 'Não confere: refaça a conta passo a passo (veja a resolução).');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l03-24', 'B', '14', 0, 'Soma dos quadrados da diagonal; o determinante é o produto (ao quadrado).');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l03-24', 'C', '36', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l03-24', 'D', '6', 0, 'Esse é det(G) só: det M = det(G)·det(Gᵀ) = (produto da diagonal)².');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l03-25', 'lista-03', '25ª', 'Gauss-Jacobi e Gauss-Seidel', 'cholesky', 1, 'numero', 1, NULL, 'A matriz M admite uma fatoração de Cholesky cuja matriz triangular inferior é G = [2 0 0; 6 1 0; −8 5 3]. Qual é o determinante da matriz M?', '36', '36', 36, 36, NULL, NULL, NULL, 0, NULL, '{"calc":"cholesky-det","G":[[2,0,0],[6,1,0],[-8,5,3]]}', 'det M = (produto da diagonal)² = (2·1·3)² = 36.', NULL, 0, 'vermelha', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l03-25', 'A', '33', 0, 'Não confere: refaça a conta passo a passo (veja a resolução).');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l03-25', 'B', '14', 0, 'Soma dos quadrados da diagonal; o determinante é o produto (ao quadrado).');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l03-25', 'C', '6', 0, 'Esse é det(G) só: det M = det(G)·det(Gᵀ) = (produto da diagonal)².');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l03-25', 'D', '36', 1, NULL);
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l03-26', 'lista-03', '26ª', 'Gauss-Jacobi e Gauss-Seidel', 'criterios', 2, 'numero', 0, NULL, 'Seja o sistema linear x₁ + 0,4x₂ − 0,1x₃ + 0,1x₄ = 0,3; 0,3x₁ + 0,2x₂ − 0,2x₃ − 0,1x₄ = −2,5; −0,1x₁ − 0,2x₂ + 0,6x₃ + 0,2x₄ = 1,2; 0,1x₁ + 0,3x₂ + 0,2x₃ + x₄ = −2,4. Para essa disposição de linhas e colunas, o critério de Sassenfeld fornece que valor para β?', 'β = 0,6', '2,40', 2.4, 0.6, NULL, NULL, NULL, 2, NULL, '{"calc":"sassenfeld","A":[[1,0.4,-0.1,0.1],[0.3,0.2,-0.2,-0.1],[-0.1,-0.2,0.6,0.2],[0.1,0.3,0.2,1]]}', 'β = (0,6000; 2,4000; 1,2333; 1,0267); β = máx βᵢ = 2,4000.', 'Igual à 16ª questão da Lista 2. Igual à 16ª questão da Lista 2. O gabarito da lista (β = 0,6) é só o β₁; o critério usa o maior βᵢ, que é β₂ = 2,4.', 1, 'vermelha', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l03-26', 'A', '1,23', 0, 'Esse é o β₃; o critério usa o maior βᵢ.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l03-26', 'B', '0,60', 0, 'Esse é só o β₁. O critério de Sassenfeld usa β = máx βᵢ. (É o valor que aparece no gabarito da lista: veja a observação da questão.)');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l03-26', 'C', '3,00', 0, 'Esse é o máx αᵢ do critério das linhas, não o β de Sassenfeld.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l03-26', 'D', '2,40', 1, NULL);
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l03-27', 'lista-03', '27ª', 'Gauss-Jacobi e Gauss-Seidel', 'cholesky', 2, 'numero', 0, NULL, 'A matriz M admite uma fatoração de Cholesky cuja matriz triangular inferior é G = [2 0 0; 6 x 0; −8 5 3]. Determine o valor de x (x > 0) para que o determinante da matriz M seja igual a 36.', '3', '1', 1, 3, NULL, NULL, NULL, 0, NULL, '{"calc":"cholesky-x","diag":[2,3],"det":36}', 'det M = (2·3·x)² = 36 ⇒ |x| = 1.', 'O gabarito da lista (3) não confere: det M = (det G)² = (2·x·3)² = 36 dá 6x = 6, ou seja, x = 1.', 1, 'vermelha', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l03-27', 'A', '4', 0, 'Não confere: refaça a conta passo a passo (veja a resolução).');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l03-27', 'B', '−5', 0, 'Não confere: refaça a conta passo a passo (veja a resolução).');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l03-27', 'C', '1', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l03-27', 'D', '6', 0, 'Faltou dividir pelos outros elementos da diagonal: det M = (2·x·3)².');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l04-01', 'lista-04', '1ª', 'Revisão', 'series', 2, 'numero', 0, NULL, 'Considere o desenvolvimento de f(x) = cotg(x) em série até o quarto termo: cotg(x) ≈ 1/x − x/3 − x³/45 − 2x⁵/945. Determine aproximadamente o erro relativo que se comete ao usar essa expansão em relação ao valor correto cotg(0,76) = 1,05213158.', '0,003128%', '0,003129%', 0.00312879131137, 0.003128, NULL, NULL, NULL, 6, 0.000002, '{"calc":"serie","serie":"cotg","x":0.76,"exato":1.05213158}', 'Soma dos quatro termos: 1,05216450. Erro relativo = |1,05216450 − 1,05213158| / 1,05213158 × 100% = 0,003129%.', NULL, 0, 'vermelha', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l04-01', 'A', '0,000031%', 0, 'Faltou multiplicar por 100.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l04-01', 'B', '0,003129%', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l04-01', 'C', '0,003004%', 0, 'Não confere: refaça a conta passo a passo (veja a resolução).');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l04-01', 'D', '0,054132%', 0, 'Usou só três termos da série; a questão pede até o quarto.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l04-02', 'lista-04', '2ª', 'Revisão', 'markov', 3, 'vetor', 0, NULL, 'Resolva pelo método de Gauss o sistema [a b c]·M = [a b c], com M = [0,8 0,2 0; 0,2 0 0,8; 0,2 0,2 0,6] e a + b + c = 1.', 'a = 0,5; b = 0,1667; c = 0,3333', '(0,5000; 0,1667; 0,3333)', NULL, NULL, '[0.5,0.166666666667,0.333333333333]', '[0.5,0.1667,0.3333]', NULL, 4, NULL, '{"calc":"markov","M":[[0.8,0.2,0],[0.2,0,0.8],[0.2,0.2,0.6]]}', '[a b c]·M = [a b c] vira (Mᵀ − I)·v = 0; trocando a última equação por a + b + c = 1 e resolvendo por Gauss: (0,5000; 0,1667; 0,3333).', NULL, 0, 'vermelha', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l04-02', 'A', '(0,1667; 0,5000; 0,3333)', 0, 'Componentes trocadas de posição.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l04-02', 'B', '(0,3333; 0,3333; 0,3333)', 0, 'Resolveu M·v = v (vetor coluna). A equação é [a b c]·M = [a b c], ou seja, (Mᵀ − I)·v = 0.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l04-02', 'C', '(0,5000; 0,1667; 0,3333)', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l04-02', 'D', '(0,5000; 0,1667; −0,3333)', 0, 'Sinal da última componente trocado.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l04-03', 'lista-04', '3ª', 'Revisão', 'lu', 2, 'sistema', 0, NULL, 'Depois de aplicar o processo de fatoração LU ao sistema AX = B, com B = (9; 3; −2)ᵀ, foram encontradas as matrizes U = [3 −4 1; 0 10/3 5/3; 0 0 −7] e L = [1 0 0; 1/3 1 0; 4/3 8/5 1]. Determine o sistema AX = B.', '3x₁ − 4x₂ + x₃ = 9; x₁ + 2x₂ + 2x₃ = 3; 4x₁ − 3x₃ = −2', '3x₁ − 4x₂ + x₃ = 9; x₁ + 2x₂ + 2x₃ = 3; 4x₁ − 3x₃ = −2', NULL, NULL, NULL, NULL, '{"A":[[3,-4,1],[1,2,2],[4,0,-3]],"b":[9,3,-2]}', 4, NULL, '{"calc":"lu-sistema","L":[[1,0,0],[0.3333333333333333,1,0],[1.3333333333333333,1.6,1]],"U":[[3,-4,1],[0,3.3333333333333335,1.6666666666666667],[0,0,-7]],"b":[9,3,-2]}', 'A = L·U (multiplique as matrizes) e o lado direito é o próprio B.', 'Igual à 1ª questão da Lista 2.', 0, 'vermelha', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l04-03', 'A', '3x₁ − 4x₂ + x₃ = 9; (10/3)x₂ + (5/3)x₃ = 3; −7x₃ = −2', 0, 'Esse é o sistema triangular U·X = B: faltou multiplicar por L (A = L·U).');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l04-03', 'B', '3x₁ − 4x₂ + x₃ = 9; −x₁ + (14/3)x₂ + (4/3)x₃ = 3; −4x₁ − 11x₃ = −2', 0, 'Sinal dos multiplicadores trocado em L.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l04-03', 'C', '3x₁ − 4x₂ + x₃ = 9; x₁ + 2x₂ + 2x₃ = 3; 4x₁ − 3x₃ = −2', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l04-03', 'D', '3x₁ − 2,4x₂ + x₃ = 9; (10/3)x₁ + 6x₂ + (5/3)x₃ = 3; −(28/3)x₁ − 11,2x₂ − 7x₃ = −2', 0, 'Multiplicou U·L; o certo é A = L·U.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l04-04', 'lista-04', '4ª', 'Revisão', 'bissecao', 1, 'numero', 0, NULL, 'Seja a função f(x) = eˣ/2 − cos(2x). Usando o método da Bisseção no intervalo [0, 1], com 4 iterações, encontre uma aproximação da raiz.', '0,4375', '0,4375', 0.4375, 0.4375, NULL, NULL, NULL, 4, NULL, '{"calc":"bissecao","f":"exp(x)/2-cos(2x)","a":0,"b":1,"iteracoes":4}', 'Bisseção: 4 iterações; x = 0,437500. 4 iterações, como pedido.
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l04-04', 'A', '0,4063', 0, 'Esse é o resultado com 5 iterações: uma a mais do que o pedido.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l04-04', 'B', '0,4375', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l04-04', 'C', '0,3750', 0, 'Esse é o resultado com 3 iterações: faltou uma.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l04-04', 'D', '0,3732', 0, 'Esse valor sai da Falsa Posição (média ponderada pelos valores de f). A Bisseção usa o valor médio xᵢ = (aᵢ + bᵢ)/2.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l04-04-r', 'lista-04', '4ª · 1º passo', 'Revisão', 'bissecao', 1, 'numero', 1, 'l04-04', 'Bisseção, 1º passo: f(x) = eˣ/2 − cos(2x) em [0; 1]. Qual é x₁?', NULL, '0,5000', 0.5, NULL, NULL, NULL, NULL, 4, NULL, '{"calc":"bissecao","f":"exp(x)/2-cos(2x)","a":0,"b":1,"iteracoes":1}', 'Bisseção: 1 iteração; x = 0,500000. 1 iteração, como pedido.
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l04-04-r', 'A', '0,2198', 0, 'Esse valor sai da Falsa Posição (média ponderada pelos valores de f). A Bisseção usa o valor médio xᵢ = (aᵢ + bᵢ)/2.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l04-04-r', 'B', '0,5200', 0, 'Não confere: refaça a conta passo a passo (veja a resolução).');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l04-04-r', 'C', '0,5000', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l04-04-r', 'D', '0,2500', 0, 'Esse é o resultado com 2 iterações: uma a mais do que o pedido.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l04-05', 'lista-04', '5ª', 'Revisão', 'series', 2, 'numero', 0, NULL, 'Considere o desenvolvimento de f(x) = cosec(x) em série até o quarto termo: cosec(x) ≈ 1/x + x/6 + 7x³/360 + 31x⁵/15120. Determine aproximadamente o erro relativo que se comete ao usar essa expansão em relação ao valor correto cosec(1,1) = 1,12207332.', '0,041579%', '0,041579%', 0.0415793202672, 0.041579, NULL, NULL, NULL, 6, 0.000002, '{"calc":"serie","serie":"cosec","x":1.1,"exato":1.12207332}', 'Soma dos quatro termos: 1,12160677. Erro relativo = |1,12160677 − 1,12207332| / 1,12207332 × 100% = 0,041579%.', NULL, 0, 'vermelha', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l04-05', 'A', '0,039916%', 0, 'Não confere: refaça a conta passo a passo (veja a resolução).');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l04-05', 'B', '0,000416%', 0, 'Faltou multiplicar por 100.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l04-05', 'C', '0,041579%', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l04-05', 'D', '0,335853%', 0, 'Usou só três termos da série; a questão pede até o quarto.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l04-06', 'lista-04', '6ª', 'Revisão', 'markov', 3, 'vetor', 0, NULL, 'Resolva pelo método de Gauss o sistema [a b c]·M = [a b c], com M = [0,7 0,2 0,1; 0,3 0,5 0,2; 0,3 0,3 0,4] e a + b + c = 1.', 'a = 0,5; b = 0,3125; c = 0,1875', '(0,5000; 0,3125; 0,1875)', NULL, NULL, '[0.5,0.3125,0.1875]', '[0.5,0.3125,0.1875]', NULL, 4, NULL, '{"calc":"markov","M":[[0.7,0.2,0.1],[0.3,0.5,0.2],[0.3,0.3,0.4]]}', '[a b c]·M = [a b c] vira (Mᵀ − I)·v = 0; trocando a última equação por a + b + c = 1 e resolvendo por Gauss: (0,5000; 0,3125; 0,1875).', NULL, 0, 'vermelha', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l04-06', 'A', '(0,5000; 0,3125; 0,1875)', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l04-06', 'B', '(0,3333; 0,3333; 0,3333)', 0, 'Resolveu M·v = v (vetor coluna). A equação é [a b c]·M = [a b c], ou seja, (Mᵀ − I)·v = 0.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l04-06', 'C', '(0,5000; 0,3125; −0,1875)', 0, 'Sinal da última componente trocado.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l04-06', 'D', '(0,3125; 0,5000; 0,1875)', 0, 'Componentes trocadas de posição.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l04-07', 'lista-04', '7ª', 'Revisão', 'pivoteamento', 3, 'texto', 0, NULL, 'Seja um sistema linear Ax = b com A = [14 6,7 6,7 6,7; 10,5 13,4 6,7 13,4; 7 6,7 6,7 13,4; 3,5 6,7 13,4 6,7] e b = (3,4; 7,5; −8,9; 8,8). Usando a eliminação gaussiana com pivoteamento parcial, serão necessárias trocas de linhas para calcular quais pivôs?', '(d) para o cálculo do terceiro pivô', '3º pivô', NULL, NULL, '[3]', '[3]', NULL, NULL, NULL, '{"calc":"gauss-trocas","A":[[14,6.7,6.7,6.7],[10.5,13.4,6.7,13.4],[7,6.7,6.7,13.4],[3.5,6.7,13.4,6.7]],"b":[3.4,7.5,-8.9,8.8]}', 'Etapa 1: o maior |aᵢₖ| já está na equação pivô, sem troca; Etapa 2: o maior |aᵢₖ| já está na equação pivô, sem troca; Etapa 3: |a₄₃| é o maior elemento da coluna 3 em módulo.', NULL, 0, 'vermelha', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l04-07', 'A', 'Para o cálculo do primeiro pivô', 0, 'O 14 já é o maior |aᵢ₁| da primeira coluna.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l04-07', 'B', 'Não será necessária nenhuma troca', 0, 'Na 3ª etapa o maior |aᵢ₃| está na 4ª equação: é preciso trocar.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l04-07', 'C', 'Só para o cálculo do terceiro pivô', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l04-07', 'D', 'Para o cálculo do segundo pivô', 0, 'Depois da 1ª etapa, o maior |aᵢ₂| da coluna 2 já está na 2ª equação.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l04-08', 'lista-04', '8ª', 'Revisão', 'jacobi', 1, 'vetor', 0, NULL, 'Considere o sistema 4,00x₁ + 0,24x₂ − 0,08x₃ = 8,00; 0,09x₁ + 3,00x₂ − 0,15x₃ = 9,00; 0,04x₁ − 0,08x₂ + 4,00x₃ = 20,00 e o vetor X⁽⁰⁾ = (0; 0; 0). Pelo método de Gauss-Jacobi, obtenha o resultado para o 2º passo.', '(1,920; 3,190; 5,040)', '(1,920; 3,190; 5,040)', NULL, NULL, '[1.92,3.19,5.04]', '[1.92,3.19,5.04]', NULL, 3, NULL, '{"calc":"jacobi","A":[[4,0.24,-0.08],[0.09,3,-0.15],[0.04,-0.08,4]],"b":[8,9,20],"x0":[0,0,0],"iteracoes":2}', 'Gauss-Jacobi: X⁽2⁾ = (1,92000; 3,19000; 5,04000).
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l04-08', 'A', '(1,920; 3,190; 5,040)', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l04-08', 'B', '(1,909; 3,194; 5,045)', 0, 'Esse é o vetor depois de 3 iterações: uma a mais.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l04-08', 'C', '(1,924; 3,194; 5,045)', 0, 'Esse é o resultado do Gauss-Seidel. No Jacobi, toda a iteração usa só os valores da iteração anterior.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l04-08', 'D', '(2,000; 3,000; 5,000)', 0, 'Esse é o vetor depois de 1 iteração: faltou uma.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l04-09', 'lista-04', '9ª', 'Revisão', 'bissecao', 1, 'numero', 0, NULL, 'Seja a função f(x) = sen(5x) − eˣ/5. Usando o método da Bisseção no intervalo [0,5; 0,6] e 4 iterações, qual aproximação da raiz é encontrada?', '0,55625', '0,55625', 0.55625, 0.55625, NULL, NULL, NULL, 5, NULL, '{"calc":"bissecao","f":"sin(5x)-exp(x)/5","a":0.5,"b":0.6,"iteracoes":4}', 'Bisseção: 4 iterações; x = 0,556250. 4 iterações, como pedido.
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l04-09', 'A', '0,55625', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l04-09', 'B', '0,55938', 0, 'Esse é o resultado com 5 iterações: uma a mais do que o pedido.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l04-09', 'C', '0,55700', 0, 'Esse valor sai da Falsa Posição (média ponderada pelos valores de f). A Bisseção usa o valor médio xᵢ = (aᵢ + bᵢ)/2.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l04-09', 'D', '0,56250', 0, 'Esse é o resultado com 3 iterações: faltou uma.');
