INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l04-09-r', 'D', '0,55462', 0, 'Esse valor sai da Falsa Posição (média ponderada pelos valores de f). A Bisseção usa o valor médio xᵢ = (aᵢ + bᵢ)/2.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l04-10', 'lista-04', '10ª', 'Revisão', 'newton', 2, 'numero', 0, NULL, 'Realize duas iterações do método de Newton, com chute inicial x₀ = 1, para encontrar uma raiz de f(x) = x/4 + cos(x). A raiz aproximada x₂ é:', '2,10531', '2,10531', 2.10531107489, 2.10531, NULL, NULL, NULL, 5, NULL, '{"calc":"newton","f":"x/4+cos(x)","df":"1/4-sin(x)","x0":1,"iteracoes":2}', 'Newton-Raphson: 2 iterações; x = 2,105311. 2 iterações, como pedido.
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l04-10', 'A', '2,10531', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l04-10', 'B', '2,13300', 0, 'Esse é o resultado com 3 iterações: uma a mais do que o pedido.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l04-10', 'C', '2,33616', 0, 'Esse é o resultado com 1 iteração: faltou uma.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l04-10', 'D', '1,14691', 0, 'Sinal trocado na fórmula: o certo é xᵢ₊₁ = xᵢ − f(xᵢ)/f′(xᵢ).');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l04-10-r', 'lista-04', '10ª · 1º passo', 'Revisão', 'newton', 1, 'numero', 1, 'l04-10', 'Newton-Raphson, 1º passo: f(x) = x/4 + cos x, f′(x) = 1/4 − sen x e x₀ = 1. Qual é x₁?', NULL, '2,33616', 2.33616411653, NULL, NULL, NULL, NULL, 5, NULL, '{"calc":"newton","f":"x/4+cos(x)","df":"1/4-sin(x)","x0":1,"iteracoes":1}', 'Newton-Raphson: 1 iteração; x = 2,336164. 1 iterações, como pedido.
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l04-10-r', 'A', '2,10531', 0, 'Esse é o resultado com 2 iterações: uma a mais do que o pedido.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l04-10-r', 'B', '−0,33616', 0, 'Sinal trocado na fórmula: o certo é xᵢ₊₁ = xᵢ − f(xᵢ)/f′(xᵢ).');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l04-10-r', 'C', '2,33616', 1, NULL);
