INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l04-11', 'lista-04', '11ª', 'Revisão', 'falsa-posicao', 1, 'numero', 0, NULL, 'Seja a função f(x) = 2x − ln x − 7. Usando o método da Falsa Posição no intervalo [4,1; 4,3] e 2 iterações, encontre uma aproximação para a raiz.', '4,21991', '4,21991', 4.21990628996, 4.21991, NULL, NULL, NULL, 5, NULL, '{"calc":"falsaPosicao","f":"2x-ln(x)-7","a":4.1,"b":4.3,"iteracoes":2}', 'Falsa Posição: 2 iterações; x = 4,219906. 2 iterações, como pedido.
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l04-11', 'A', '4,21975', 0, 'Esse é o resultado com 1 iteração: faltou uma.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l04-11', 'B', '4,38870', 0, 'Não confere: refaça a conta passo a passo (veja a resolução).');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l04-11', 'C', '4,25000', 0, 'Esse valor sai da Bisseção (valor médio). A Falsa Posição usa xᵢ = (aᵢ·f(bᵢ) − bᵢ·f(aᵢ)) / (f(bᵢ) − f(aᵢ)).');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l04-11', 'D', '4,21991', 1, NULL);
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l04-11-r', 'lista-04', '11ª · 1º passo', 'Revisão', 'falsa-posicao', 1, 'numero', 1, 'l04-11', 'Falsa Posição, 1º passo: f(x) = 2x − ln x − 7 em [4,1; 4,3]. Qual é x₁?', NULL, '4,21975', 4.21975242246, NULL, NULL, NULL, NULL, 5, NULL, '{"calc":"falsaPosicao","f":"2x-ln(x)-7","a":4.1,"b":4.3,"iteracoes":1}', 'Falsa Posição: 1 iteração; x = 4,219752. 1 iteração, como pedido.
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l04-11-r', 'A', '4,21975', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l04-11-r', 'B', '4,20000', 0, 'Esse valor sai da Bisseção (valor médio). A Falsa Posição usa xᵢ = (aᵢ·f(bᵢ) − bᵢ·f(aᵢ)) / (f(bᵢ) − f(aᵢ)).');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l04-11-r', 'C', '4,05096', 0, 'Não confere: refaça a conta passo a passo (veja a resolução).');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l04-11-r', 'D', '4,21991', 0, 'Esse é o resultado com 2 iterações: uma a mais do que o pedido.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l05-1a', 'lista-05', '1ª (a)', 'Fatoração de Cholesky', 'cholesky', 2, 'matriz', 0, NULL, 'Use o algoritmo de Cholesky para encontrar uma fatoração da forma A = G·Gᵀ para A = [4 1 1 1; 1 3 −1 1; 1 −1 2 0; 1 1 0 2].', 'G = [2 0 0 0; 0,5 1,658311 0 0; 0,5 −0,7537785 1,087113 0; 0,5 0,4522671 0,08362442 1,240346]', 'G = [2 0 0 0; 0,5 1,6583 0 0; 0,5 −0,7538 1,0871 0; 0,5 0,4523 0,0836 1,2403]', NULL, NULL, NULL, NULL, '{"G":[[2,0,0,0],[0.5,1.65831239518,0,0],[0.5,-0.753778361444,1.08711461301,0],[0.5,0.452267016867,0.0836242010007,1.24034734589]]}', 4, NULL, '{"calc":"cholesky","A":[[4,1,1,1],[1,3,-1,1],[1,-1,2,0],[1,1,0,2]]}', 'A = G·Gᵀ com G triangular inferior: gⱼⱼ = √(aⱼⱼ − Σgⱼₖ²) e gᵢⱼ = (aᵢⱼ − Σgᵢₖgⱼₖ)/gⱼⱼ.', NULL, 0, 'vermelha', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l05-1a', 'A', 'G = [2 0 0 0; −0,5 1,6583 0 0; −0,5 0,7538 1,0871 0; −0,5 −0,4523 −0,0836 1,2403]', 0, 'Sinal dos elementos abaixo da diagonal trocado: gᵢⱼ = (aᵢⱼ − Σgᵢₖgⱼₖ)/gⱼⱼ.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l05-1a', 'B', 'G = [2 0,5 0,5 0,5; 0 1,6583 −0,7538 0,4523; 0 0 1,0871 0,0836; 0 0 0 1,2403]', 0, 'Essa é Gᵀ (triangular superior); a fatoração pede G triangular inferior.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l05-1a', 'C', 'G = [2 0 0 0; 0,5 1,6583 0 0; 0,5 −0,7538 1,0871 0; 0,5 0,4523 0,0836 1,2403]', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l05-1a', 'D', 'G = [4 0 0 0; 0,5 2,75 0 0; 0,5 −0,7538 1,1818 0; 0,5 0,4523 0,0836 1,5385]', 0, 'Faltou a raiz na diagonal: gⱼⱼ = √(aⱼⱼ − Σgⱼₖ²).');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l05-1b', 'lista-05', '1ª (b)', 'Fatoração de Cholesky', 'cholesky', 2, 'matriz', 0, NULL, 'Use o algoritmo de Cholesky para encontrar uma fatoração da forma A = G·Gᵀ para A = [6 2 1 −1; 2 4 1 0; 1 1 4 −1; −1 0 −1 3].', 'G = [2,449489 0 0 0; 0,8164966 1,825741 0 0; 0,4082483 0,3651483 1,923538 0; −0,4082483 0,1825741 −0,4678876 1,606574]', 'G = [2,4495 0 0 0; 0,8165 1,8257 0 0; 0,4082 0,3651 1,9235 0; −0,4082 0,1826 −0,4679 1,6066]', NULL, NULL, NULL, NULL, '{"G":[[2.44948974278,0,0,0],[0.816496580928,1.82574185835,0,0],[0.408248290464,0.36514837167,1.92353840617,0],[-0.408248290464,0.182574185835,-0.467887720419,1.60657433102]]}', 4, NULL, '{"calc":"cholesky","A":[[6,2,1,-1],[2,4,1,0],[1,1,4,-1],[-1,0,-1,3]]}', 'A = G·Gᵀ com G triangular inferior: gⱼⱼ = √(aⱼⱼ − Σgⱼₖ²) e gᵢⱼ = (aᵢⱼ − Σgᵢₖgⱼₖ)/gⱼⱼ.', NULL, 0, 'vermelha', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l05-1b', 'A', 'G = [2,4495 0 0 0; −0,8165 1,8257 0 0; −0,4082 −0,3651 1,9235 0; 0,4082 −0,1826 0,4679 1,6066]', 0, 'Sinal dos elementos abaixo da diagonal trocado: gᵢⱼ = (aᵢⱼ − Σgᵢₖgⱼₖ)/gⱼⱼ.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l05-1b', 'B', 'G = [6 0 0 0; 0,8165 3,3333 0 0; 0,4082 0,3651 3,7 0; −0,4082 0,1826 −0,4679 2,5811]', 0, 'Faltou a raiz na diagonal: gⱼⱼ = √(aⱼⱼ − Σgⱼₖ²).');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l05-1b', 'C', 'G = [2,4495 0,8165 0,4082 −0,4082; 0 1,8257 0,3651 0,1826; 0 0 1,9235 −0,4679; 0 0 0 1,6066]', 0, 'Essa é Gᵀ (triangular superior); a fatoração pede G triangular inferior.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l05-1b', 'D', 'G = [2,4495 0 0 0; 0,8165 1,8257 0 0; 0,4082 0,3651 1,9235 0; −0,4082 0,1826 −0,4679 1,6066]', 1, NULL);
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l05-2a', 'lista-05', '2ª (a)', 'Fatoração de Cholesky', 'cholesky', 2, 'vetor', 0, NULL, 'Use a fatoração de Cholesky para resolver o sistema 4x₁ + x₂ + x₃ + x₄ = 0,65; x₁ + 4x₂ − x₃ + x₄ = 0,05; x₁ − x₂ + 2x₃ = 0; x₁ + x₂ + 2x₄ = 0,5.', '(0,2; −0,2; −0,2; 0,25)', '(0,1750; −0,1250; −0,1500; 0,2250)', NULL, NULL, '[0.175,-0.125,-0.15,0.225]', '[0.2,-0.2,-0.2,0.25]', NULL, 4, NULL, '{"calc":"cholesky-sistema","A":[[4,1,1,1],[1,4,-1,1],[1,-1,2,0],[1,1,0,2]],"b":[0.65,0.05,0,0.5]}', 'G·y = b dá y = (0,325000; −0,058095; −0,173205; 0,284605); Gᵀ·x = y dá x = (0,175000; −0,125000; −0,150000; 0,225000).', 'O gabarito da lista (0,2; −0,2; −0,2; 0,25) é a solução com 3x₂ na 2ª equação (a matriz da 1ª questão, item a). Com o sistema como está escrito (4x₂), a solução é (0,175; −0,125; −0,15; 0,225).', 1, 'vermelha', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l05-2a', 'A', '(0,1750; −0,1250; −0,1500; 0,2250)', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l05-2a', 'B', '(0,1750; −0,1250; −0,1500; −0,2250)', 0, 'Sinal da última componente trocado.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l05-2a', 'C', '(−0,1250; 0,1750; −0,1500; 0,2250)', 0, 'Componentes trocadas de posição.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l05-2a', 'D', '(0,1960; −0,1250; −0,1500; 0,2250)', 0, 'A primeira componente não confere: refaça a conta.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l05-2b', 'lista-05', '2ª (b)', 'Fatoração de Cholesky', 'cholesky', 2, 'vetor', 0, NULL, 'Use a fatoração de Cholesky para resolver o sistema 6x₁ + 2x₂ + x₃ − x₄ = 0; 2x₁ + 4x₂ + x₃ = 7; x₁ + x₂ + 4x₃ − x₄ = −1; −x₁ − x₃ + 3x₄ = −2.', '(−0,8586874; 2,4188482; −0,95811518; −1,2722513)', '(−0,8586; 2,4188; −0,9581; −1,2723)', NULL, NULL, '[-0.858638743455,2.41884816754,-0.958115183246,-1.2722513089]', '[-0.8586874,2.4188482,-0.95811518,-1.2722513]', NULL, 4, NULL, '{"calc":"cholesky-sistema","A":[[6,2,1,-1],[2,4,1,0],[1,1,4,-1],[-1,0,-1,3]],"b":[0,7,-1,-2]}', 'G·y = b dá y = (0,000000; 3,834058; −1,247701; −2,043966); Gᵀ·x = y dá x = (−0,858639; 2,418848; −0,958115; −1,272251).', NULL, 0, 'vermelha', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l05-2b', 'A', '(2,4188; −0,8586; −0,9581; −1,2723)', 0, 'Componentes trocadas de posição.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l05-2b', 'B', '(−0,8586; 2,4188; −0,9581; −1,2723)', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l05-2b', 'C', '(−0,8586; 2,4188; −0,9581; 1,2723)', 0, 'Sinal da última componente trocado.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l05-2b', 'D', '(−0,9617; 2,4188; −0,9581; −1,2723)', 0, 'A primeira componente não confere: refaça a conta.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l05-3', 'lista-05', '3ª', 'Fatoração de Cholesky', 'cholesky', 1, 'matriz', 1, NULL, 'A matriz M admite uma fatoração de Cholesky cuja matriz triangular superior é R = [2 1 −2; 0 3 2; 0 0 1]. Determine a matriz M.', NULL, 'M = [4 2 −4; 2 10 4; −4 4 9]', NULL, NULL, NULL, NULL, '{"M":[[4,2,-4],[2,10,4],[-4,4,9]]}', 4, NULL, '{"calc":"cholesky-M","R":[[2,1,-2],[0,3,2],[0,0,1]]}', 'M = Rᵀ·R (a transposta da triangular superior vezes ela mesma).', 'A lista não traz a resposta desta questão; a resposta é a calculada (igual à 13ª questão da Lista 3).', 0, 'vermelha', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l05-3', 'A', 'M = [4 1 −2; 1 9 2; −2 2 1]', 0, 'Elevou só a diagonal ao quadrado: cada mᵢⱼ é uma soma de produtos (Rᵀ·R).');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l05-3', 'B', 'M = [4 2 −4; 2 10 4; −4 4 9]', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l05-3', 'C', 'M = [4 −2 4; −2 10 −4; 4 −4 9]', 0, 'Sinais fora da diagonal trocados.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l05-3', 'D', 'M = [9 −1 −2; −1 13 2; −2 2 1]', 0, 'Multiplicou R·Rᵀ; com R triangular superior, M = Rᵀ·R.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l06-01', 'lista-06', '1ª', 'Interpolação', 'interpolacao', 1, 'numero', 1, NULL, 'Obtenha ln(3,7) por interpolação linear, onde f(x) = ln(x) está tabelada: xᵢ: 1,0 | 2,0 | 3,0 | 4,0; fᵢ: 0,0000 | 0,6931 | 1,0986 | 1,3863.', '1,3000', '1,3000', 1.29999, 1.3, NULL, NULL, NULL, 4, NULL, '{"calc":"interp-linear","xs":[1,2,3,4],"ys":[0,0.6931,1.0986,1.3863],"x":3.7}', 'Entre os dois pontos vizinhos de x = 3,7: p₁(x) = y₀ + (y₁ − y₀)(x − x₀)/(x₁ − x₀) = 1,3000.', NULL, 0, 'vermelha', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l06-01', 'A', '1,3520', 0, 'Não confere: refaça a conta passo a passo (veja a resolução).');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l06-01', 'B', '1,3863', 0, 'Esse é só o valor tabelado mais próximo, sem interpolar.');
