INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l06-01', 'D', '1,3825', 0, 'Usou o segmento errado da tabela: a interpolação linear usa os dois pontos vizinhos de x.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l06-02', 'lista-06', '2ª', 'Interpolação', 'interpolacao', 1, 'numero', 0, NULL, 'Obtenha ln(3,7) por interpolação linear (tabela: xᵢ: 1,0 | 2,0 | 3,0 | 4,0; fᵢ: 0,0000 | 0,6931 | 1,0986 | 1,3863) e determine o erro relativo cometido, sabendo que ln(3,7) = 1,3083. Considere 4 casas decimais.', '0,60%', '0,64%', 0.635175418482, 0.6, NULL, NULL, NULL, 2, NULL, '{"calc":"interp-linear-erro","xs":[1,2,3,4],"ys":[0,0.6931,1.0986,1.3863],"x":3.7,"exato":1.3083}', 'p₁(3,7) = 1,3000; erro relativo = |1,3000 − 1,3083| / 1,3083 × 100% = 0,64%.', 'O gabarito da lista (0,60%) não confere: p₁(3,7) = 1,3000 e |1,3000 − 1,3083| / 1,3083 = 0,63%.', 1, 'vermelha', NULL);
