INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l06-03', 'lista-06', '3ª', 'Interpolação', 'interpolacao', 1, 'numero', 1, NULL, 'Obtenha ln(2,4) por interpolação linear, onde f(x) = ln(x) está tabelada: xᵢ: 1,0 | 2,0 | 3,0 | 4,0; fᵢ: 0,0000 | 0,6931 | 1,0986 | 1,3863.', '0,8553', '0,8553', 0.8553, 0.8553, NULL, NULL, NULL, 4, NULL, '{"calc":"interp-linear","xs":[1,2,3,4],"ys":[0,0.6931,1.0986,1.3863],"x":2.4}', 'Entre os dois pontos vizinhos de x = 2,4: p₁(x) = y₀ + (y₁ − y₀)(x − x₀)/(x₁ − x₀) = 0,8553.', NULL, 0, 'vermelha', NULL);
