INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l06-08', 'lista-06', '8ª', 'Interpolação', 'interpolacao', 2, 'numero', 0, NULL, 'Dada a tabela xᵢ: 1,3 | 1,4 | 1,5; fᵢ: 3,669 | 4,055 | 4,482, determine o polinômio interpolador que passa por todos os pontos e calcule f(1,35).', '3,857', '3,857', 3.856875, 3.857, NULL, NULL, NULL, 3, NULL, '{"calc":"interp-poli","xs":[1.3,1.4,1.5],"ys":[3.669,4.055,4.482],"x":1.35}', 'Polinômio de grau 2 pelos pontos dados (Lagrange): p(1,35000) = 3,85688.', NULL, 0, 'vermelha', NULL);
