INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l06-09', 'lista-06', '9ª', 'Interpolação', 'interpolacao', 1, 'vetor', 0, NULL, 'Dada a tabela xᵢ: 3,0 | 3,1 | 3,2 | 3,3; fᵢ: 1,0986 | 1,1314 | 1,1632 | 1,1939, determine o polinômio do primeiro grau que passa pelos pontos 3,1 e 3,2.', '0,3180x + 0,1456', 'p(x) = 0,3180x + 0,1456', NULL, NULL, '[0.1456,0.318]', '[0.1456,0.318]', NULL, 4, NULL, '{"calc":"interp-poli-coef","xs":[3.1,3.2],"ys":[1.1314,1.1632]}', 'p(x) = 0,3180x + 0,1456.', NULL, 0, 'vermelha', NULL);
