INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l06-18', 'lista-06', '18ª', 'Interpolação', 'interpolacao', 2, 'numero', 0, NULL, 'Dada a tabela x: 2,00 | 2,50 | 3,00; f(x): 0,301 | 0,398 | 0,477, obtenha f(2,40) por interpolação polinomial, usando a fórmula de Lagrange.', '0,380', '0,380', 0.38004, 0.38, NULL, NULL, NULL, 3, NULL, '{"calc":"interp-poli","xs":[2,2.5,3],"ys":[0.301,0.398,0.477],"x":2.4}', 'Polinômio de grau 2 pelos pontos dados (Lagrange): p(2,40000) = 0,38004.', NULL, 0, 'vermelha', NULL);
