INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l06-19', 'lista-06', '19ª', 'Interpolação', 'interpolacao', 2, 'vetor', 0, NULL, 'Dada a tabela x: 2,00 | 2,50 | 3,00; f(x): 0,301 | 0,398 | 0,477, obtenha o polinômio que melhor interpola a função f(x).', '−0,036x² + 0,356x − 0,267', 'p(x) = −0,036x² + 0,356x − 0,267', NULL, NULL, '[-0.267,0.356,-0.036]', '[-0.267,0.356,-0.036]', NULL, 3, NULL, '{"calc":"interp-poli-coef","xs":[2,2.5,3],"ys":[0.301,0.398,0.477]}', 'p(x) = −0,0360x² + 0,3560x − 0,2670.', NULL, 0, 'vermelha', NULL);
