INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l06-20', 'lista-06', '20ª', 'Interpolação', 'interpolacao', 3, 'numero', 0, NULL, 'Dada a tabela x: 2,00 | 2,50 | 3,00; f(x): 0,301 | 0,398 | 0,477, obtenha a melhor aproximação para x* tal que f(x*) = 0,350, utilizando um polinômio que passe por x₀, x₁ e x₂.', '2,236', '2,237', 2.23688206613, 2.236, NULL, NULL, NULL, 3, 0.002, '{"calc":"interp-inversa-lagrange","xs":[2,2.5,3],"ys":[0.301,0.398,0.477],"y":0.35}', 'Interpolação inversa: trocamos os papéis de x e y e passamos o polinômio de Lagrange pelos pontos (yᵢ; xᵢ). Em y = 0,35: x* = 2,2369.', NULL, 0, 'vermelha', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l06-20', 'A', '2,253', 0, 'Usou outro par de pontos da tabela: o certo é o segmento em que f passa por ȳ.');
