INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l07-01', 'lista-07', '1ª', 'Ajuste de Curvas', 'minimos-quadrados', 2, 'numero', 0, NULL, 'A partir da reta que melhor ajusta os pontos da tabela (x: 0 | 1 | 2 | 3 | 4; y: 0 | 1 | 1 | 4 | 4), determine a imagem de x = 5.', '5,3', '5,3', 5.3, 5.3, NULL, NULL, NULL, 1, NULL, '{"calc":"mq","base":"reta","xs":[0,1,2,3,4],"ys":[0,1,1,4,4],"x":5}', 'g(x) = −0,2000 + 1,1000·x; g(5) = 5,3000.', NULL, 0, 'vermelha', NULL);
