INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l07-02', 'lista-07', '2ª', 'Ajuste de Curvas', 'minimos-quadrados', 2, 'vetor', 0, NULL, 'Utilizando o método dos mínimos quadrados, ajuste uma função do tipo g(x) = a + bx² aos pontos da tabela (x: 0,0 | 1,0 | 2,0; f(x): 1,1 | 0,1 | −3,1).', 'g(x) = −1,05x² + 1,12', 'g(x) = −1,05x² + 1,12', NULL, NULL, '[1.12307692308,-1.05384615385]', '[1.12,-1.05]', NULL, 2, 0.006, '{"calc":"mq","base":"a+bx2","xs":[0,1,2],"ys":[1.1,0.1,-3.1]}', 'g(x) = 1,1231 − 1,0538·x².', NULL, 0, 'vermelha', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l07-02', 'A', 'g(x) = −1,05x² + 1,12', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l07-02', 'B', 'g(x) = −1,05x² + 1,26', 0, 'A primeira componente não confere: refaça a conta.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l07-02', 'C', 'g(x) = 1,12x² − 1,05', 0, 'Coeficientes trocados de lugar.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l07-02', 'D', 'g(x) = 1,05x² + 1,12', 0, 'Sinal do segundo coeficiente trocado.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l07-03', 'lista-07', '3ª', 'Ajuste de Curvas', 'minimos-quadrados', 3, 'numero', 0, NULL, 'Um sinal em um osciloscópio pode ser aproximado por uma função da forma g(x) = a·x + b·cos x. Algumas medidas: xᵢ: 0,0 | 1,5 | 3,0 | 4,5 | 6,0; fᵢ: 1,00 | 1,57 | 2,00 | 4,30 | 7,00. Utilizando o método dos mínimos quadrados, obtenha um valor aproximado para g(3,5).', '2,5630', '2,5631', 2.56307186609, 2.563, NULL, NULL, NULL, 4, 0.0002, '{"calc":"mq","base":"ax+bcos","xs":[0,1.5,3,4.5,6],"ys":[1,1.57,2,4.3,7],"x":3.5}', 'g(x) = 1,0034·x + 1,0133·cos x; g(3,5) = 2,5631.', NULL, 0, 'vermelha', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l07-03', 'A', '2,9243', 0, 'Esse é o resultado com outro ajuste (uma exponencial); a questão pede g(x) = a·x + b·cos x.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l07-03', 'B', '2,5631', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l07-03', 'C', '3,6650', 0, 'Esse é o resultado com outro ajuste (uma reta); a questão pede g(x) = a·x + b·cos x.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l07-03', 'D', '2,8379', 0, 'Esse é o resultado com outro ajuste (uma parábola); a questão pede g(x) = a·x + b·cos x.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l07-04', 'lista-07', '4ª', 'Ajuste de Curvas', 'minimos-quadrados', 2, 'numero', 0, NULL, 'Utilizando o método dos mínimos quadrados, ajuste uma função do tipo g(x) = a + bx² aos pontos da tabela (x: 0,0 | 1,0 | 2,0; f(x): 1,1 | 0,1 | −3,1) e determine aproximadamente x* tal que g(x*) = −2,5.', '1,8568', '1,8542', 1.85417264686, 1.8568, NULL, NULL, NULL, 4, 0.005, '{"calc":"mq","base":"a+bx2","xs":[0,1,2],"ys":[1.1,0.1,-3.1],"y":-2.5,"faixa":[0,4]}', 'g(x) = 1,1231 − 1,0538·x²; g(x*) = −2,5 ⇒ x* = 1,8542.', 'A lista chega a 1,8568 usando os coeficientes já arredondados (1,12 e −1,05); com os coeficientes completos, x* = 1,8542.', 0, 'vermelha', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l07-04', 'A', '1,7800', 0, 'Não confere: refaça a conta passo a passo (veja a resolução).');
