INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l07-05', 'lista-07', '5ª', 'Ajuste de Curvas', 'minimos-quadrados', 2, 'numero', 0, NULL, 'A partir da reta que melhor ajusta os pontos da tabela (x: 0 | 1 | 2 | 3 | 4; y: 0 | 1 | 1 | 4 | 4), determine de forma aproximada x* tal que g(x*) = 3,5.', '3,364', '3,364', 3.36363636364, 3.364, NULL, NULL, NULL, 3, NULL, '{"calc":"mq","base":"reta","xs":[0,1,2,3,4],"ys":[0,1,1,4,4],"y":3.5}', 'g(x) = −0,2000 + 1,1000·x; g(x*) = 3,5 ⇒ x* = 3,3636.', NULL, 0, 'vermelha', NULL);
