INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l07-06', 'lista-07', '6ª', 'Ajuste de Curvas', 'minimos-quadrados', 1, 'vetor', 0, NULL, 'Qual a reta que melhor ajusta os pontos da tabela x: 4,0 | 5,0 | 6,0 | 7,0; y: 0,000 | 0,405 | 0,588 | 0,693?', 'y = 0,226x − 0,822', 'g(x) = 0,226x − 0,823', NULL, NULL, '[-0.8226,0.2262]', '[-0.822,0.226]', NULL, 3, NULL, '{"calc":"mq","base":"reta","xs":[4,5,6,7],"ys":[0,0.405,0.588,0.693]}', 'g(x) = −0,8226 + 0,2262·x.', NULL, 0, 'vermelha', NULL);
