INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l07-08', 'lista-07', '8ª', 'Ajuste de Curvas', 'minimos-quadrados', 3, 'numero', 0, NULL, 'Ajuste os dados da tabela (x: 1 | 2 | 3; y: 1 | 2 | 4) por um polinômio da forma g(x) = a + bx + cx² pelo método dos mínimos quadrados. Determine aproximadamente x* tal que g(x*) = 3,0.', '2,56', '2,56', 2.56155281281, 2.56, NULL, NULL, NULL, 2, NULL, '{"calc":"mq","base":"parabola","xs":[1,2,3],"ys":[1,2,4],"y":3,"faixa":[1,4]}', 'g(x) = 1,0000 − 0,5000·x + 0,5000·x²; g(x*) = 3 ⇒ x* = 2,5616.', NULL, 0, 'vermelha', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l07-08', 'A', '2,44', 0, 'Esse é o resultado com outro ajuste (uma reta); a questão pede a parábola.');
