INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l07-09', 'lista-07', '9ª', 'Ajuste de Curvas', 'minimos-quadrados', 1, 'vetor', 0, NULL, 'A tabela mostra o resultado de um teste com 3 digitadores de idades diferentes (idade: 30 | 35 | 40; palavras por minuto: 70 | 65 | 58). Utilizando o método dos mínimos quadrados, encontre a reta y = c₀ + c₁x que melhor ajusta os pontos, sendo x a idade e y o número de palavras por minuto.', 'y = 106,33 − 1,2x', 'g(x) = −1,20x + 106,33', NULL, NULL, '[106.333333333,-1.2]', '[106.33,-1.2]', NULL, 2, NULL, '{"calc":"mq","base":"reta","xs":[30,35,40],"ys":[70,65,58]}', 'g(x) = 106,3333 − 1,2000·x.', NULL, 0, 'vermelha', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l07-09', 'A', 'g(x) = 1,20x + 106,33', 0, 'Sinal do segundo coeficiente trocado.');
