INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l07-09', 'D', 'g(x) = 106,33x − 1,20', 0, 'Coeficientes trocados de lugar.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l07-10', 'lista-07', '10ª', 'Ajuste de Curvas', 'minimos-quadrados', 2, 'numero', 0, NULL, 'Com a reta de mínimos quadrados dos digitadores (idade: 30 | 35 | 40; palavras por minuto: 70 | 65 | 58), determine aproximadamente a idade do digitador capaz de digitar 39 palavras por minuto.', '56', '56', 56.1111111111, 56, NULL, NULL, NULL, 0, 0.6, '{"calc":"mq","base":"reta","xs":[30,35,40],"ys":[70,65,58],"y":39,"faixa":[30,80]}', 'g(x) = 106,3333 − 1,2000·x; g(x*) = 39 ⇒ x* = 56,1111.', NULL, 0, 'vermelha', NULL);
