INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l07-11', 'lista-07', '11ª', 'Ajuste de Curvas', 'minimos-quadrados', 2, 'vetor', 0, NULL, 'A população de uma localidade variou com o tempo segundo a tabela (ano: 4 | 5 | 6 | 7; população × 10⁴: 1,0 | 1,5 | 1,8 | 2,0). Utilizando o método dos mínimos quadrados, ajuste uma função do tipo g(t) = at² + bt + c.', 'g(t) = −0,075t² + 1,155t − 2,415', 'g(x) = −0,075x² + 1,155x − 2,415', NULL, NULL, '[-2.415,1.155,-0.075]', '[-2.415,1.155,-0.075]', NULL, 3, NULL, '{"calc":"mq","base":"parabola","xs":[4,5,6,7],"ys":[1,1.5,1.8,2]}', 'g(x) = −2,4150 + 1,1550·x − 0,0750·x².', NULL, 0, 'vermelha', NULL);
