INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l07-12', 'lista-07', '12ª', 'Ajuste de Curvas', 'minimos-quadrados', 3, 'numero', 0, NULL, 'Com o ajuste g(t) = at² + bt + c da população (ano: 4 | 5 | 6 | 7; população × 10⁴: 1,0 | 1,5 | 1,8 | 2,0), determine aproximadamente em que ano a população era de 17 000 pessoas.', '5,6', '5,6', 5.59682779275, 5.6, NULL, NULL, NULL, 1, NULL, '{"calc":"mq","base":"parabola","xs":[4,5,6,7],"ys":[1,1.5,1.8,2],"y":1.7,"faixa":[4,7]}', 'g(x) = −2,4150 + 1,1550·x − 0,0750·x²; g(x*) = 1,7 ⇒ x* = 5,5968.', NULL, 0, 'vermelha', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l07-12', 'A', '6,0', 0, 'Esse é o resultado com outro ajuste (uma exponencial); a questão pede a parábola.');
