INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l07-13', 'lista-07', '13ª', 'Ajuste de Curvas', 'minimos-quadrados', 2, 'vetor', 0, NULL, 'Com os dados da população (ano: 4 | 5 | 6 | 7; população × 10⁴: 1,0 | 1,5 | 1,8 | 2,0), ajuste pelo método dos mínimos quadrados uma função do tipo g(t) = a·eᵇᵗ.', 'g(t) = 0,439·e^(0,226t)', 'g(t) = 0,439·e^(0,226t)', NULL, NULL, '[0.43938908248,0.226176309847]', '[0.439,0.226]', NULL, 3, NULL, '{"calc":"mq","base":"exp","xs":[4,5,6,7],"ys":[1,1.5,1.8,2]}', 'g(t) = 0,439·e^(0,226t).', NULL, 0, 'vermelha', NULL);
