INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l07-14', 'lista-07', '14ª', 'Ajuste de Curvas', 'minimos-quadrados', 2, 'vetor', 0, NULL, 'Uma função f varia segundo a tabela x: 0,00 | 0,25 | 0,50 | 0,75 | 1,00; f(x): 1,0000 | 1,2840 | 1,6487 | 2,1179 | 2,7183. Utilizando o método dos mínimos quadrados, ajuste uma função do tipo g(x) = ax² + bx + c.', 'g(x) = 0,8432x² + 0,8647x + 1,0051', 'g(x) = 0,8426x² + 0,8656x + 1,0050', NULL, NULL, '[1.00500857143,0.865571428571,0.842628571429]', '[1.0051,0.8647,0.8432]', NULL, 4, 0.002, '{"calc":"mq","base":"parabola","xs":[0,0.25,0.5,0.75,1],"ys":[1,1.284,1.6487,2.1179,2.7183]}', 'g(x) = 1,0050 + 0,8656·x + 0,8426·x².', NULL, 0, 'vermelha', NULL);
