INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l07-15', 'lista-07', '15ª', 'Ajuste de Curvas', 'minimos-quadrados', 1, 'vetor', 0, NULL, 'Uma rede de eletrodomésticos tem o volume de computadores vendidos em função do tempo (t (mês): 1 | 2 | 3 | 4 | 5 | 6; n(t) (× 10³): 9 | 11 | 10 | 13 | 13 | 14). Utilizando o método dos mínimos quadrados, ajuste uma função do tipo g(t) = at + b.', 'g(t) = 0,97t + 8,27', 'g(x) = 0,97x + 8,27', NULL, NULL, '[8.26666666667,0.971428571429]', '[8.27,0.97]', NULL, 2, NULL, '{"calc":"mq","base":"reta","xs":[1,2,3,4,5,6],"ys":[9,11,10,13,13,14]}', 'g(x) = 8,2667 + 0,9714·x.', NULL, 0, 'vermelha', NULL);
