INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l07-16', 'lista-07', '16ª', 'Ajuste de Curvas', 'minimos-quadrados', 2, 'numero', 0, NULL, 'Com o ajuste g(t) = at + b das vendas (t (mês): 1 | 2 | 3 | 4 | 5 | 6; n(t) (× 10³): 9 | 11 | 10 | 13 | 13 | 14), determine em que mês o número de computadores vendidos será 16 000.', '8', '8', 7.96078431373, 8, NULL, NULL, NULL, 0, 0.1, '{"calc":"mq","base":"reta","xs":[1,2,3,4,5,6],"ys":[9,11,10,13,13,14],"y":16,"faixa":[1,12]}', 'g(x) = 8,2667 + 0,9714·x; g(x*) = 16 ⇒ x* = 7,9608.', NULL, 0, 'vermelha', NULL);
