INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l07-20', 'lista-07', '20ª', 'Ajuste de Curvas', 'minimos-quadrados', 2, 'numero', 0, NULL, 'Com os dados da população (ano: 4 | 5 | 6 | 7; população × 10⁴: 1,0 | 1,5 | 1,8 | 2,0), ajuste uma função do tipo g(t) = a·eᵇᵗ e calcule o ano em que a população será de 42 070 pessoas.', '10', '10', 9.9883129754, 10, NULL, NULL, NULL, 0, 0.1, '{"calc":"mq","base":"exp","xs":[4,5,6,7],"ys":[1,1.5,1.8,2],"y":42070,"escala":10000}', 'g(t) = 0,439·e^(0,226t); g(x*) = 42070 ⇒ x* = 9,9883.', NULL, 0, 'vermelha', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l07-20', 'A', '10', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l07-20', 'B', '4', 0, 'Não confere: refaça a conta passo a passo (veja a resolução).');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l07-20', 'C', '7', 0, 'Não confere: refaça a conta passo a passo (veja a resolução).');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l07-20', 'D', '1', 0, 'Não confere: refaça a conta passo a passo (veja a resolução).');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l07-21', 'lista-07', '21ª', 'Ajuste de Curvas', 'minimos-quadrados', 1, 'vetor', 0, NULL, 'Ajuste a tabela x: −1 | 0 | 1 | 2; y: 1 | −1 | 2 | 3 por uma reta utilizando o método dos mínimos quadrados.', 'y = 0,9x + 0,8', 'g(x) = 0,9x + 0,8', NULL, NULL, '[0.8,0.9]', '[0.8,0.9]', NULL, 1, NULL, '{"calc":"mq","base":"reta","xs":[-1,0,1,2],"ys":[1,-1,2,3]}', 'g(x) = 0,8000 + 0,9000·x.', NULL, 0, 'vermelha', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l07-21', 'A', 'g(x) = 0,9x + 0,9', 0, 'A primeira componente não confere: refaça a conta.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l07-21', 'B', 'g(x) = −0,9x + 0,8', 0, 'Sinal do segundo coeficiente trocado.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l07-21', 'C', 'g(x) = 0,8x + 0,9', 0, 'Coeficientes trocados de lugar.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l07-21', 'D', 'g(x) = 0,9x + 0,8', 1, NULL);
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l07-22', 'lista-07', '22ª', 'Ajuste de Curvas', 'minimos-quadrados', 1, 'vetor', 0, NULL, 'Ache a fórmula do tipo y = ax + b para a tabela x: 0,30 | 0,40 | 0,50 | 0,80; y: 0,30 | 0,30 | 0,40 | 0,60 pelo método dos mínimos quadrados. Use 3 decimais.', 'y = 0,643x + 0,079', 'g(x) = 0,643x + 0,079', NULL, NULL, '[0.0785714285714,0.642857142857]', '[0.079,0.643]', NULL, 3, NULL, '{"calc":"mq","base":"reta","xs":[0.3,0.4,0.5,0.8],"ys":[0.3,0.3,0.4,0.6]}', 'g(x) = 0,0786 + 0,6429·x.', NULL, 0, 'vermelha', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l07-22', 'A', 'g(x) = 0,643x + 0,079', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l07-22', 'B', 'g(x) = 0,079x + 0,643', 0, 'Coeficientes trocados de lugar.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l07-22', 'C', 'g(x) = 0,643x + 0,088', 0, 'A primeira componente não confere: refaça a conta.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l07-22', 'D', 'g(x) = −0,643x + 0,079', 0, 'Sinal do segundo coeficiente trocado.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l07-23', 'lista-07', '23ª', 'Ajuste de Curvas', 'minimos-quadrados', 2, 'vetor', 0, NULL, 'Ache a fórmula do tipo y = a·10ᵇˣ pelo método dos mínimos quadrados para a tabela x: 1 | 2 | 3 | 4 | 5 | 6; y: 1,3 | 2,8 | 6,2 | 13,8 | 33,6 | 64,2. Use 3 decimais.', 'y = 0,584·10^(0,344x)', 'y = 0,583·10^(0,344x)', NULL, NULL, '[0.583322586444,0.344371128967]', '[0.584,0.344]', NULL, 3, 0.001, '{"calc":"mq","base":"pot10","xs":[1,2,3,4,5,6],"ys":[1.3,2.8,6.2,13.8,33.6,64.2]}', 'y = 0,583·10^(0,344x).', NULL, 0, 'vermelha', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l07-23', 'A', 'y = 0,583·10^(−0,344x)', 0, 'Sinal do segundo coeficiente trocado.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l07-23', 'B', 'y = 0,583·10^(0,344x)', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l07-23', 'C', 'y = 0,344·10^(0,583x)', 0, 'Coeficientes trocados de lugar.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l07-23', 'D', 'y = −0,539·10^(0,344x)', 0, 'Esse é o coeficiente linear da reta ajustada (ln a ou log a): falta voltar para a, elevando e (ou 10) a esse valor.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l07-24', 'lista-07', '24ª', 'Ajuste de Curvas', 'minimos-quadrados', 2, 'numero', 0, NULL, 'Ache a fórmula do tipo y = a·10ᵇˣ pelo método dos mínimos quadrados para a tabela x: 1 | 2 | 3 | 4 | 5 | 6; y: 1,3 | 2,8 | 6,2 | 13,8 | 33,6 | 64,2 e calcule o x correspondente a y = 50. Use 3 decimais.', '5,62', '5,61', 5.61330799522, 5.62, NULL, NULL, NULL, 2, 0.01, '{"calc":"mq","base":"pot10","xs":[1,2,3,4,5,6],"ys":[1.3,2.8,6.2,13.8,33.6,64.2],"y":50}', 'y = 0,583·10^(0,344x); g(x*) = 50 ⇒ x* = 5,6133.', 'A lista usa a = 0,584 e b = 0,344 já arredondados (x = 5,618 ≈ 5,62); com os coeficientes completos, x = 5,613.', 0, 'vermelha', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l07-24', 'A', '6,01', 0, 'Esse é o resultado com outro ajuste (uma reta); a questão pede y = a·10ᵇˣ.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l07-24', 'B', '5,61', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l07-24', 'C', '5,84', 0, 'Não confere: refaça a conta passo a passo (veja a resolução).');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l07-24', 'D', '5,57', 0, 'Esse é o resultado com outro ajuste (uma parábola); a questão pede y = a·10ᵇˣ.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l07-25', 'lista-07', '25ª', 'Ajuste de Curvas', 'minimos-quadrados', 2, 'vetor', 0, NULL, 'Foram feitas cinco medições da velocidade de um carro de Fórmula 1 e da pressão do ar na superfície do aerofólio dianteiro: Vᵢ: 7,87 | 11,50 | 16,40 | 22,60 | 32,80; pᵢ: 0,014 | 0,028 | 0,056 | 0,112 | 0,225. Utilize o método dos mínimos quadrados, considerando p(V) = a + bV².', 'p = 0,001203 + 0,000209V²', 'p(V) = 0,001204 + 0,000209V²', NULL, NULL, '[0.0012035526966,0.000209285466668]', '[0.001203,0.000209]', NULL, 6, NULL, '{"calc":"mq","base":"a+bv2","xs":[7.87,11.5,16.4,22.6,32.8],"ys":[0.014,0.028,0.056,0.112,0.225]}', 'g(x) = 0,0012 + 0,0002·V².', NULL, 0, 'vermelha', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l07-25', 'A', 'p(V) = 0,001348 + 0,000209V²', 0, 'A primeira componente não confere: refaça a conta.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l07-25', 'B', 'p(V) = 0,001204 − 0,000209V²', 0, 'Sinal do segundo coeficiente trocado.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l07-25', 'C', 'p(V) = 0,001204 + 0,000209V²', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l07-25', 'D', 'p(V) = 0,000209 + 0,001204V²', 0, 'Coeficientes trocados de lugar.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l08-01', 'lista-08', '1ª', 'Integração Numérica', 'simpson13', 1, 'numero', 0, NULL, 'Calcule a integral ∫₀¹ eˣ dx aplicando a regra de Simpson, com 5 pontos e 5 casas decimais.', '1,7183', '1,7183', 1.71831884192, 1.7183, NULL, NULL, NULL, 4, NULL, '{"calc":"integral","regra":"simpson13","f":"exp(x)","a":0,"b":1,"pontos":5}', 'regra de Simpson (1/3) com 5 pontos: I ≈ 1,71832.', NULL, 0, 'vermelha', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l08-01', 'A', '1,7272', 0, 'Esse é o resultado pela regra dos trapézios; a questão pede a regra de Simpson 1/3.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l08-01', 'B', '1,7138', 0, 'Esse é o resultado pela regra dos retângulos; a questão pede a regra de Simpson 1/3.');
