INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l08-01', 'D', '1,7183', 1, NULL);
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l08-02', 'lista-08', '2ª', 'Integração Numérica', 'trapezios', 2, 'numero', 0, NULL, 'Calcule a integral Iₜ = ∫₀¹ eˣ dx pela regra dos trapézios, com 5 pontos e 5 casas decimais, e determine o erro relativo E_R = |Iₜ − I_c| / |I_c| em relação ao valor correto I_c.', '0,52%', '0,52%', 0.520291604695, 0.52, NULL, NULL, NULL, 2, NULL, '{"calc":"integral-erro","regra":"trapezios","f":"exp(x)","a":0,"b":1,"pontos":5,"exato":1.718281828459045}', 'regra dos trapézios: I ≈ 1,72722; valor correto 1,71828; E_R = 0,52%.', NULL, 0, 'vermelha', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l08-02', 'A', '0,01%', 0, 'Faltou multiplicar por 100.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l08-02', 'B', '0,52%', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l08-02', 'C', '0,26%', 0, 'Esse é o resultado pela regra dos retângulos; a questão pede a regra dos trapézios.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l08-02', 'D', '0,00%', 0, 'Esse é o resultado pela regra de Simpson 1/3; a questão pede a regra dos trapézios.');
