INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l08-26', 'lista-08', '26ª', 'Integração Numérica', 'simpson13', 2, 'numero', 0, NULL, 'Sabendo que a abscissa do centro de gravidade de uma área pode ser calculada por x̄ = ∫x·y dx / ∫y dx (de x₀ a x₄), ache a abscissa do centro de gravidade da seção central de uma embarcação baseada na tabela (x (m): 0 | 2 | 4 | 6 | 8; y (m): 12,5 | 12,8 | 12,9 | 13,0 | 13,0). Utilize a regra de Simpson.', '4,0233 m', '4,0233 m', 4.02330097087, 4.0233, NULL, NULL, NULL, 4, NULL, '{"calc":"centro-gravidade","regra":"simpson13","xs":[0,2,4,6,8],"ys":[12.5,12.8,12.9,13,13]}', 'x̄ = ∫x·y dx / ∫y dx = 414,4000 / 103,0000 = 4,0233 (regra de Simpson (1/3)).', NULL, 0, 'vermelha', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l08-26', 'A', '4,0233 m', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l08-26', 'B', '4,0000 m', 0, 'Esse é só o meio do intervalo; o centro de gravidade pondera cada x pela altura y: x̄ = ∫x·y dx / ∫y dx.');
