INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l08-28', 'lista-08', '28ª', 'Integração Numérica', 'simpson13', 1, 'numero', 0, NULL, 'Seja c (cal/g·°C) o calor específico de um corpo à temperatura θ (°C). Encontre o calor Q (cal) necessário para elevar a temperatura de um grama de água de 0 °C a 8 °C, com Q = m·∫c dθ, dada a tabela θᵢ: 0 | 2 | 4 | 6 | 8; cᵢ: 1,00664 | 1,00543 | 1,00453 | 1,00331 | 1,00233. Utilize a regra de Simpson.', '8,0353 cal', '8,0353 cal', 8.03532666667, 8.0353, NULL, NULL, NULL, 4, NULL, '{"calc":"integral","regra":"simpson13","xs":[0,2,4,6,8],"ys":[1.00664,1.00543,1.00453,1.00331,1.00233]}', 'regra de Simpson (1/3) com os 5 pontos da tabela: I ≈ 8,03533.', NULL, 0, 'vermelha', NULL);
