INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l08-30', 'lista-08', '30ª', 'Integração Numérica', 'simpson13', 2, 'numero', 0, NULL, 'Ache o comprimento do arco da curva y = x³, da origem até o ponto (2, 8): C = ∫ √(1 + (dy/dx)²) dx = ∫₀² √(1 + 9x⁴) dx. Utilize a regra de Simpson com 5 pontos e 4 decimais.', '8,610', '8,610', 8.61013967117, 8.61, NULL, NULL, NULL, 3, NULL, '{"calc":"integral","regra":"simpson13","f":"sqrt(1+9x^4)","a":0,"b":2,"pontos":5}', 'regra de Simpson (1/3) com 5 pontos: I ≈ 8,61014.', NULL, 0, 'vermelha', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l08-30', 'A', '8,878', 0, 'Esse é o resultado pela regra dos trapézios; a questão pede a regra de Simpson 1/3.');
