INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l08-31', 'lista-08', '31ª', 'Integração Numérica', 'trapezios', 2, 'numero', 0, NULL, 'Ache o comprimento do arco da curva y = x³, da origem até o ponto (2, 8): C = ∫ √(1 + (dy/dx)²) dx = ∫₀² √(1 + 9x⁴) dx. Utilize a regra dos trapézios com 5 pontos e 4 decimais.', '8,8784 u.c.', '8,8784 u.c.', 8.87837349077, 8.8784, NULL, NULL, NULL, 4, NULL, '{"calc":"integral","regra":"trapezios","f":"sqrt(1+9x^4)","a":0,"b":2,"pontos":5}', 'regra dos trapézios com 5 pontos: I ≈ 8,87837.', NULL, 0, 'vermelha', NULL);
