INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l08-32', 'lista-08', '32ª', 'Integração Numérica', 'simpson13', 3, 'numero', 0, NULL, 'A função de Debye é usada no cálculo do calor específico, a volume constante, de certas substâncias: C(θ) = (3/θ³)·∫ x³/(eˣ − 1) dx, de 0 a θ. Calcule C(0,4) usando a regra de Simpson com passo h = 0,1. Trabalhe com 4 decimais. Observação: lim (x→0) x³/(eˣ − 1) = 0.', '0,858', '0,858', 0.858005377385, 0.858, NULL, NULL, NULL, 3, NULL, '{"calc":"integral","regra":"simpson13","f":"x^3/(exp(x)-1)","a":0,"b":0.4,"n":4,"f0":0,"fator":46.875}', 'regra de Simpson (1/3) com n = 4: I ≈ 0,85801.', NULL, 0, 'vermelha', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l08-32', 'A', '0,824', 0, 'Não confere: refaça a conta passo a passo (veja a resolução).');
