INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l09-01', 'lista-09', '1ª', 'Integração Numérica — continuação', 'simpson38', 1, 'numero', 0, NULL, 'Calcule a integral ∫₀¹ eˣ dx aplicando a regra de Simpson 3/8, com 7 pontos e 5 casas decimais.', '1,71830', '1,71830', 1.71829829247, 1.7183, NULL, NULL, NULL, 5, NULL, '{"calc":"integral","regra":"simpson38","f":"exp(x)","a":0,"b":1,"pontos":7}', 'regra de Simpson 3/8 com 7 pontos: I ≈ 1,71830.', NULL, 0, 'vermelha', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l09-01', 'A', '1,72226', 0, 'Esse é o resultado pela regra dos trapézios; a questão pede a regra de Simpson 3/8.');
