INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l09-02', 'lista-09', '2ª', 'Integração Numérica — continuação', 'simpson38', 1, 'numero', 0, NULL, 'Calcule a integral ∫ eˣ·cos x dx de 0 a 1,2 pela regra de Simpson 3/8, com 3 subintervalos e 4 casas decimais.', '1,6166', '1,6465', 1.64653539297, 1.6166, NULL, NULL, NULL, 4, NULL, '{"calc":"integral","regra":"simpson38","f":"exp(x)cos(x)","a":0,"b":1.2,"n":3}', 'regra de Simpson 3/8 com n = 3: I ≈ 1,64654.', 'O gabarito da lista (1,6166) não sai da regra 3/8 com 3 subintervalos (h = 0,4): (3·0,4/8)·[f(0) + 3f(0,4) + 3f(0,8) + f(1,2)] = 1,6465. O valor exato da integral é 1,6488.', 1, 'vermelha', NULL);
