INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l09-04', 'lista-09', '4ª', 'Integração Numérica — continuação', 'simpson38', 1, 'numero', 0, NULL, 'Dada a tabela Vᵢ: 2 | 4 | 6 | 8 | 10 | 12 | 14; pᵢ: 10,5 | 42,7 | 25,3 | 16,7 | 13,0 | 15,8 | 32,4, com p = p(V), para vapor de água superaquecido, ache o trabalho realizado W = ∫ p(V) dV (de V₀ a V₆). Utilize a regra de Simpson 3/8.', '275,03', '275,03', 275.025, 275.03, NULL, NULL, NULL, 2, NULL, '{"calc":"integral","regra":"simpson38","xs":[2,4,6,8,10,12,14],"ys":[10.5,42.7,25.3,16.7,13,15.8,32.4]}', 'regra de Simpson 3/8 com os 7 pontos da tabela: I ≈ 275,02500.', NULL, 0, 'vermelha', NULL);
