INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l09-05', 'lista-09', '5ª', 'Integração Numérica — continuação', 'simpson38', 2, 'numero', 0, NULL, 'Sabendo que a abscissa do centro de gravidade de uma área pode ser calculada por x̄ = ∫x·y dx / ∫y dx (de x₀ a x₆), ache a abscissa do centro de gravidade da seção central de uma embarcação baseada na tabela x (m): 0 | 2 | 4 | 6 | 8 | 10 | 12; y (m): 12,5 | 12,8 | 12,9 | 13,0 | 13,0 | 13,3 | 14,2. Utilize a regra de Simpson 3/8.', '6,0799 m', '6,0805 m', 6.08049832295, 6.0799, NULL, NULL, NULL, 4, 0.001, '{"calc":"centro-gravidade","regra":"simpson38","xs":[0,2,4,6,8,10,12],"ys":[12.5,12.8,12.9,13,13,13.3,14.2]}', 'x̄ = ∫x·y dx / ∫y dx = 951,7500 / 156,5250 = 6,0805 (regra de Simpson 3/8).', NULL, 0, 'vermelha', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l09-05', 'A', '6,0792 m', 0, 'Esse é o resultado pela regra de Simpson 1/3; a questão pede a regra de Simpson 3/8. (É o valor que aparece no gabarito da lista: veja a observação da questão.)');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('l09-05', 'B', '6,0000 m', 0, 'Esse é só o meio do intervalo; o centro de gravidade pondera cada x pela altura y: x̄ = ∫x·y dx / ∫y dx.');
