INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l09-06', 'lista-09', '6ª', 'Integração Numérica — continuação', 'simpson38', 1, 'numero', 0, NULL, 'Seja c (cal/g·°C) o calor específico de um corpo à temperatura θ (°C), dado na tabela θᵢ: 0 | 2 | 4 | 6; cᵢ: 1,00664 | 1,00543 | 1,00453 | 1,00331. Encontre o calor Q (cal) necessário para elevar a temperatura de um grama de água de 0 °C a 6 °C, com Q = m·∫c dθ. Utilize a regra de Simpson 3/8.', '6,02987 cal', '6,02987 cal', 6.0298725, 6.02987, NULL, NULL, NULL, 5, NULL, '{"calc":"integral","regra":"simpson38","xs":[0,2,4,6],"ys":[1.00664,1.00543,1.00453,1.00331]}', 'regra de Simpson 3/8 com os 4 pontos da tabela: I ≈ 6,02987.', NULL, 0, 'vermelha', NULL);
