INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('l09-09', 'lista-09', '9ª', 'Integração Numérica — continuação', 'simpson38', 2, 'numero', 0, NULL, 'Ache o comprimento do arco da curva y = x³, da origem até o ponto (2, 8): C = ∫ √(1 + (dy/dx)²) dx = ∫₀² √(1 + 9x⁴) dx. Utilize a regra de Simpson 3/8 com 7 pontos e 5 decimais.', '8,62333', '8,62333', 8.62332559743, 8.62333, NULL, NULL, NULL, 5, NULL, '{"calc":"integral","regra":"simpson38","f":"sqrt(1+9x^4)","a":0,"b":2,"pontos":7}', 'regra de Simpson 3/8 com 7 pontos: I ≈ 8,62333.', 'A lista pula da 6ª para a 9ª questão.', 0, 'vermelha', NULL);
