INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('cc-fl-trunc', 'conceitos', '', 'Perguntas rápidas de conceito', 'ponto-flutuante', 1, 'texto', 1, NULL, 'Num sistema F(10, 4, m, M), qual é fl(3,14159) com truncamento?', NULL, '0,3141 × 10¹', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"Normalizando, 3,14159 = 0,314159 × 10¹. A mantissa guarda t = 4 dígitos e truncar é descartar o resto: 0,3141 × 10¹."}', 'Normalizando, 3,14159 = 0,314159 × 10¹. A mantissa guarda t = 4 dígitos e truncar é descartar o resto: 0,3141 × 10¹.', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('cc-fl-trunc', 'A', '3,141 × 10⁰', 0, 'A mantissa normalizada é 0,d₁d₂d₃d₄ com d₁ ≠ 0.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('cc-fl-trunc', 'B', '0,3141 × 10¹', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('cc-fl-trunc', 'C', '0,31415 × 10¹', 0, 'São 5 dígitos: a mantissa tem t = 4.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('cc-fl-trunc', 'D', '0,3142 × 10¹', 0, 'Esse é o arredondamento: o 5º dígito (5) faria o 4º subir. Truncar só corta.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('cc-fl-overflow', 'conceitos', '', 'Perguntas rápidas de conceito', 'ponto-flutuante', 1, 'texto', 1, NULL, 'Num sistema de ponto flutuante F(β, t, m, M), quando acontece overflow?', NULL, 'Quando o expoente do resultado passa de M', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"O maior número representável é 0,(β−1)(β−1)… × βᴹ. Um resultado com expoente maior que M não cabe: é overflow. Expoente menor que m é underflow."}', 'O maior número representável é 0,(β−1)(β−1)… × βᴹ. Um resultado com expoente maior que M não cabe: é overflow. Expoente menor que m é underflow.', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('cc-fl-overflow', 'A', 'Quando o resultado é zero', 0, 'Zero é representável.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('cc-fl-overflow', 'B', 'Quando o expoente do resultado passa de M', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('cc-fl-overflow', 'C', 'Quando a mantissa tem mais de t dígitos', 0, 'Aí basta arredondar ou truncar: não é overflow.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('cc-fl-overflow', 'D', 'Quando o expoente fica menor que m', 0, 'Isso é underflow.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('cc-interp-grau', 'conceitos', '', 'Perguntas rápidas de conceito', 'interpolacao', 1, 'texto', 1, NULL, 'Por n + 1 pontos com abscissas distintas passa um único polinômio interpolador de que grau?', NULL, 'Grau no máximo n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"O sistema de Vandermonde com n + 1 pontos distintos tem solução única: o polinômio interpolador tem grau ≤ n."}', 'O sistema de Vandermonde com n + 1 pontos distintos tem solução única: o polinômio interpolador tem grau ≤ n.', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('cc-interp-grau', 'A', 'Sempre grau 1', 0, 'Grau 1 é a interpolação linear, entre dois pontos.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('cc-interp-grau', 'B', 'Grau 2n', 0, 'Grau 2n tem coeficientes demais para os n + 1 pontos.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('cc-interp-grau', 'C', 'Grau no máximo n', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('cc-interp-grau', 'D', 'Grau n + 1', 0, 'Com grau n + 1 sobram coeficientes: haveria infinitos polinômios.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('cc-interp-inversa', 'conceitos', '', 'Perguntas rápidas de conceito', 'interpolacao', 1, 'texto', 1, NULL, 'Para achar x* tal que f(x*) = ȳ com uma tabela, o que a interpolação inversa faz?', NULL, 'Troca os papéis de x e y e interpola x como função de y', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"Em vez de montar p(x) e resolver p(x*) = ȳ, montamos x(y) passando pelos pontos (yᵢ, xᵢ) e calculamos x(ȳ). Exige f monótona no trecho."}', 'Em vez de montar p(x) e resolver p(x*) = ȳ, montamos x(y) passando pelos pontos (yᵢ, xᵢ) e calculamos x(ȳ). Exige f monótona no trecho.', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('cc-interp-inversa', 'A', 'Calcula f(ȳ) diretamente na tabela', 0, 'ȳ é um valor de f, não uma abscissa.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('cc-interp-inversa', 'B', 'Usa o método da Bisseção na tabela', 0, 'A Bisseção precisa de f em qualquer ponto, não só na tabela.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('cc-interp-inversa', 'C', 'Deriva a tabela', 0, 'Não há derivada na interpolação inversa.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('cc-interp-inversa', 'D', 'Troca os papéis de x e y e interpola x como função de y', 1, NULL);
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('cc-mq-ideia', 'conceitos', '', 'Perguntas rápidas de conceito', 'minimos-quadrados', 1, 'texto', 1, NULL, 'O que o método dos mínimos quadrados minimiza?', NULL, 'A soma dos quadrados dos desvios, Σ(yᵢ − g(xᵢ))²', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"O ajuste não passa por todos os pontos: escolhe os coeficientes que deixam a soma Σ(yᵢ − g(xᵢ))² a menor possível. Daí saem as equações normais."}', 'O ajuste não passa por todos os pontos: escolhe os coeficientes que deixam a soma Σ(yᵢ − g(xᵢ))² a menor possível. Daí saem as equações normais.', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('cc-mq-ideia', 'A', 'O número de pontos fora da curva', 0, 'O critério é contínuo: usa o tamanho dos desvios.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('cc-mq-ideia', 'B', 'A soma dos desvios, Σ(yᵢ − g(xᵢ))', 0, 'Desvios positivos e negativos se cancelariam.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('cc-mq-ideia', 'C', 'A soma dos quadrados dos desvios, Σ(yᵢ − g(xᵢ))²', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('cc-mq-ideia', 'D', 'O maior desvio', 0, 'Minimizar o maior desvio é outro critério (minimax).');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('cc-mq-exp', 'conceitos', '', 'Perguntas rápidas de conceito', 'minimos-quadrados', 1, 'texto', 1, NULL, 'Como ajustar g(t) = a·eᵇᵗ com o método dos mínimos quadrados para retas?', NULL, 'Aplicar ln: ln g = ln a + b·t, e ajustar uma reta aos pontos (tᵢ, ln yᵢ)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"A exponencial vira reta depois do logaritmo: Y = ln y = ln a + b·t. Ajusta-se a reta e depois a = e elevado ao coeficiente linear."}', 'A exponencial vira reta depois do logaritmo: Y = ln y = ln a + b·t. Ajusta-se a reta e depois a = e elevado ao coeficiente linear.', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('cc-mq-exp', 'A', 'Ajustar uma reta direto aos pontos (tᵢ, yᵢ)', 0, 'A reta não descreve a curva exponencial.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('cc-mq-exp', 'B', 'Elevar os yᵢ ao quadrado', 0, 'O quadrado não lineariza a exponencial.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('cc-mq-exp', 'C', 'Usar interpolação de Lagrange', 0, 'Lagrange passa por todos os pontos; aqui queremos o melhor ajuste.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('cc-mq-exp', 'D', 'Aplicar ln: ln g = ln a + b·t, e ajustar uma reta aos pontos (tᵢ, ln yᵢ)', 1, NULL);
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('cc-trap-formula', 'conceitos', '', 'Perguntas rápidas de conceito', 'trapezios', 1, 'texto', 1, NULL, 'Qual é a regra dos trapézios repetida com n subintervalos de largura h?', NULL, 'I ≈ (h/2)·[f₀ + 2(f₁ + … + fₙ₋₁) + fₙ]', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"Cada trapézio vale (h/2)(fᵢ + fᵢ₊₁); somando, os pontos internos aparecem duas vezes."}', 'Cada trapézio vale (h/2)(fᵢ + fᵢ₊₁); somando, os pontos internos aparecem duas vezes.', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('cc-trap-formula', 'A', 'I ≈ (3h/8)·[f₀ + 3f₁ + 3f₂ + 2f₃ + … + fₙ]', 0, 'Essa é a Simpson 3/8.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('cc-trap-formula', 'B', 'I ≈ h·(f₀ + f₁ + … + fₙ)', 0, 'Os extremos têm peso 1/2, não 1.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('cc-trap-formula', 'C', 'I ≈ (h/2)·[f₀ + 2(f₁ + … + fₙ₋₁) + fₙ]', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('cc-trap-formula', 'D', 'I ≈ (h/3)·[f₀ + 4f₁ + 2f₂ + … + fₙ]', 0, 'Essa é a regra de Simpson 1/3.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('cc-simp-n', 'conceitos', '', 'Perguntas rápidas de conceito', 'simpson13', 1, 'texto', 1, NULL, 'Que condição o número de subintervalos n precisa cumprir na regra de Simpson 1/3?', NULL, 'n precisa ser par', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"Simpson 1/3 usa parábolas por três pontos, ou seja, pares de subintervalos: n par (número ímpar de pontos)."}', 'Simpson 1/3 usa parábolas por três pontos, ou seja, pares de subintervalos: n par (número ímpar de pontos).', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('cc-simp-n', 'A', 'Qualquer n serve', 0, 'Os pesos 1-4-2-4-…-1 só fecham com n par.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('cc-simp-n', 'B', 'n precisa ser múltiplo de 3', 0, 'Essa é a condição da Simpson 3/8.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('cc-simp-n', 'C', 'n precisa ser ímpar', 0, 'Com n ímpar sobra um subintervalo sem parábola.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('cc-simp-n', 'D', 'n precisa ser par', 1, NULL);
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('cc-simp38-n', 'conceitos', '', 'Perguntas rápidas de conceito', 'simpson38', 1, 'texto', 1, NULL, 'Que condição o número de subintervalos n precisa cumprir na regra de Simpson 3/8?', NULL, 'n precisa ser múltiplo de 3', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"A Simpson 3/8 usa cúbicas por quatro pontos, ou seja, blocos de 3 subintervalos."}', 'A Simpson 3/8 usa cúbicas por quatro pontos, ou seja, blocos de 3 subintervalos.', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('cc-simp38-n', 'A', 'n precisa ser par', 0, 'Essa é a condição da Simpson 1/3.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('cc-simp38-n', 'B', 'n precisa ser primo', 0, 'Não há condição de primalidade.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('cc-simp38-n', 'C', 'n precisa ser múltiplo de 3', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('cc-simp38-n', 'D', 'n precisa ser 8', 0, 'O 8 do nome vem do fator 3h/8.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('cc-euler', 'conceitos', '', 'Perguntas rápidas de conceito', 'euler', 1, 'texto', 1, NULL, 'Qual é a fórmula do método de Euler para y′ = f(x, y)?', NULL, 'yₖ₊₁ = yₖ + h·f(xₖ, yₖ)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"Euler segue a reta tangente por um passo h: é a série de Taylor cortada no termo de 1ª ordem."}', 'Euler segue a reta tangente por um passo h: é a série de Taylor cortada no termo de 1ª ordem.', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('cc-euler', 'A', 'yₖ₊₁ = yₖ + h·f(xₖ, yₖ)', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('cc-euler', 'B', 'yₖ₊₁ = h·f(xₖ, yₖ)', 0, 'Faltou somar o yₖ.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('cc-euler', 'C', 'yₖ₊₁ = yₖ + (h²/2)·f(xₖ, yₖ)', 0, 'O termo de 1ª ordem é h·f.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('cc-euler', 'D', 'yₖ₊₁ = yₖ − f(xₖ, yₖ)/f′(xₖ, yₖ)', 0, 'Isso lembra o Newton-Raphson, que acha raízes.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('cc-taylor2', 'conceitos', '', 'Perguntas rápidas de conceito', 'taylor', 1, 'texto', 1, NULL, 'O que o método de Taylor de 2ª ordem acrescenta ao método de Euler?', NULL, 'O termo (h²/2)·y″, com y″ = fₓ + f_y·f', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"yₖ₊₁ = yₖ + h·f + (h²/2)·(fₓ + f_y·f). O termo extra corrige a curvatura e reduz o erro local de O(h²) para O(h³)."}', 'yₖ₊₁ = yₖ + h·f + (h²/2)·(fₓ + f_y·f). O termo extra corrige a curvatura e reduz o erro local de O(h²) para O(h³).', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('cc-taylor2', 'A', 'Um passo h dividido por 2', 0, 'Dividir o passo é outra ideia (Euler com h/2).');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('cc-taylor2', 'B', 'Nada: é o mesmo método', 0, 'O termo de 2ª ordem muda o resultado.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('cc-taylor2', 'C', 'A média de duas inclinações', 0, 'Isso é o Euler melhorado (Heun).');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('cc-taylor2', 'D', 'O termo (h²/2)·y″, com y″ = fₓ + f_y·f', 1, NULL);
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('bf-trunc-arred', 'basico', '', 'Perguntas básicas', 'ponto-flutuante', 1, 'texto', 1, NULL, 'Em F(10, 3, −5, 5), qual é a representação de x = 2,7182 por arredondamento?', NULL, '0,272 × 10¹', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"Normalizando: 2,7182 = 0,27182 × 10¹. Com t = 3 dígitos, o 4º dígito (8) é ≥ 5, então o 3º sobe: 0,272 × 10¹."}', 'Normalizando: 2,7182 = 0,27182 × 10¹. Com t = 3 dígitos, o 4º dígito (8) é ≥ 5, então o 3º sobe: 0,272 × 10¹.', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-trunc-arred', 'A', '0,272 × 10⁰', 0, 'Expoente errado: 0,272 × 10⁰ = 0,272, não 2,72.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-trunc-arred', 'B', '0,271 × 10¹', 0, 'Isso é o truncamento: descarta os dígitos sem olhar o 4º.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-trunc-arred', 'C', '0,272 × 10¹', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-trunc-arred', 'D', '0,2718 × 10¹', 0, 'São 4 dígitos na mantissa, e o sistema só guarda t = 3.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('bf-erro-relativo', 'basico', '', 'Perguntas básicas', 'ponto-flutuante', 1, 'texto', 1, NULL, 'x = 2,7182 foi aproximado por x̄ = 2,72. Qual é o erro relativo |x − x̄| / |x|?', NULL, '≈ 6,62 × 10⁻⁴', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"Erro absoluto: |2,7182 − 2,72| = 0,0018. Erro relativo: 0,0018 / 2,7182 ≈ 6,62 × 10⁻⁴ (ou 0,0662%)."}', 'Erro absoluto: |2,7182 − 2,72| = 0,0018. Erro relativo: 0,0018 / 2,7182 ≈ 6,62 × 10⁻⁴ (ou 0,0662%).', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-erro-relativo', 'A', '≈ 6,62', 0, 'Isso é o erro relativo multiplicado por 10⁴, não por 100.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-erro-relativo', 'B', '≈ 6,62 × 10⁻⁴', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-erro-relativo', 'C', '≈ 6,62 × 10⁻²', 0, 'Uma potência de 10 a mais: 0,0018 / 2,7182 ≈ 0,000662.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-erro-relativo', 'D', '1,8 × 10⁻³', 0, 'Esse é o erro absoluto |x − x̄|; falta dividir por |x|.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('bf-limitante-trunc', 'basico', '', 'Perguntas básicas', 'ponto-flutuante', 1, 'texto', 1, NULL, 'Na base 10 com t dígitos na mantissa, qual é o limitante do erro relativo do TRUNCAMENTO?', NULL, '|ER| < 10¹⁻ᵗ', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"Truncando, o erro absoluto é menor que uma unidade do último dígito guardado; dividindo pela mantissa (≥ 0,1) sai |ER| < 10¹⁻ᵗ. No arredondamento o limitante cai pela metade: ½ · 10¹⁻ᵗ."}', 'Truncando, o erro absoluto é menor que uma unidade do último dígito guardado; dividindo pela mantissa (≥ 0,1) sai |ER| < 10¹⁻ᵗ. No arredondamento o limitante cai pela metade: ½ · 10¹⁻ᵗ.', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-limitante-trunc', 'A', '|ER| < 10⁻ᵗ', 0, 'Falta considerar que a mantissa pode ser só 0,1: o limitante é 10 vezes maior.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-limitante-trunc', 'B', '|ER| < ½ · 10¹⁻ᵗ', 0, 'Esse é o limitante do arredondamento, que erra no máximo meia unidade.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-limitante-trunc', 'C', '|ER| < 10ᵗ', 0, 'O erro diminui quando t cresce: o expoente é negativo.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-limitante-trunc', 'D', '|ER| < 10¹⁻ᵗ', 1, NULL);
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('bf-erro-serie', 'basico', '', 'Perguntas básicas', 'series', 1, 'texto', 1, NULL, 'Calculamos e ≈ 1 + 1 + 1/2! + 1/3! e paramos a soma aí. Que erro aparece por cortar a série?', NULL, 'Erro de truncamento', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"Trocar um processo infinito (a série) por um finito gera erro de truncamento, mesmo com contas exatas. Arredondamento é outra coisa: vem de guardar números com poucos dígitos."}', 'Trocar um processo infinito (a série) por um finito gera erro de truncamento, mesmo com contas exatas. Arredondamento é outra coisa: vem de guardar números com poucos dígitos.', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-erro-serie', 'A', 'Erro de truncamento', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-erro-serie', 'B', 'Erro de arredondamento', 0, 'Arredondamento vem da representação dos números; aqui o erro vem de cortar a soma.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-erro-serie', 'C', 'Erro de dados de entrada', 0, 'Os dados (os termos da série) são exatos; o erro é de cortar a série.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-erro-serie', 'D', 'Overflow', 0, 'Nenhum número saiu da faixa representável.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('bf-cancel-porque', 'basico', '', 'Perguntas básicas', 'cancelamento', 1, 'texto', 1, NULL, 'Por que √(x + 1) − √x, com x = 10⁶, sai ruim numa máquina com poucos dígitos?', NULL, 'Subtrai números quase iguais e perde algarismos significativos', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"√1000001 ≈ 1000,0005 e √1000000 = 1000: os primeiros dígitos são iguais e se cancelam na subtração. Sobram poucos algarismos confiáveis (cancelamento catastrófico)."}', '√1000001 ≈ 1000,0005 e √1000000 = 1000: os primeiros dígitos são iguais e se cancelam na subtração. Sobram poucos algarismos confiáveis (cancelamento catastrófico).', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-cancel-porque', 'A', 'A raiz quadrada não pode ser calculada em ponto flutuante', 0, 'A raiz é calculada com boa precisão; o problema é a subtração.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-cancel-porque', 'B', 'Subtrai números quase iguais e perde algarismos significativos', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-cancel-porque', 'C', 'A conta dá zero porque √x é irracional', 0, 'O zero (quando aparece) vem do cancelamento, não da irracionalidade.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-cancel-porque', 'D', 'Dá overflow, porque 10⁶ é grande demais', 0, 'Mesmo com 4 dígitos, 10⁶ = 0,1 × 10⁷ cabe em qualquer sistema usual.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('bf-cancel-forma', 'basico', '', 'Perguntas básicas', 'cancelamento', 1, 'texto', 1, NULL, 'Qual expressão equivalente a √(x + 1) − √x evita o cancelamento?', NULL, '1 / (√(x + 1) + √x)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"Multiplicando e dividindo pelo conjugado: (√(x+1) − √x)(√(x+1) + √x) = 1. Fica 1/(√(x+1) + √x), uma soma de positivos, sem subtração perigosa."}', 'Multiplicando e dividindo pelo conjugado: (√(x+1) − √x)(√(x+1) + √x) = 1. Fica 1/(√(x+1) + √x), uma soma de positivos, sem subtração perigosa.', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-cancel-forma', 'A', '1 / (√(x + 1) + √x)', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-cancel-forma', 'B', '√(x + 1 − x) = 1', 0, '√a − √b ≠ √(a − b).');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-cancel-forma', 'C', '1 / (√(x + 1) − √x)', 0, 'O conjugado de uma diferença é a soma; aqui a subtração continua no denominador.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-cancel-forma', 'D', '√(x + 1) · √x', 0, 'Não é equivalente: para x = 1 dá √2, e a expressão original dá √2 − 1.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('bf-cancel-bhaskara', 'basico', '', 'Perguntas básicas', 'cancelamento', 1, 'texto', 1, NULL, 'Em x² − 1000x + 1 = 0, a raiz pequena por Bhaskara é (1000 − √999996)/2. Como calculá-la sem cancelamento?', NULL, '2 / (1000 + √999996)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"O produto das raízes é c/a = 1, então x_pequena = 1/x_grande = 2/(1000 + √999996). O denominador é uma soma: nenhum dígito se perde."}', 'O produto das raízes é c/a = 1, então x_pequena = 1/x_grande = 2/(1000 + √999996). O denominador é uma soma: nenhum dígito se perde.', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-cancel-bhaskara', 'A', '(1000 + √999996) / 2', 0, 'Essa é a raiz grande.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-cancel-bhaskara', 'B', '1000 − √999996', 0, 'Continua subtraindo números quase iguais (e falta o /2).');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-cancel-bhaskara', 'C', '2 / (1000 + √999996)', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-cancel-bhaskara', 'D', '2 / (1000 − √999996)', 0, 'Essa expressão é igual à raiz grande e ainda tem o cancelamento.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('bf-cancel-digitos', 'basico', '', 'Perguntas básicas', 'cancelamento', 1, 'texto', 1, NULL, 'Numa máquina de 4 algarismos significativos, 3,142 − 3,141 = 0,001. Quantos algarismos significativos confiáveis o resultado tem?', NULL, 'Apenas 1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"Os três primeiros dígitos (3,14) se cancelaram; só a última casa, que já carregava o erro de arredondamento, sobrou."}', 'Os três primeiros dígitos (3,14) se cancelaram; só a última casa, que já carregava o erro de arredondamento, sobrou.', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-cancel-digitos', 'A', 'Apenas 1', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-cancel-digitos', 'B', 'Nenhum: o resultado é sempre zero', 0, 'O resultado é 0,001, mas só com 1 algarismo confiável.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-cancel-digitos', 'C', '4, como os operandos', 0, 'A subtração não preserva os 4 dígitos: os iguais se cancelam.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-cancel-digitos', 'D', '3', 0, 'Os 3 dígitos iguais são justamente os que somem.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('bf-underflow', 'basico', '', 'Perguntas básicas', 'overflow', 1, 'texto', 1, NULL, 'Em F(β, t, m, M), o que acontece quando o expoente do resultado é MENOR que m?', NULL, 'Underflow', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"Expoente acima de M é overflow (número grande demais); abaixo de m é underflow (número pequeno demais, perto de zero)."}', 'Expoente acima de M é overflow (número grande demais); abaixo de m é underflow (número pequeno demais, perto de zero).', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-underflow', 'A', 'Truncamento', 0, 'Truncamento é cortar dígitos da mantissa.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-underflow', 'B', 'Overflow', 0, 'Overflow é expoente maior que M.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-underflow', 'C', 'Cancelamento', 0, 'Cancelamento é a perda de dígitos na subtração de números próximos.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-underflow', 'D', 'Underflow', 1, NULL);
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('bf-reescala', 'basico', '', 'Perguntas básicas', 'overflow', 1, 'texto', 1, NULL, 'Por que calcular √(a² + b²) como |a|·√(1 + (b/a)²), com |a| ≥ |b|, é mais seguro?', NULL, 'Evita o overflow de elevar números grandes ao quadrado', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"Se a = 10²⁰⁰, a² já estoura o double. Dividindo por |a| antes, (b/a)² ≤ 1 e o único número grande fica fora da raiz."}', 'Se a = 10²⁰⁰, a² já estoura o double. Dividindo por |a| antes, (b/a)² ≤ 1 e o único número grande fica fora da raiz.', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-reescala', 'A', 'Dá o resultado exato em ponto flutuante', 0, 'Continua havendo arredondamento; só some o risco de overflow.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-reescala', 'B', 'Faz menos contas', 0, 'Faz até mais contas; a vantagem é não estourar.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-reescala', 'C', 'Evita divisão por zero', 0, 'A forma reescalada é que divide por a; o ganho é evitar o overflow.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-reescala', 'D', 'Evita o overflow de elevar números grandes ao quadrado', 1, NULL);
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('bf-maior-numero', 'basico', '', 'Perguntas básicas', 'overflow', 1, 'texto', 1, NULL, 'Qual é o maior número representável em F(10, 3, −4, 4)?', NULL, '0,999 × 10⁴', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"Maior mantissa (0,999) com o maior expoente (M = 4): 0,999 × 10⁴ = 9990."}', 'Maior mantissa (0,999) com o maior expoente (M = 4): 0,999 × 10⁴ = 9990.', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-maior-numero', 'A', '0,999 × 10⁴', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-maior-numero', 'B', '0,999 × 10⁵', 0, 'O expoente máximo é M = 4.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-maior-numero', 'C', '0,100 × 10⁻⁴', 0, 'Esse é o menor número positivo.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-maior-numero', 'D', '0,100 × 10⁴', 0, 'Essa é a menor mantissa normalizada com o maior expoente.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('bf-menor-numero', 'basico', '', 'Perguntas básicas', 'overflow', 1, 'texto', 1, NULL, 'E o menor número positivo de F(10, 3, −4, 4)?', NULL, '0,100 × 10⁻⁴', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"Menor mantissa normalizada (0,100, primeiro dígito ≠ 0) com o menor expoente (m = −4): 0,100 × 10⁻⁴ = 10⁻⁵."}', 'Menor mantissa normalizada (0,100, primeiro dígito ≠ 0) com o menor expoente (m = −4): 0,100 × 10⁻⁴ = 10⁻⁵.', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-menor-numero', 'A', '0,100 × 10⁻⁴', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-menor-numero', 'B', '0,100 × 10⁻³', 0, 'O menor expoente é m = −4.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-menor-numero', 'C', '0,999 × 10⁻⁴', 0, 'Essa é a maior mantissa com o menor expoente.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-menor-numero', 'D', '0,001 × 10⁻⁴', 0, 'Mantissa não normalizada: o primeiro dígito precisa ser diferente de zero.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('bf-bis-x2', 'basico', '', 'Perguntas básicas', 'bissecao', 1, 'numero', 1, NULL, 'Bisseção em f(x) = x² − 3, no intervalo [1; 2]. Qual é x₂?', NULL, '1,7500', 1.75, NULL, NULL, NULL, NULL, 4, NULL, '{"calc":"bissecao","f":"x^2-3","a":1,"b":2,"iteracoes":2}', 'Bisseção: 2 iterações; x = 1,750000. 2 iterações, como pedido.
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-bis-x2', 'A', '1,5000', 0, 'Esse é x₁; o pedido é x₂.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-bis-x2', 'B', '1,6250', 0, 'Esse já é x₃ (o ponto médio de [1,5; 1,75]).');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-bis-x2', 'C', '1,7500', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-bis-x2', 'D', '1,2500', 0, 'Ficou com a metade errada: f(1,5) = −0,75 < 0 e f(2) > 0, então a raiz está em [1,5; 2].');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('bf-bis-k', 'basico', '', 'Perguntas básicas', 'bissecao', 1, 'numero', 1, NULL, 'Quantas iterações da Bisseção garantem erro menor que 0,001 começando em [1; 2]?', NULL, '10', 10, NULL, NULL, NULL, NULL, 0, NULL, '{"calc":"iteracoesBissecao","a":1,"b":2,"eps":0.001}', 'k > (log(1) − log(0,001))/log 2 = 9,9658, então k = 10.', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-bis-k', 'A', '1000', 0, 'Isso é (b − a)/ε, não o número de iterações: cada iteração divide o intervalo por 2.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-bis-k', 'B', '10', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-bis-k', 'C', '3', 0, 'Usou log na base 10: o intervalo cai pela metade, então a base é 2.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-bis-k', 'D', '9', 0, 'k > log(1/0,001)/log 2 ≈ 9,97: arredonde para cima.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('bf-bis-metade', 'basico', '', 'Perguntas básicas', 'bissecao', 1, 'texto', 1, NULL, 'Na Bisseção, depois de calcular xₖ = (aₖ + bₖ)/2, qual metade fica para a próxima iteração?', NULL, 'Se f(aₖ)·f(xₖ) < 0, o novo intervalo é [aₖ; xₖ]; senão, [xₖ; bₖ]', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"Fica a metade em que f troca de sinal: é ela que, pelo Teorema 1, ainda garante uma raiz."}', 'Fica a metade em que f troca de sinal: é ela que, pelo Teorema 1, ainda garante uma raiz.', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-bis-metade', 'A', 'A metade em que xₖ é positivo', 0, 'O que importa é o sinal de f(xₖ), não o de xₖ.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-bis-metade', 'B', 'Se f(aₖ)·f(xₖ) < 0, o novo intervalo é [aₖ; xₖ]; senão, [xₖ; bₖ]', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-bis-metade', 'C', 'Se f(aₖ)·f(xₖ) > 0, o novo intervalo é [aₖ; xₖ]', 0, 'Produto positivo quer dizer mesmo sinal: a troca de sinal (e a raiz) está na outra metade.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-bis-metade', 'D', 'A metade mais perto da raiz exata', 0, 'Não conhecemos a raiz exata; a decisão é pelo sinal de f.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('bf-bis-teorema', 'basico', '', 'Perguntas básicas', 'bissecao', 1, 'texto', 1, NULL, 'O que o Teorema 1 (Bolzano) exige para garantir pelo menos uma raiz de f em (a, b)?', NULL, 'f contínua em [a, b] e f(a)·f(b) < 0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"Função contínua que troca de sinal nas pontas passa pelo zero em algum ponto do intervalo (Teorema do Valor Intermediário)."}', 'Função contínua que troca de sinal nas pontas passa pelo zero em algum ponto do intervalo (Teorema do Valor Intermediário).', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-bis-teorema', 'A', 'f contínua em [a, b] e f(a)·f(b) < 0', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-bis-teorema', 'B', 'f derivável e f′(a)·f′(b) < 0', 0, 'O sinal da derivada fala de crescimento, não de raiz.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-bis-teorema', 'C', 'f(a)·f(b) > 0', 0, 'Mesmo sinal nas pontas não garante raiz.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-bis-teorema', 'D', 'f(a) = f(b)', 0, 'Essa é a hipótese do Teorema de Rolle (sobre f′), não de raiz de f.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('bf-fp-x1', 'basico', '', 'Perguntas básicas', 'falsa-posicao', 1, 'numero', 1, NULL, 'Falsa Posição em f(x) = x² − 3, no intervalo [1; 2]. Qual é x₁?', NULL, '1,6667', 1.66666666667, NULL, NULL, NULL, NULL, 4, NULL, '{"calc":"falsaPosicao","f":"x^2-3","a":1,"b":2,"iteracoes":1}', 'Falsa Posição: 1 iteração; x = 1,666667. 1 iteração, como pedido.
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-fp-x1', 'A', '1,5000', 0, 'Esse é o ponto médio: é a Bisseção.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-fp-x1', 'B', '1,7500', 0, 'Esse é o x₂ da Bisseção.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-fp-x1', 'C', '1,6667', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-fp-x1', 'D', '1,3333', 0, 'Pesos trocados: x = (a·f(b) − b·f(a))/(f(b) − f(a)) = (1·1 − 2·(−2))/3.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('bf-fp-formula', 'basico', '', 'Perguntas básicas', 'falsa-posicao', 1, 'texto', 1, NULL, 'Qual é a fórmula da Falsa Posição no intervalo [a; b]?', NULL, 'x = (a·f(b) − b·f(a)) / (f(b) − f(a))', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"x é a média de a e b ponderada pelos |f| da ponta oposta: a reta pelos dois pontos corta o eixo x aí."}', 'x é a média de a e b ponderada pelos |f| da ponta oposta: a reta pelos dois pontos corta o eixo x aí.', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-fp-formula', 'A', 'x = (a·f(b) − b·f(a)) / (f(b) − f(a))', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-fp-formula', 'B', 'x = (a·f(a) − b·f(b)) / (f(a) − f(b))', 0, 'Os pesos estão trocados: cada ponta é pesada pelo f da OUTRA ponta.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-fp-formula', 'C', 'x = a − f(a)/f′(a)', 0, 'Essa é a fórmula de Newton-Raphson.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-fp-formula', 'D', 'x = (a + b)/2', 0, 'Esse é o ponto médio da Bisseção.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('bf-fp-lenta', 'basico', '', 'Perguntas básicas', 'falsa-posicao', 1, 'texto', 1, NULL, 'Por que a Falsa Posição pode ficar lenta quando f é muito curva no intervalo?', NULL, 'Uma das pontas fica parada e o intervalo não encolhe dos dois lados', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"Com f côncava (ou convexa) em [a, b], as cordas caem sempre do mesmo lado da raiz: uma extremidade nunca muda, e a largura do intervalo não vai a zero."}', 'Com f côncava (ou convexa) em [a, b], as cordas caem sempre do mesmo lado da raiz: uma extremidade nunca muda, e a largura do intervalo não vai a zero.', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-fp-lenta', 'A', 'Porque perde a troca de sinal', 0, 'A troca de sinal é sempre mantida, como na Bisseção.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-fp-lenta', 'B', 'Uma das pontas fica parada e o intervalo não encolhe dos dois lados', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-fp-lenta', 'C', 'Porque divide o intervalo exatamente ao meio', 0, 'Quem divide ao meio é a Bisseção.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-fp-lenta', 'D', 'Porque precisa calcular a derivada', 0, 'A Falsa Posição não usa derivada.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('bf-fp-geometria', 'basico', '', 'Perguntas básicas', 'falsa-posicao', 1, 'texto', 1, NULL, 'Geometricamente, o x₁ da Falsa Posição é…', NULL, 'onde a reta por (a, f(a)) e (b, f(b)) corta o eixo x', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"A Falsa Posição troca a curva pela corda entre as pontas do intervalo e usa o zero da corda."}', 'A Falsa Posição troca a curva pela corda entre as pontas do intervalo e usa o zero da corda.', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-fp-geometria', 'A', 'o vértice da parábola por três pontos', 0, 'Parábolas aparecem em Simpson/Müller, não aqui.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-fp-geometria', 'B', 'o ponto médio de [a; b]', 0, 'Ponto médio é a Bisseção.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-fp-geometria', 'C', 'onde a reta por (a, f(a)) e (b, f(b)) corta o eixo x', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-fp-geometria', 'D', 'onde a tangente em (a, f(a)) corta o eixo x', 0, 'Tangente é Newton-Raphson.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('bf-pf-condicao', 'basico', '', 'Perguntas básicas', 'ponto-fixo', 1, 'texto', 1, NULL, 'Reescrevendo f(x) = 0 como x = φ(x), que condição garante que xₖ₊₁ = φ(xₖ) converge perto da raiz?', NULL, '|φ′(x)| < 1 numa vizinhança da raiz (com x₀ nela)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"Se |φ′| ≤ k < 1 perto da raiz, cada passo multiplica o erro por no máximo k: o erro vai a zero."}', 'Se |φ′| ≤ k < 1 perto da raiz, cada passo multiplica o erro por no máximo k: o erro vai a zero.', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-pf-condicao', 'A', '|φ′(x)| > 1 perto da raiz', 0, 'Com |φ′| > 1 o erro aumenta a cada passo: diverge.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-pf-condicao', 'B', 'f′(x) ≠ 0 perto da raiz', 0, 'Essa é a condição de Newton; no Ponto Fixo a condição é sobre φ′.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-pf-condicao', 'C', 'φ(x) < 1 no intervalo', 0, 'O que importa é a inclinação φ′, não o valor de φ.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-pf-condicao', 'D', '|φ′(x)| < 1 numa vizinhança da raiz (com x₀ nela)', 1, NULL);
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('bf-pf-cos', 'basico', '', 'Perguntas básicas', 'ponto-fixo', 1, 'texto', 1, NULL, 'Ponto Fixo em x = cos x com x₀ = 1 (calculadora em radianos). Qual é x₁ = cos(x₀)?', NULL, '0,5403', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"x₁ = φ(x₀) = cos(1) = 0,5403 (radianos). A sequência vai oscilando até o ponto fixo 0,7391."}', 'x₁ = φ(x₀) = cos(1) = 0,5403 (radianos). A sequência vai oscilando até o ponto fixo 0,7391.', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-pf-cos', 'A', '0,9998', 0, 'Calculadora em graus: cos(1°) ≈ 0,9998.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-pf-cos', 'B', '0,8415', 0, 'Esse é sen(1).');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-pf-cos', 'C', '0,5403', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-pf-cos', 'D', '0,7391', 0, 'Esse é o ponto fixo final, não x₁.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('bf-pf-escolha', 'basico', '', 'Perguntas básicas', 'ponto-fixo', 1, 'texto', 1, NULL, 'f(x) = x² − x − 2 tem raízes −1 e 2. Qual função de iteração converge para a raiz 2?', NULL, 'φ(x) = √(x + 2)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"x² = x + 2 ⇒ x = √(x + 2). φ′(x) = 1/(2√(x + 2)), e φ′(2) = 1/4 < 1: converge."}', 'x² = x + 2 ⇒ x = √(x + 2). φ′(x) = 1/(2√(x + 2)), e φ′(2) = 1/4 < 1: converge.', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-pf-escolha', 'A', 'φ(x) = 2x² − 6', 0, 'φ(2) = 2, mas |φ′(2)| = 8 > 1: diverge.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-pf-escolha', 'B', 'φ(x) = x² − x − 2', 0, 'Essa é a própria f; o ponto fixo dela não é a raiz de f.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-pf-escolha', 'C', 'φ(x) = √(x + 2)', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-pf-escolha', 'D', 'φ(x) = x² − 2', 0, 'φ(2) = 2, mas |φ′(2)| = 4 > 1: diverge.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('bf-pf-grafico', 'basico', '', 'Perguntas básicas', 'ponto-fixo', 1, 'texto', 1, NULL, 'No gráfico, o ponto fixo de φ é…', NULL, 'a interseção de y = φ(x) com a reta y = x', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"Ponto fixo é onde φ(x) = x, ou seja, onde a curva de φ cruza a bissetriz y = x."}', 'Ponto fixo é onde φ(x) = x, ou seja, onde a curva de φ cruza a bissetriz y = x.', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-pf-grafico', 'A', 'a interseção de y = φ(x) com a reta y = x', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-pf-grafico', 'B', 'o ponto de máximo de φ', 0, 'Ponto fixo não tem relação com máximo.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-pf-grafico', 'C', 'onde φ′(x) = 0', 0, 'Isso é um ponto crítico de φ.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-pf-grafico', 'D', 'onde y = φ(x) corta o eixo x', 0, 'Isso é uma raiz de φ, não um ponto fixo.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('bf-pf-cos-3', 'basico', '', 'Perguntas básicas', 'ponto-fixo', 2, 'numero', 0, NULL, 'Ponto Fixo em x = cos x, com x₀ = 1 (radianos). Faça 3 iterações xₖ₊₁ = cos(xₖ). Qual é x₃?', NULL, '0,6543', 0.654289790498, NULL, NULL, NULL, NULL, 4, NULL, '{"calc":"pontoFixo","g":"cos(x)","x0":1,"iteracoes":3}', 'Ponto Fixo: 3 iterações; x = 0,654290. 3 iterações, como pedido.
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-pf-cos-3', 'A', '0,5403', 0, 'Esse é x₁.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-pf-cos-3', 'B', '0,6543', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-pf-cos-3', 'C', '0,9998', 0, 'Calculadora em graus.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-pf-cos-3', 'D', '0,7391', 0, 'Esse é o ponto fixo final; com 3 iterações ainda não chegamos lá.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('bf-pf-raiz-3', 'basico', '', 'Perguntas básicas', 'ponto-fixo', 3, 'numero', 0, NULL, 'Ponto Fixo para x² − x − 2 = 0 com φ(x) = √(x + 2) e x₀ = 1. Faça 3 iterações. Qual é x₃?', NULL, '1,9829', 1.98288972275, NULL, NULL, NULL, NULL, 4, NULL, '{"calc":"pontoFixo","g":"sqrt(x+2)","x0":1,"iteracoes":3}', 'Ponto Fixo: 3 iterações; x = 1,982890. 3 iterações, como pedido.
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-pf-raiz-3', 'A', '1,9829', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-pf-raiz-3', 'B', '1,9319', 0, 'Esse é x₂.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-pf-raiz-3', 'C', '1,7321', 0, 'Esse é x₁ = √3.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-pf-raiz-3', 'D', '2,0000', 0, 'Essa é a raiz; com 3 iterações ainda falta um pouco.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('bf-nr-x1', 'basico', '', 'Perguntas básicas', 'newton', 1, 'numero', 1, NULL, 'Newton-Raphson em f(x) = x² − 3, com f′(x) = 2x e x₀ = 2. Qual é x₁?', NULL, '1,7500', 1.75, NULL, NULL, NULL, NULL, 4, NULL, '{"calc":"newton","f":"x^2-3","df":"2x","x0":2,"iteracoes":1}', 'Newton-Raphson: 1 iteração; x = 1,750000. 1 iterações, como pedido.
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-nr-x1', 'A', '1,7500', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-nr-x1', 'B', '1,5000', 0, 'Derivada errada: f′(2) = 2·2 = 4, não 2.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-nr-x1', 'C', '1,7321', 0, 'Essa é a raiz √3, não x₁.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-nr-x1', 'D', '2,2500', 0, 'Sinal trocado: x₁ = x₀ − f(x₀)/f′(x₀) = 2 − 1/4.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('bf-nr-formula', 'basico', '', 'Perguntas básicas', 'newton', 1, 'texto', 1, NULL, 'Qual é a fórmula de Newton-Raphson?', NULL, 'xₖ₊₁ = xₖ − f(xₖ)/f′(xₖ)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"É o zero da reta tangente em (xₖ, f(xₖ)): 0 = f(xₖ) + f′(xₖ)(x − xₖ)."}', 'É o zero da reta tangente em (xₖ, f(xₖ)): 0 = f(xₖ) + f′(xₖ)(x − xₖ).', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-nr-formula', 'A', 'xₖ₊₁ = xₖ − f(xₖ)/f′(xₖ)', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-nr-formula', 'B', 'xₖ₊₁ = xₖ + f(xₖ)/f′(xₖ)', 0, 'Sinal trocado: o passo vai na direção contrária.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-nr-formula', 'C', 'xₖ₊₁ = (a·f(b) − b·f(a))/(f(b) − f(a))', 0, 'Essa é a Falsa Posição.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-nr-formula', 'D', 'xₖ₊₁ = xₖ − f′(xₖ)/f(xₖ)', 0, 'Fração invertida.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('bf-nr-falha', 'basico', '', 'Perguntas básicas', 'newton', 1, 'texto', 1, NULL, 'Em que situação Newton-Raphson costuma falhar?', NULL, 'Quando f′(xₖ) ≈ 0: a tangente fica quase horizontal e joga xₖ₊₁ para longe', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"O passo é f(xₖ)/f′(xₖ); com f′ perto de zero ele fica enorme. Também pode entrar em ciclo ou ir para outra raiz se x₀ estiver longe."}', 'O passo é f(xₖ)/f′(xₖ); com f′ perto de zero ele fica enorme. Também pode entrar em ciclo ou ir para outra raiz se x₀ estiver longe.', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-nr-falha', 'A', 'Quando f(x₀) > 0', 0, 'O sinal de f(x₀) sozinho não decide nada.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-nr-falha', 'B', 'Quando x₀ está bem perto da raiz', 0, 'Perto da raiz (simples) é justamente quando Newton converge rápido.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-nr-falha', 'C', 'Quando f é um polinômio', 0, 'Polinômios são o caso mais comum de uso.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-nr-falha', 'D', 'Quando f′(xₖ) ≈ 0: a tangente fica quase horizontal e joga xₖ₊₁ para longe', 1, NULL);
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('bf-nr-ordem', 'basico', '', 'Perguntas básicas', 'newton', 1, 'texto', 1, NULL, 'Qual é a ordem de convergência de Newton-Raphson numa raiz simples?', NULL, 'Quadrática (ordem 2)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"Perto da raiz, eₖ₊₁ ≈ C·eₖ²: o número de casas corretas praticamente dobra a cada iteração."}', 'Perto da raiz, eₖ₊₁ ≈ C·eₖ²: o número de casas corretas praticamente dobra a cada iteração.', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-nr-ordem', 'A', 'Cúbica (ordem 3)', 0, 'Newton é de ordem 2 numa raiz simples.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-nr-ordem', 'B', 'Quadrática (ordem 2)', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-nr-ordem', 'C', 'Linear (ordem 1)', 0, 'Linear é a Bisseção.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-nr-ordem', 'D', '≈ 1,618', 0, 'Essa é a ordem da Secante.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('bf-sec-x2', 'basico', '', 'Perguntas básicas', 'secante', 1, 'numero', 1, NULL, 'Secante em f(x) = x² − 3, com x₀ = 1 e x₁ = 2. Qual é x₂?', NULL, '1,6667', 1.66666666667, NULL, NULL, NULL, NULL, 4, NULL, '{"calc":"secante","f":"x^2-3","x0":1,"x1":2,"iteracoes":1}', 'Secante: 1 iteração; x = 1,666667. 1 iterações, como pedido.
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-sec-x2', 'A', '2,3333', 0, 'Sinal trocado: x₂ = x₁ − f(x₁)(x₁ − x₀)/(f(x₁) − f(x₀)) = 2 − 1/3.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-sec-x2', 'B', '1,5000', 0, 'Esse é o ponto médio (Bisseção).');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-sec-x2', 'C', '1,7500', 0, 'Esse é Newton a partir de x = 2.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-sec-x2', 'D', '1,6667', 1, NULL);
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('bf-sec-formula', 'basico', '', 'Perguntas básicas', 'secante', 1, 'texto', 1, NULL, 'Qual é a fórmula da Secante?', NULL, 'xₖ₊₁ = xₖ − f(xₖ)·(xₖ − xₖ₋₁)/(f(xₖ) − f(xₖ₋₁))', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"É Newton com a derivada trocada pela inclinação da reta pelos dois últimos pontos."}', 'É Newton com a derivada trocada pela inclinação da reta pelos dois últimos pontos.', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-sec-formula', 'A', 'xₖ₊₁ = (xₖ + xₖ₋₁)/2', 0, 'Ponto médio é a Bisseção.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-sec-formula', 'B', 'xₖ₊₁ = xₖ − f(xₖ)/f′(xₖ)', 0, 'Essa é Newton: usa a derivada.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-sec-formula', 'C', 'xₖ₊₁ = xₖ − (f(xₖ) − f(xₖ₋₁))/(xₖ − xₖ₋₁)', 0, 'Faltou multiplicar por f(xₖ) e a fração está invertida.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-sec-formula', 'D', 'xₖ₊₁ = xₖ − f(xₖ)·(xₖ − xₖ₋₁)/(f(xₖ) − f(xₖ₋₁))', 1, NULL);
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('bf-sec-vantagem', 'basico', '', 'Perguntas básicas', 'secante', 1, 'texto', 1, NULL, 'Qual é a principal vantagem da Secante sobre Newton-Raphson?', NULL, 'Não precisa da derivada f′', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"A Secante usa a inclinação da reta pelos dois últimos pontos. Converge com ordem ≈ 1,618, um pouco menos que Newton, mas sem calcular f′."}', 'A Secante usa a inclinação da reta pelos dois últimos pontos. Converge com ordem ≈ 1,618, um pouco menos que Newton, mas sem calcular f′.', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-sec-vantagem', 'A', 'Mantém sempre a troca de sinal', 0, 'Quem mantém a troca de sinal é a Falsa Posição.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-sec-vantagem', 'B', 'Não precisa da derivada f′', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-sec-vantagem', 'C', 'Tem ordem 2', 0, 'A ordem é ≈ 1,618.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-sec-vantagem', 'D', 'Sempre converge', 0, 'A Secante pode divergir, como Newton.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('bf-sec-vs-fp', 'basico', '', 'Perguntas básicas', 'secante', 1, 'texto', 1, NULL, 'O que diferencia a Secante da Falsa Posição?', NULL, 'A Secante usa sempre os dois últimos pontos, sem exigir troca de sinal', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"Ambas usam retas por dois pontos. A Falsa Posição escolhe os pontos para manter f(a)·f(b) < 0; a Secante só descarta o mais antigo."}', 'Ambas usam retas por dois pontos. A Falsa Posição escolhe os pontos para manter f(a)·f(b) < 0; a Secante só descarta o mais antigo.', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-sec-vs-fp', 'A', 'Não há diferença', 0, 'A regra de quais pontos manter é diferente.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-sec-vs-fp', 'B', 'A Secante usa sempre os dois últimos pontos, sem exigir troca de sinal', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-sec-vs-fp', 'C', 'A Secante usa a tangente', 0, 'Tangente é Newton.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-sec-vs-fp', 'D', 'A Falsa Posição não usa retas', 0, 'A Falsa Posição também usa a reta (corda) pelos dois pontos.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('bf-ga-m21', 'basico', '', 'Perguntas básicas', 'gauss', 1, 'numero', 1, NULL, 'Eliminação de Gauss em A = [2 1 1; 4 3 3; 8 7 9]. Qual é o multiplicador m₂₁?', NULL, '2', 2, NULL, NULL, NULL, NULL, 0, NULL, '{"calc":"gauss-multiplicador","A":[[2,1,1],[4,3,3],[8,7,9]],"i":2,"k":1}', 'm₂₁ = a₂₁/a₁₁ = 4/2 = 2,0000.', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-ga-m21', 'A', '−2', 0, 'O multiplicador é a₂₁/a₁₁ = 2; o sinal de menos fica na operação E₂ ← E₂ − m₂₁E₁.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-ga-m21', 'B', '4', 0, 'Faltou dividir pelo pivô a₁₁ = 2.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-ga-m21', 'C', '2', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-ga-m21', 'D', '0,5', 0, 'Fração invertida: m₂₁ = a₂₁/a₁₁ = 4/2.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('bf-ga-sistema', 'basico', '', 'Perguntas básicas', 'gauss', 1, 'vetor', 1, NULL, 'Resolva por Eliminação de Gauss: 2x₁ + x₂ = 5; x₁ + 3x₂ = 10. Qual é (x₁; x₂)?', NULL, '(1; 3)', NULL, NULL, '[1,3]', NULL, NULL, 0, NULL, '{"calc":"gauss","A":[[2,1],[1,3]],"b":[5,10]}', 'Solução: X* = (1; 3). (5/2)x₂ = 15/2 ⇒ x₂ = 3; 2x₁ + 1·3 = 5 ⇒ x₁ = 1', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-ga-sistema', 'A', '(1; 3)', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-ga-sistema', 'B', '(1; 2)', 0, 'Na etapa 1, E₂ ← E₂ − ½E₁ dá 2,5x₂ = 7,5, logo x₂ = 3.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-ga-sistema', 'C', '(2; 1)', 0, 'Satisfaz só a 1ª equação: 2 + 3·1 = 5 ≠ 10.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-ga-sistema', 'D', '(3; 1)', 0, 'Trocou x₁ e x₂: 2·3 + 1 = 7 ≠ 5.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('bf-ga-regressiva', 'basico', '', 'Perguntas básicas', 'gauss', 1, 'texto', 1, NULL, 'Depois do escalonamento, o sistema triangular superior é resolvido por…', NULL, 'substituição regressiva (da última equação para a primeira)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"A última equação tem uma incógnita só; acha-se xₙ, depois xₙ₋₁, e assim por diante, subindo."}', 'A última equação tem uma incógnita só; acha-se xₙ, depois xₙ₋₁, e assim por diante, subindo.', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-ga-regressiva', 'A', 'mais uma rodada de eliminação', 0, 'A matriz já está triangular; falta só substituir.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-ga-regressiva', 'B', 'regra de Cramer', 0, 'Não é preciso: o sistema triangular sai direto por substituição.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-ga-regressiva', 'C', 'substituição regressiva (da última equação para a primeira)', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-ga-regressiva', 'D', 'substituição progressiva (da primeira para a última)', 0, 'Progressiva é para sistemas triangulares inferiores (como L·y = b).');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('bf-ga-etapas', 'basico', '', 'Perguntas básicas', 'gauss', 1, 'texto', 1, NULL, 'Sem trocas de linhas, quantas etapas de eliminação a Eliminação de Gauss faz num sistema 3×3?', NULL, '2', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"Etapa 1 zera a₂₁ e a₃₁; etapa 2 zera a₃₂. Num sistema n×n são n − 1 etapas."}', 'Etapa 1 zera a₂₁ e a₃₁; etapa 2 zera a₃₂. Num sistema n×n são n − 1 etapas.', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-ga-etapas', 'A', '3', 0, 'A última coluna não precisa de etapa: são n − 1 = 2.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-ga-etapas', 'B', '2', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-ga-etapas', 'C', '6', 0, 'São n − 1 etapas, não n·(n − 1).');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-ga-etapas', 'D', '1', 0, 'Uma etapa só zera a 1ª coluna; ainda falta a₃₂.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('bf-piv-qual', 'basico', '', 'Perguntas básicas', 'pivoteamento', 1, 'texto', 1, NULL, 'No pivoteamento parcial, qual elemento vira pivô na etapa k?', NULL, 'O de maior módulo na coluna k, da linha k para baixo', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"Troca-se a linha k com a que tem o maior |aᵢₖ| (i ≥ k). Assim todos os multiplicadores ficam com |m| ≤ 1."}', 'Troca-se a linha k com a que tem o maior |aᵢₖ| (i ≥ k). Assim todos os multiplicadores ficam com |m| ≤ 1.', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-piv-qual', 'A', 'O de menor módulo na coluna k', 0, 'Pivô pequeno gera multiplicadores grandes e amplia o erro.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-piv-qual', 'B', 'O de maior módulo na linha k', 0, 'O pivoteamento parcial procura na coluna, não na linha.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-piv-qual', 'C', 'O primeiro elemento não nulo da coluna', 0, 'Isso evita só a divisão por zero; o parcial escolhe o maior |aᵢₖ|.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-piv-qual', 'D', 'O de maior módulo na coluna k, da linha k para baixo', 1, NULL);
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('bf-piv-porque', 'basico', '', 'Perguntas básicas', 'pivoteamento', 1, 'texto', 1, NULL, 'Para que serve o pivoteamento parcial?', NULL, 'Evitar pivô nulo e reduzir o erro de arredondamento (|m| ≤ 1)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"Pivô zero impede a divisão; pivô pequeno gera multiplicadores grandes, que ampliam os erros de arredondamento."}', 'Pivô zero impede a divisão; pivô pequeno gera multiplicadores grandes, que ampliam os erros de arredondamento.', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-piv-porque', 'A', 'Deixar a matriz simétrica', 0, 'Trocar linhas não deixa a matriz simétrica.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-piv-porque', 'B', 'Mudar a solução do sistema', 0, 'Trocar equações de lugar não muda a solução.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-piv-porque', 'C', 'Evitar pivô nulo e reduzir o erro de arredondamento (|m| ≤ 1)', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-piv-porque', 'D', 'Diminuir o número de etapas', 0, 'O número de etapas continua n − 1.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('bf-piv-pequeno', 'basico', '', 'Perguntas básicas', 'pivoteamento', 1, 'texto', 1, NULL, 'Sistema 0,0001x₁ + x₂ = 1; x₁ + x₂ = 2, com 3 algarismos significativos e SEM pivoteamento. Qual x₁ sai?', NULL, 'x₁ = 0 (a solução verdadeira é ≈ 1)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"m₂₁ = 10000: a₂₂ vira fl(1 − 10000) = −10000 e b₂ vira fl(2 − 10000) = −10000, então x₂ = 1 e x₁ = (1 − 1)/0,0001 = 0. Trocando as linhas antes (pivô 1), sai x₁ ≈ 1 e x₂ ≈ 1."}', 'm₂₁ = 10000: a₂₂ vira fl(1 − 10000) = −10000 e b₂ vira fl(2 − 10000) = −10000, então x₂ = 1 e x₁ = (1 − 1)/0,0001 = 0. Trocando as linhas antes (pivô 1), sai x₁ ≈ 1 e x₂ ≈ 1.', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-piv-pequeno', 'A', 'x₁ = 0 (a solução verdadeira é ≈ 1)', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-piv-pequeno', 'B', 'x₁ = 10000', 0, '10000 é o multiplicador m₂₁, não x₁.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-piv-pequeno', 'C', 'x₁ ≈ 1, igual à solução verdadeira', 0, 'Esse é o resultado COM pivoteamento.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-piv-pequeno', 'D', 'Divisão por zero', 0, 'O pivô 0,0001 é pequeno, mas não é zero.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('bf-piv-troca', 'basico', '', 'Perguntas básicas', 'pivoteamento', 1, 'texto', 1, NULL, 'Com pivoteamento parcial em A = [1 2 3; 4 5 6; 7 8 10], qual é a primeira troca?', NULL, 'E₁ ↔ E₃ (|7| é o maior da 1ª coluna)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"Na 1ª coluna os candidatos são 1, 4 e 7; o maior em módulo está na 3ª equação."}', 'Na 1ª coluna os candidatos são 1, 4 e 7; o maior em módulo está na 3ª equação.', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-piv-troca', 'A', 'E₁ ↔ E₃ (|7| é o maior da 1ª coluna)', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-piv-troca', 'B', 'Nenhuma: a₁₁ = 1 ≠ 0', 0, 'O parcial troca mesmo com a₁₁ ≠ 0, se houver |aᵢ₁| maior.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-piv-troca', 'C', 'E₂ ↔ E₃', 0, 'A primeira etapa decide o pivô da linha 1.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-piv-troca', 'D', 'E₁ ↔ E₂', 0, '|4| não é o maior da coluna.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('bf-lu-L', 'basico', '', 'Perguntas básicas', 'lu', 1, 'texto', 1, NULL, 'Na fatoração A = L·U (Doolittle), o que fica na matriz L?', NULL, '1 na diagonal e os multiplicadores mᵢⱼ abaixo dela', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"U é a matriz triangular superior que sai da eliminação; L guarda os multiplicadores usados, com 1 na diagonal."}', 'U é a matriz triangular superior que sai da eliminação; L guarda os multiplicadores usados, com 1 na diagonal.', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-lu-L', 'A', 'A inversa de A', 0, 'L não é a inversa; é um fator triangular.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-lu-L', 'B', 'Os pivôs na diagonal', 0, 'Os pivôs ficam na diagonal de U.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-lu-L', 'C', '1 na diagonal e os multiplicadores mᵢⱼ abaixo dela', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-lu-L', 'D', 'A matriz escalonada', 0, 'A escalonada é U.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('bf-lu-resolver', 'basico', '', 'Perguntas básicas', 'lu', 1, 'texto', 1, NULL, 'Com A = L·U, como se resolve A·x = b?', NULL, 'L·y = b (substituição progressiva) e depois U·x = y (regressiva)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"A·x = L·(U·x) = b. Chamando U·x = y: primeiro L·y = b, depois U·x = y."}', 'A·x = L·(U·x) = b. Chamando U·x = y: primeiro L·y = b, depois U·x = y.', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-lu-resolver', 'A', 'U·y = b e depois L·x = y', 0, 'A ordem é ao contrário: A = L·U, então L vem primeiro.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-lu-resolver', 'B', 'Escalonar [A|b] de novo', 0, 'A vantagem da LU é justamente não escalonar de novo.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-lu-resolver', 'C', 'L·y = b (substituição progressiva) e depois U·x = y (regressiva)', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-lu-resolver', 'D', 'x = L·U·b', 0, 'Isso multiplica por A, não resolve o sistema.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('bf-lu-vantagem', 'basico', '', 'Perguntas básicas', 'lu', 1, 'texto', 1, NULL, 'Qual é a vantagem da LU quando é preciso resolver A·x = b para vários vetores b?', NULL, 'A fatoração é feita uma vez só e reaproveitada para cada b', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"Fatorar custa da ordem de n³; cada par de substituições custa da ordem de n². Com muitos b, a economia é grande."}', 'Fatorar custa da ordem de n³; cada par de substituições custa da ordem de n². Com muitos b, a economia é grande.', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-lu-vantagem', 'A', 'Dispensa o pivoteamento', 0, 'A LU também pode precisar de pivoteamento (P·A = L·U).');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-lu-vantagem', 'B', 'A fatoração é feita uma vez só e reaproveitada para cada b', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-lu-vantagem', 'C', 'Dá a resposta exata em ponto flutuante', 0, 'Continua havendo arredondamento.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-lu-vantagem', 'D', 'Funciona para qualquer matriz singular', 0, 'Matriz singular não tem solução única, com ou sem LU.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('bf-lu-u22', 'basico', '', 'Perguntas básicas', 'lu', 1, 'texto', 1, NULL, 'Em A = [2 1; 6 5], qual é u₂₂ na fatoração A = L·U?', NULL, '2', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"m₂₁ = 6/2 = 3, então u₂₂ = 5 − 3·1 = 2. L = [1 0; 3 1] e U = [2 1; 0 2]."}', 'm₂₁ = 6/2 = 3, então u₂₂ = 5 − 3·1 = 2. L = [1 0; 3 1] e U = [2 1; 0 2].', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-lu-u22', 'A', '5', 0, 'Faltou eliminar: u₂₂ = a₂₂ − m₂₁·a₁₂.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-lu-u22', 'B', '−1', 0, 'Usou a₂₁ no lugar de m₂₁: 5 − 3·1 = 2.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-lu-u22', 'C', '2', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-lu-u22', 'D', '3', 0, 'Esse é o multiplicador l₂₁ = m₂₁.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('bf-jac-x1', 'basico', '', 'Perguntas básicas', 'jacobi', 1, 'vetor', 1, NULL, 'Gauss-Jacobi em 4x₁ + x₂ = 9; x₁ + 5x₂ = 11, com X⁽⁰⁾ = (0; 0). Qual é X⁽¹⁾?', NULL, '(2,25; 2,20)', NULL, NULL, '[2.25,2.2]', NULL, NULL, 2, NULL, '{"calc":"jacobi","A":[[4,1],[1,5]],"b":[9,11],"x0":[0,0],"iteracoes":1}', 'Gauss-Jacobi: X⁽1⁾ = (2,25000; 2,20000).
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-jac-x1', 'A', '(2,25; 2,20)', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-jac-x1', 'B', '(9,00; 11,00)', 0, 'Faltou dividir pelo elemento da diagonal.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-jac-x1', 'C', '(2,25; 1,75)', 0, 'Usou o x₁ novo na 2ª equação: isso é Gauss-Seidel.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-jac-x1', 'D', '(0,44; 0,45)', 0, 'Fração invertida: xᵢ = bᵢ/aᵢᵢ com X⁽⁰⁾ = 0.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('bf-jac-formula', 'basico', '', 'Perguntas básicas', 'jacobi', 1, 'texto', 1, NULL, 'No Gauss-Jacobi (3×3), como se calcula x₁⁽ᵏ⁺¹⁾?', NULL, 'x₁⁽ᵏ⁺¹⁾ = (b₁ − a₁₂x₂⁽ᵏ⁾ − a₁₃x₃⁽ᵏ⁾)/a₁₁', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"Isola-se x₁ na 1ª equação e usam-se os valores da iteração anterior (k) para as outras incógnitas."}', 'Isola-se x₁ na 1ª equação e usam-se os valores da iteração anterior (k) para as outras incógnitas.', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-jac-formula', 'A', 'x₁⁽ᵏ⁺¹⁾ = (b₁ + a₁₂x₂⁽ᵏ⁾ + a₁₃x₃⁽ᵏ⁾)/a₁₁', 0, 'Sinais trocados: os outros termos passam para o lado de b subtraindo.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-jac-formula', 'B', 'x₁⁽ᵏ⁺¹⁾ = a₁₁/(b₁ − a₁₂x₂⁽ᵏ⁾ − a₁₃x₃⁽ᵏ⁾)', 0, 'Fração invertida.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-jac-formula', 'C', 'x₁⁽ᵏ⁺¹⁾ = (b₁ − a₁₂x₂⁽ᵏ⁾ − a₁₃x₃⁽ᵏ⁾)/a₁₁', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-jac-formula', 'D', 'x₁⁽ᵏ⁺¹⁾ = b₁ − a₁₂x₂⁽ᵏ⁾ − a₁₃x₃⁽ᵏ⁾', 0, 'Faltou dividir por a₁₁.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('bf-jac-linhas', 'basico', '', 'Perguntas básicas', 'jacobi', 1, 'texto', 1, NULL, 'O critério das linhas garante a convergência do Gauss-Jacobi quando…', NULL, 'αₖ = (Σⱼ≠ₖ |aₖⱼ|)/|aₖₖ| < 1 em todas as linhas', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"Se cada elemento da diagonal é maior, em módulo, que a soma dos outros da linha (diagonal estritamente dominante), Jacobi converge para qualquer X⁽⁰⁾."}', 'Se cada elemento da diagonal é maior, em módulo, que a soma dos outros da linha (diagonal estritamente dominante), Jacobi converge para qualquer X⁽⁰⁾.', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-jac-linhas', 'A', 'A é simétrica', 0, 'Simetria não basta para Jacobi.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-jac-linhas', 'B', 'det(A) > 0', 0, 'Determinante positivo não garante convergência.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-jac-linhas', 'C', 'αₖ < 1 em pelo menos uma linha', 0, 'Precisa valer em todas as linhas (máx αₖ < 1).');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-jac-linhas', 'D', 'αₖ = (Σⱼ≠ₖ |aₖⱼ|)/|aₖₖ| < 1 em todas as linhas', 1, NULL);
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('bf-jac-parada', 'basico', '', 'Perguntas básicas', 'jacobi', 1, 'texto', 1, NULL, 'Que critério de parada os slides usam nos métodos iterativos (Jacobi e Seidel)?', NULL, 'd⁽ᵏ⁾ = máx|xᵢ⁽ᵏ⁾ − xᵢ⁽ᵏ⁻¹⁾| / máx|xᵢ⁽ᵏ⁾| < ε', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"É o erro relativo entre duas iterações: a maior diferença entre componentes, dividida pela maior componente (em módulo) da iteração nova."}', 'É o erro relativo entre duas iterações: a maior diferença entre componentes, dividida pela maior componente (em módulo) da iteração nova.', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-jac-parada', 'A', 'Parar quando o determinante é menor que ε', 0, 'O determinante não muda entre iterações.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-jac-parada', 'B', 'd⁽ᵏ⁾ = máx|xᵢ⁽ᵏ⁾ − xᵢ⁽ᵏ⁻¹⁾| / máx|xᵢ⁽ᵏ⁾| < ε', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-jac-parada', 'C', 'Parar quando x⁽ᵏ⁾ = 0', 0, 'A solução não precisa ser zero.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-jac-parada', 'D', 'Parar depois de exatamente 3 iterações', 0, 'Número fixo de iterações só quando o enunciado pede.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('bf-sei-x1', 'basico', '', 'Perguntas básicas', 'seidel', 1, 'vetor', 1, NULL, 'Gauss-Seidel em 4x₁ + x₂ = 9; x₁ + 5x₂ = 11, com X⁽⁰⁾ = (0; 0). Qual é X⁽¹⁾?', NULL, '(2,25; 1,75)', NULL, NULL, '[2.25,1.75]', NULL, NULL, 2, NULL, '{"calc":"seidel","A":[[4,1],[1,5]],"b":[9,11],"x0":[0,0],"iteracoes":1}', 'Gauss-Seidel: X⁽1⁾ = (2,25000; 1,75000).
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-sei-x1', 'A', '(2,25; 1,75)', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-sei-x1', 'B', '(9,00; 2,00)', 0, 'Faltou dividir a 1ª equação por a₁₁ = 4.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-sei-x1', 'C', '(2,25; 2,20)', 0, 'Usou x₁⁽⁰⁾ = 0 na 2ª equação: isso é Gauss-Jacobi.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-sei-x1', 'D', '(2,25; 2,65)', 0, 'Sinal trocado: x₂ = (11 − 1·2,25)/5, não (11 + 2,25)/5.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('bf-sei-diferenca', 'basico', '', 'Perguntas básicas', 'seidel', 1, 'texto', 1, NULL, 'O que o Gauss-Seidel faz de diferente do Gauss-Jacobi?', NULL, 'Usa, na mesma iteração, os valores que acabou de calcular', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"Para x₂⁽ᵏ⁺¹⁾ o Seidel já usa x₁⁽ᵏ⁺¹⁾; o Jacobi espera a iteração seguinte. Por isso o Seidel costuma convergir mais rápido."}', 'Para x₂⁽ᵏ⁺¹⁾ o Seidel já usa x₁⁽ᵏ⁺¹⁾; o Jacobi espera a iteração seguinte. Por isso o Seidel costuma convergir mais rápido.', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-sei-diferenca', 'A', 'Não precisa de chute inicial', 0, 'Os dois precisam de X⁽⁰⁾.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-sei-diferenca', 'B', 'Escalona a matriz antes', 0, 'Os dois são iterativos; nenhum escalona.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-sei-diferenca', 'C', 'Usa só os valores da iteração anterior', 0, 'Esse é o Jacobi.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-sei-diferenca', 'D', 'Usa, na mesma iteração, os valores que acabou de calcular', 1, NULL);
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('bf-sei-beta', 'basico', '', 'Perguntas básicas', 'criterios', 1, 'numero', 1, NULL, 'Critério de Sassenfeld em A = [4 1; 1 5]: qual é β₂?', NULL, '0,05', 0.05, NULL, NULL, NULL, NULL, 2, NULL, '{"calc":"sassenfeld","A":[[4,1],[1,5]],"indice":2}', 'β₂ = 0,0500 (β = (0,2500; 0,0500)).', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-sei-beta', 'A', '0,25', 0, 'Esse é β₁ = 1/4.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-sei-beta', 'B', '1,25', 0, 'Somou β₁ em vez de multiplicar: β₂ = |a₂₁|·β₁/|a₂₂|.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-sei-beta', 'C', '0,05', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-sei-beta', 'D', '0,20', 0, 'Esse é o α₂ do critério das linhas: no Sassenfeld, |a₂₁| é multiplicado por β₁ = 0,25.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('bf-sei-garante', 'basico', '', 'Perguntas básicas', 'criterios', 1, 'texto', 1, NULL, 'Se o critério de Sassenfeld dá β = máx βᵢ < 1, então…', NULL, 'o Gauss-Seidel converge para qualquer X⁽⁰⁾', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"β < 1 é condição suficiente de convergência do Gauss-Seidel. Se β ≥ 1, o critério não garante nada (pode convergir ou não)."}', 'β < 1 é condição suficiente de convergência do Gauss-Seidel. Se β ≥ 1, o critério não garante nada (pode convergir ou não).', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-sei-garante', 'A', 'a solução é β', 0, 'β mede a contração, não é a solução.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-sei-garante', 'B', 'o Gauss-Seidel diverge', 0, 'β < 1 garante convergência, não divergência.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-sei-garante', 'C', 'o Gauss-Seidel converge para qualquer X⁽⁰⁾', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-sei-garante', 'D', 'só o Jacobi converge', 0, 'Sassenfeld é o critério do Gauss-Seidel.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('bf-lag-linear', 'basico', '', 'Perguntas básicas', 'interpolacao', 1, 'numero', 1, NULL, 'Interpolação linear pelos pontos (1; 2) e (3; 8). Qual é p(2)?', NULL, '5,00', 5, NULL, NULL, NULL, NULL, 2, NULL, '{"calc":"interp-linear","xs":[1,3],"ys":[2,8],"x":2}', 'Entre os dois pontos vizinhos de x = 2: p₁(x) = y₀ + (y₁ − y₀)(x − x₀)/(x₁ − x₀) = 5,0000.', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-lag-linear', 'A', '2,00', 0, 'Esse é y₀; falta somar o acréscimo 3.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-lag-linear', 'B', '8,00', 0, 'Faltou dividir por x₁ − x₀ = 2: o acréscimo é 6·(2 − 1)/2 = 3.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-lag-linear', 'C', '5,00', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-lag-linear', 'D', '3,00', 0, 'Esse é só o acréscimo (8 − 2)·(2 − 1)/(3 − 1) = 3; falta somar y₀ = 2.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('bf-lag-base', 'basico', '', 'Perguntas básicas', 'interpolacao', 1, 'texto', 1, NULL, 'Na forma de Lagrange com nós x₀, x₁, x₂, quanto valem L₀(x₀) e L₀(x₁)?', NULL, 'L₀(x₀) = 1 e L₀(x₁) = 0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"Cada Lₖ vale 1 no seu nó e 0 nos outros. Assim p(xₖ) = Σ yᵢLᵢ(xₖ) = yₖ."}', 'Cada Lₖ vale 1 no seu nó e 0 nos outros. Assim p(xₖ) = Σ yᵢLᵢ(xₖ) = yₖ.', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-lag-base', 'A', 'Os dois valem 1', 0, 'Se L₀(x₁) = 1, p(x₁) não daria y₁.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-lag-base', 'B', 'L₀(x₀) = y₀', 0, 'O y₀ multiplica L₀; L₀ sozinho vale 1 em x₀.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-lag-base', 'C', 'L₀(x₀) = 0 e L₀(x₁) = 1', 0, 'Invertido: L₀ vale 1 no próprio nó x₀.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-lag-base', 'D', 'L₀(x₀) = 1 e L₀(x₁) = 0', 1, NULL);
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('bf-lag-calc', 'basico', '', 'Perguntas básicas', 'interpolacao', 1, 'texto', 1, NULL, 'Pontos (0; 1), (1; 3) e (2; 2). Qual é p₂(0,5) pelo polinômio de Lagrange?', NULL, '2,375', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"L₀(0,5) = 0,375; L₁(0,5) = 0,75; L₂(0,5) = −0,125. p₂(0,5) = 1·0,375 + 3·0,75 + 2·(−0,125) = 2,375."}', 'L₀(0,5) = 0,375; L₁(0,5) = 0,75; L₂(0,5) = −0,125. p₂(0,5) = 1·0,375 + 3·0,75 + 2·(−0,125) = 2,375.', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-lag-calc', 'A', '2,000', 0, 'Isso é a interpolação linear entre (0; 1) e (1; 3), sem o 3º ponto.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-lag-calc', 'B', '2,500', 0, 'Confira L₂(0,5) = (0,5 − 0)(0,5 − 1)/((2 − 0)(2 − 1)) = −0,125.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-lag-calc', 'C', '2,375', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-lag-calc', 'D', '1,875', 0, 'Sinal de L₂ trocado ou peso errado em L₁ = 0,75.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('bf-lag-grau', 'basico', '', 'Perguntas básicas', 'interpolacao', 1, 'texto', 1, NULL, 'Por 4 pontos com abscissas distintas passa um único polinômio interpolador. De que grau?', NULL, 'No máximo 3', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"n + 1 pontos distintos determinam um único polinômio de grau ≤ n. Com 4 pontos, grau ≤ 3."}', 'n + 1 pontos distintos determinam um único polinômio de grau ≤ n. Com 4 pontos, grau ≤ 3.', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-lag-grau', 'A', 'Qualquer grau', 0, 'Grau ≤ 3 é único; grau maior tem infinitas opções.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-lag-grau', 'B', 'Exatamente 4', 0, 'Seriam 5 coeficientes para 4 condições: não fica único.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-lag-grau', 'C', 'No máximo 3', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-lag-grau', 'D', 'No máximo 2', 0, 'Uma parábola não passa, em geral, por 4 pontos quaisquer.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('bf-spl-trecho', 'basico', '', 'Perguntas básicas', 'spline', 1, 'texto', 1, NULL, 'Numa spline cúbica, cada trecho [xᵢ; xᵢ₊₁] é…', NULL, 'um polinômio de grau 3, com S, S′ e S″ contínuas nos nós internos', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"A spline cola cúbicas trecho a trecho e exige que valor, inclinação e curvatura combinem nos nós."}', 'A spline cola cúbicas trecho a trecho e exige que valor, inclinação e curvatura combinem nos nós.', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-spl-trecho', 'A', 'um polinômio de grau 3, com S, S′ e S″ contínuas nos nós internos', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-spl-trecho', 'B', 'uma reta ligando os pontos', 0, 'Isso é a spline linear (interpolação por partes de grau 1).');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-spl-trecho', 'C', 'uma cúbica que só precisa passar pelos pontos', 0, 'Também exige continuidade de S′ e S″.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-spl-trecho', 'D', 'o mesmo polinômio em todos os trechos', 0, 'Um único polinômio em tudo é a interpolação polinomial comum.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('bf-spl-porque', 'basico', '', 'Perguntas básicas', 'spline', 1, 'texto', 1, NULL, 'Por que usar spline cúbica em vez de um polinômio de grau alto por muitos pontos?', NULL, 'Evita as oscilações nas pontas (fenômeno de Runge)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"Com nós igualmente espaçados, polinômios de grau alto oscilam muito perto das extremidades. A spline usa grau 3 em cada trecho e fica suave."}', 'Com nós igualmente espaçados, polinômios de grau alto oscilam muito perto das extremidades. A spline usa grau 3 em cada trecho e fica suave.', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-spl-porque', 'A', 'Evita as oscilações nas pontas (fenômeno de Runge)', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-spl-porque', 'B', 'Porque não precisa resolver sistema', 0, 'A spline cúbica resolve um sistema (tridiagonal) para as curvaturas.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-spl-porque', 'C', 'Porque é um polinômio só', 0, 'É o contrário: são vários polinômios, um por trecho.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-spl-porque', 'D', 'Porque passa por menos pontos', 0, 'A spline também passa por todos os pontos.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('bf-spl-natural', 'basico', '', 'Perguntas básicas', 'spline', 1, 'texto', 1, NULL, 'O que a spline cúbica NATURAL impõe nas extremidades?', NULL, 'S″(x₀) = 0 e S″(xₙ) = 0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"Faltam duas condições para fechar o sistema; a natural zera a curvatura nas pontas (a \"régua\" fica reta lá)."}', 'Faltam duas condições para fechar o sistema; a natural zera a curvatura nas pontas (a "régua" fica reta lá).', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-spl-natural', 'A', 'S(x₀) = 0 e S(xₙ) = 0', 0, 'S nas pontas tem que valer y₀ e yₙ.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-spl-natural', 'B', 'S′(x₀) = 0 e S′(xₙ) = 0', 0, 'Zerar a inclinação é outra condição (e não é a natural).');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-spl-natural', 'C', 'S″(x₀) = 0 e S″(xₙ) = 0', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-spl-natural', 'D', 'Nenhuma condição', 0, 'Sem duas condições extras o sistema não tem solução única.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('bf-spl-sistema', 'basico', '', 'Perguntas básicas', 'spline', 1, 'texto', 1, NULL, 'O sistema que dá as curvaturas Mᵢ da spline cúbica tem matriz…', NULL, 'tridiagonal', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"Cada equação liga só Mᵢ₋₁, Mᵢ e Mᵢ₊₁: a matriz tem três diagonais não nulas e resolve-se rápido."}', 'Cada equação liga só Mᵢ₋₁, Mᵢ e Mᵢ₊₁: a matriz tem três diagonais não nulas e resolve-se rápido.', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-spl-sistema', 'A', 'triangular superior', 0, 'Há elementos abaixo da diagonal (os vizinhos à esquerda).');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-spl-sistema', 'B', 'tridiagonal', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-spl-sistema', 'C', 'diagonal', 0, 'Os nós vizinhos aparecem em cada equação.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-spl-sistema', 'D', 'cheia (todos os elementos não nulos)', 0, 'Cada nó só "conversa" com os vizinhos.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('bf-mmq-b', 'basico', '', 'Perguntas básicas', 'minimos-quadrados', 1, 'texto', 1, NULL, 'Reta y = a + bx por mínimos quadrados nos pontos (0; 1), (1; 2) e (2; 4). Qual é a inclinação b?', NULL, '1,5', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"x̄ = 1 e ȳ = 7/3. b = Σ(xᵢ − x̄)(yᵢ − ȳ) / Σ(xᵢ − x̄)² = 3/2 = 1,5; a = ȳ − b·x̄ ≈ 0,8333."}', 'x̄ = 1 e ȳ = 7/3. b = Σ(xᵢ − x̄)(yᵢ − ȳ) / Σ(xᵢ − x̄)² = 3/2 = 1,5; a = ȳ − b·x̄ ≈ 0,8333.', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-mmq-b', 'A', '1,0', 0, 'Essa é a inclinação só entre os dois primeiros pontos.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-mmq-b', 'B', '2,0', 0, 'Essa é a inclinação só entre os dois últimos pontos.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-mmq-b', 'C', '0,8333', 0, 'Esse é o coeficiente linear a.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-mmq-b', 'D', '1,5', 1, NULL);
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('bf-mmq-normais', 'basico', '', 'Perguntas básicas', 'minimos-quadrados', 1, 'texto', 1, NULL, 'Quais são as equações normais da reta y = a + bx (n pontos)?', NULL, 'n·a + b·Σx = Σy e a·Σx + b·Σx² = Σxy', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"Derivando Σ(yᵢ − a − bxᵢ)² em relação a a e a b e igualando a zero saem essas duas equações."}', 'Derivando Σ(yᵢ − a − bxᵢ)² em relação a a e a b e igualando a zero saem essas duas equações.', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-mmq-normais', 'A', 'n·a + b·Σx = Σy e a·Σx + b·Σx² = Σxy', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-mmq-normais', 'B', 'a + b·Σx = Σy e a·Σx + b·Σx = Σxy', 0, 'Falta o n no 1º termo e Σx² no 2º.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-mmq-normais', 'C', 'n·a = Σy e b·Σx² = Σxy', 0, 'Faltam os termos cruzados com Σx.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-mmq-normais', 'D', 'a·Σx² + b·Σx = Σy', 0, 'Falta a segunda equação e os índices estão trocados.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('bf-mmq-vs-interp', 'basico', '', 'Perguntas básicas', 'minimos-quadrados', 1, 'texto', 1, NULL, 'Qual é a diferença entre ajustar (mínimos quadrados) e interpolar?', NULL, 'O ajuste não precisa passar pelos pontos: minimiza a soma dos quadrados dos desvios', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"Interpolar obriga a curva a passar por todos os pontos. Com dados medidos (com ruído), o ajuste por uma curva simples é mais adequado."}', 'Interpolar obriga a curva a passar por todos os pontos. Com dados medidos (com ruído), o ajuste por uma curva simples é mais adequado.', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-mmq-vs-interp', 'A', 'O ajuste passa exatamente por todos os pontos', 0, 'Isso é interpolação.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-mmq-vs-interp', 'B', 'Não há diferença', 0, 'São problemas diferentes.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-mmq-vs-interp', 'C', 'A interpolação usa só retas', 0, 'A interpolação pode usar polinômios de qualquer grau.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-mmq-vs-interp', 'D', 'O ajuste não precisa passar pelos pontos: minimiza a soma dos quadrados dos desvios', 1, NULL);
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('bf-mmq-potencia', 'basico', '', 'Perguntas básicas', 'minimos-quadrados', 1, 'texto', 1, NULL, 'Para ajustar y = a·xᵇ por mínimos quadrados, que transformação deixa o problema linear?', NULL, 'ln y = ln a + b·ln x: reta nos pontos (ln xᵢ; ln yᵢ)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"Aplicando ln dos dois lados, a potência vira reta em ln x. Ajusta-se a reta e depois a = e^(coeficiente linear)."}', 'Aplicando ln dos dois lados, a potência vira reta em ln x. Ajusta-se a reta e depois a = e^(coeficiente linear).', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-mmq-potencia', 'A', 'ln y = ln a + b·ln x: reta nos pontos (ln xᵢ; ln yᵢ)', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-mmq-potencia', 'B', 'y = a + b·x direto', 0, 'A potência não é uma reta em x.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-mmq-potencia', 'C', 'ln y = ln a + b·x: reta nos pontos (xᵢ; ln yᵢ)', 0, 'Essa é a linearização da exponencial a·eᵇˣ.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-mmq-potencia', 'D', '√y = a + b·x', 0, 'A raiz não lineariza a potência.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('bf-trap-n2', 'basico', '', 'Perguntas básicas', 'trapezios', 1, 'numero', 1, NULL, 'Regra dos trapézios repetida com n = 2 para ∫₀² x² dx. Qual é o valor?', NULL, '3,0000', 3, NULL, NULL, NULL, NULL, 4, NULL, '{"calc":"integral","regra":"trapezios","f":"x^2","a":0,"b":2,"n":2}', 'regra dos trapézios com n = 2: I ≈ 3,00000.', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-trap-n2', 'A', '2,6667', 0, 'Esse é o valor exato (8/3), que a Simpson 1/3 acerta.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-trap-n2', 'B', '4,0000', 0, 'Esse é o trapézio simples (n = 1).');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-trap-n2', 'C', '6,0000', 0, 'Faltou o fator h/2: (1/2)·(0 + 2·1 + 4) = 3.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-trap-n2', 'D', '3,0000', 1, NULL);
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('bf-trap-erro', 'basico', '', 'Perguntas básicas', 'trapezios', 1, 'texto', 1, NULL, 'O erro da regra dos trapézios repetida é proporcional a…', NULL, 'h² (dividir h por 2 divide o erro por cerca de 4)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"E ≈ −(b − a)·h²·f″(ξ)/12: o erro é de ordem h²."}', 'E ≈ −(b − a)·h²·f″(ξ)/12: o erro é de ordem h².', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-trap-erro', 'A', 'h⁴', 0, 'h⁴ é a ordem das regras de Simpson.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-trap-erro', 'B', 'h² (dividir h por 2 divide o erro por cerca de 4)', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-trap-erro', 'C', 'h (dividir h por 2 divide o erro por 2)', 0, 'O trapézio é de ordem 2, não 1.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-trap-erro', 'D', 'não depende de h', 0, 'Diminuir h diminui o erro.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('bf-trap-concava', 'basico', '', 'Perguntas básicas', 'trapezios', 1, 'texto', 1, NULL, 'Se f″ > 0 em [a, b] (gráfico com concavidade para cima), a regra dos trapézios…', NULL, 'superestima a integral', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"As cordas ficam acima da curva, então a área dos trapézios é maior que a área sob f."}', 'As cordas ficam acima da curva, então a área dos trapézios é maior que a área sob f.', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-trap-concava', 'A', 'superestima a integral', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-trap-concava', 'B', 'é exata', 0, 'Só é exata para retas (f″ = 0).');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-trap-concava', 'C', 'não dá para saber', 0, 'O sinal de f″ diz se as cordas ficam acima ou abaixo.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-trap-concava', 'D', 'subestima a integral', 0, 'Subestima quando f″ < 0 (concavidade para baixo).');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('bf-trap-pontos', 'basico', '', 'Perguntas básicas', 'trapezios', 1, 'texto', 1, NULL, 'Quantos pontos (nós) a regra dos trapézios repetida usa com n subintervalos?', NULL, 'n + 1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"n subintervalos de largura h = (b − a)/n têm n + 1 extremidades: x₀, x₁, …, xₙ."}', 'n subintervalos de largura h = (b − a)/n têm n + 1 extremidades: x₀, x₁, …, xₙ.', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-trap-pontos', 'A', 'n − 1', 0, 'Esses são só os pontos internos.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-trap-pontos', 'B', '2n', 0, 'Os pontos internos são compartilhados por dois trapézios.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-trap-pontos', 'C', 'n + 1', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-trap-pontos', 'D', 'n', 0, 'Faltou contar uma das extremidades.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('bf-s13-n2', 'basico', '', 'Perguntas básicas', 'simpson13', 1, 'numero', 1, NULL, 'Regra de Simpson 1/3 com n = 2 para ∫₀² x² dx. Qual é o valor?', NULL, '2,6667', 2.66666666667, NULL, NULL, NULL, NULL, 4, NULL, '{"calc":"integral","regra":"simpson13","f":"x^2","a":0,"b":2,"n":2}', 'regra de Simpson (1/3) com n = 2: I ≈ 2,66667.', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-s13-n2', 'A', '3,0000', 0, 'Esse é o trapézio repetido com n = 2.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-s13-n2', 'B', '8,0000', 0, 'Faltou o fator h/3: (1/3)·(0 + 4·1 + 4).');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-s13-n2', 'C', '4,0000', 0, 'Esse é o trapézio simples.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-s13-n2', 'D', '2,6667', 1, NULL);
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('bf-s13-cubica', 'basico', '', 'Perguntas básicas', 'simpson13', 1, 'texto', 1, NULL, 'Por que a Simpson 1/3 é exata para polinômios de grau até 3?', NULL, 'O erro depende de f⁽⁴⁾, que é zero para cúbicas', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"E = −(b − a)·h⁴·f⁽⁴⁾(ξ)/180. Para grau ≤ 3, f⁽⁴⁾ = 0 e o erro some."}', 'E = −(b − a)·h⁴·f⁽⁴⁾(ξ)/180. Para grau ≤ 3, f⁽⁴⁾ = 0 e o erro some.', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-s13-cubica', 'A', 'Porque usa cúbicas para aproximar f', 0, 'A 1/3 usa parábolas; a exatidão em cúbicas é um "bônus" da simetria.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-s13-cubica', 'B', 'Porque o erro depende de f″', 0, 'O erro que depende de f″ é o do trapézio.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-s13-cubica', 'C', 'O erro depende de f⁽⁴⁾, que é zero para cúbicas', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-s13-cubica', 'D', 'Não é exata para cúbicas', 0, 'É exata até grau 3.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('bf-s13-formula', 'basico', '', 'Perguntas básicas', 'simpson13', 1, 'texto', 1, NULL, 'Qual é a Simpson 1/3 repetida (n par)?', NULL, '(h/3)·[f₀ + 4(f₁ + f₃ + …) + 2(f₂ + f₄ + …) + fₙ]', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"Pesos 1, 4, 2, 4, …, 2, 4, 1: ímpares com 4, pares internos com 2."}', 'Pesos 1, 4, 2, 4, …, 2, 4, 1: ímpares com 4, pares internos com 2.', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-s13-formula', 'A', '(h/2)·[f₀ + 2(f₁ + … + fₙ₋₁) + fₙ]', 0, 'Essa é a regra dos trapézios.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-s13-formula', 'B', '(h/3)·[f₀ + 2(f₁ + f₃ + …) + 4(f₂ + f₄ + …) + fₙ]', 0, 'Pesos trocados: os ímpares levam 4.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-s13-formula', 'C', '(3h/8)·[f₀ + 3f₁ + 3f₂ + f₃]', 0, 'Essa é a Simpson 3/8.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-s13-formula', 'D', '(h/3)·[f₀ + 4(f₁ + f₃ + …) + 2(f₂ + f₄ + …) + fₙ]', 1, NULL);
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('bf-s13-ordem', 'basico', '', 'Perguntas básicas', 'simpson13', 1, 'texto', 1, NULL, 'Ao dividir h por 2 na Simpson 1/3 repetida, o erro fica dividido por cerca de…', NULL, '16', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"O erro é de ordem h⁴: (1/2)⁴ = 1/16."}', 'O erro é de ordem h⁴: (1/2)⁴ = 1/16.', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-s13-ordem', 'A', '2', 0, 'Seria um método de ordem 1.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-s13-ordem', 'B', '8', 0, 'Seria ordem h³.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-s13-ordem', 'C', '16', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-s13-ordem', 'D', '4', 0, 'Esse é o caso do trapézio (ordem h²).');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('bf-s38-n3', 'basico', '', 'Perguntas básicas', 'simpson38', 1, 'numero', 1, NULL, 'Regra de Simpson 3/8 com n = 3 para ∫₀³ x² dx. Qual é o valor?', NULL, '9,0000', 9, NULL, NULL, NULL, NULL, 4, NULL, '{"calc":"integral","regra":"simpson38","f":"x^2","a":0,"b":3,"n":3}', 'regra de Simpson 3/8 com n = 3: I ≈ 9,00000.', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-s38-n3', 'A', '5,2500', 0, 'Faltaram os pesos 3 nos pontos internos.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-s38-n3', 'B', '24,0000', 0, 'Faltou o fator 3h/8.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-s38-n3', 'C', '9,5000', 0, 'Esse é o trapézio repetido com n = 3.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-s38-n3', 'D', '9,0000', 1, NULL);
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('bf-s38-formula', 'basico', '', 'Perguntas básicas', 'simpson38', 1, 'texto', 1, NULL, 'Qual é a Simpson 3/8 simples (3 subintervalos)?', NULL, '(3h/8)·[f₀ + 3f₁ + 3f₂ + f₃]', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"Integra a cúbica que passa pelos quatro pontos x₀, x₁, x₂, x₃."}', 'Integra a cúbica que passa pelos quatro pontos x₀, x₁, x₂, x₃.', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-s38-formula', 'A', '(h/8)·[f₀ + 3f₁ + 3f₂ + f₃]', 0, 'O fator é 3h/8.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-s38-formula', 'B', '(h/3)·[f₀ + 4f₁ + f₂]', 0, 'Essa é a Simpson 1/3 simples.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-s38-formula', 'C', '(3h/8)·[f₀ + 2f₁ + 2f₂ + f₃]', 0, 'Os pontos internos levam peso 3.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-s38-formula', 'D', '(3h/8)·[f₀ + 3f₁ + 3f₂ + f₃]', 1, NULL);
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('bf-s38-combina', 'basico', '', 'Perguntas básicas', 'simpson38', 1, 'texto', 1, NULL, 'Com n = 5 subintervalos (ímpar), como usar as regras de Simpson?', NULL, 'Simpson 1/3 em 2 subintervalos e 3/8 nos outros 3', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"A 1/3 precisa de número par e a 3/8 de múltiplo de 3: 5 = 2 + 3."}', 'A 1/3 precisa de número par e a 3/8 de múltiplo de 3: 5 = 2 + 3.', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-s38-combina', 'A', 'Não dá para usar Simpson', 0, 'Dá: combinando as duas.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-s38-combina', 'B', 'Simpson 3/8 nos 5', 0, 'A 3/8 exige múltiplo de 3.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-s38-combina', 'C', 'Simpson 1/3 nos 5', 0, 'A 1/3 exige n par.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-s38-combina', 'D', 'Simpson 1/3 em 2 subintervalos e 3/8 nos outros 3', 1, NULL);
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('bf-s38-ordem', 'basico', '', 'Perguntas básicas', 'simpson38', 1, 'texto', 1, NULL, 'A Simpson 3/8 e a Simpson 1/3 têm a mesma ordem de erro?', NULL, 'Sim: as duas são de ordem h⁴ e exatas para cúbicas', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"A 3/8 tem constante de erro um pouco maior, mas a mesma ordem. A vantagem dela é aceitar n múltiplo de 3."}', 'A 3/8 tem constante de erro um pouco maior, mas a mesma ordem. A vantagem dela é aceitar n múltiplo de 3.', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-s38-ordem', 'A', 'Não: só a 1/3 é exata para cúbicas', 0, 'A 3/8 também é exata até grau 3.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-s38-ordem', 'B', 'Não: a 3/8 é de ordem h²', 0, 'h² é o trapézio.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-s38-ordem', 'C', 'Sim: as duas são de ordem h⁴ e exatas para cúbicas', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-s38-ordem', 'D', 'Não: a 3/8 é de ordem h⁸', 0, 'As duas são de ordem h⁴.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('bf-eul-y1', 'basico', '', 'Perguntas básicas', 'euler', 1, 'numero', 1, NULL, 'Euler em y′ = y, y(0) = 1, com h = 0,1. Qual é y₁ ≈ y(0,1)?', NULL, '1,1000', 1.1, NULL, NULL, NULL, NULL, 4, NULL, '{"calc":"euler","f":"y","x0":0,"y0":1,"h":0.1,"xf":0.1}', 'Euler: yₖ₊₁ = yₖ + h·f(xₖ, yₖ), h = 0,1, 1 passos: y(0,1) ≈ 1,10000.', NULL, 0, 'verde', 1);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-eul-y1', 'A', '0,1000', 0, 'Isso é só o acréscimo h·f; falta somar y₀.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-eul-y1', 'B', '1,0000', 0, 'Esse é y₀; falta somar h·f(x₀, y₀).');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-eul-y1', 'C', '1,1052', 0, 'Esse é o valor exato e^0,1; Euler dá 1 + 0,1·1.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-eul-y1', 'D', '1,1000', 1, NULL);
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('bf-eul-ordem', 'basico', '', 'Perguntas básicas', 'euler', 1, 'texto', 1, NULL, 'Qual é a ordem do método de Euler?', NULL, '1ª ordem: o erro global é proporcional a h', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"Euler corta a série de Taylor no termo de 1ª ordem: erro local O(h²), erro global O(h)."}', 'Euler corta a série de Taylor no termo de 1ª ordem: erro local O(h²), erro global O(h).', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-eul-ordem', 'A', '1ª ordem: o erro global é proporcional a h', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-eul-ordem', 'B', '4ª ordem', 0, '4ª ordem é o RK4.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-eul-ordem', 'C', 'O erro não depende de h', 0, 'Diminuir h diminui o erro.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-eul-ordem', 'D', '2ª ordem', 0, 'Essa é a ordem de Taylor de 2ª ordem (e de Heun).');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('bf-eul-instavel', 'basico', '', 'Perguntas básicas', 'euler', 1, 'texto', 1, NULL, 'Euler em y′ = −50y com h = 0,05. O que acontece com a solução numérica?', NULL, 'Oscila com amplitude crescente: |1 − 50h| = 1,5 > 1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"yₖ₊₁ = (1 − 50h)·yₖ = −1,5·yₖ. A solução exata decai, mas a numérica troca de sinal e cresce: o passo é grande demais (instabilidade)."}', 'yₖ₊₁ = (1 − 50h)·yₖ = −1,5·yₖ. A solução exata decai, mas a numérica troca de sinal e cresce: o passo é grande demais (instabilidade).', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-eul-instavel', 'A', 'Decai suavemente, como a exata', 0, 'Para isso precisaria |1 − 50h| < 1, ou seja, h < 0,04.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-eul-instavel', 'B', 'Dá exatamente e^(−50x)', 0, 'Euler não é exato; aqui nem é estável.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-eul-instavel', 'C', 'Oscila com amplitude crescente: |1 − 50h| = 1,5 > 1', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-eul-instavel', 'D', 'Fica constante', 0, 'O fator −1,5 muda yₖ a cada passo.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('bf-eul-geometria', 'basico', '', 'Perguntas básicas', 'euler', 1, 'texto', 1, NULL, 'Geometricamente, um passo do método de Euler…', NULL, 'segue a reta tangente à solução em (xₖ, yₖ) por um passo h', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"A inclinação em (xₖ, yₖ) é f(xₖ, yₖ); Euler anda h nessa direção: yₖ₊₁ = yₖ + h·f(xₖ, yₖ)."}', 'A inclinação em (xₖ, yₖ) é f(xₖ, yₖ); Euler anda h nessa direção: yₖ₊₁ = yₖ + h·f(xₖ, yₖ).', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-eul-geometria', 'A', 'segue a reta tangente à solução em (xₖ, yₖ) por um passo h', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-eul-geometria', 'B', 'segue a corda entre (xₖ, yₖ) e (xₖ₊₁, yₖ₊₁)', 0, 'Euler não conhece yₖ₊₁ de antemão: usa a tangente.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-eul-geometria', 'C', 'interpola uma parábola', 0, 'Euler usa só a reta tangente.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-eul-geometria', 'D', 'faz a média de quatro inclinações', 0, 'Isso é o RK4.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('bf-rk4-avaliacoes', 'basico', '', 'Perguntas básicas', 'runge-kutta', 1, 'texto', 1, NULL, 'Quantas avaliações de f o RK4 faz por passo?', NULL, '4 (k₁, k₂, k₃ e k₄)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"k₁ no início, k₂ e k₃ no meio do passo e k₄ no fim."}', 'k₁ no início, k₂ e k₃ no meio do passo e k₄ no fim.', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-rk4-avaliacoes', 'A', '4 (k₁, k₂, k₃ e k₄)', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-rk4-avaliacoes', 'B', '8', 0, 'O RK4 clássico usa 4.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-rk4-avaliacoes', 'C', '2', 0, '2 avaliações é Heun (ou ponto médio), de 2ª ordem.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-rk4-avaliacoes', 'D', '1', 0, '1 avaliação por passo é o Euler.');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('bf-rk4-media', 'basico', '', 'Perguntas básicas', 'runge-kutta', 1, 'texto', 1, NULL, 'Como o RK4 combina as inclinações k₁, k₂, k₃ e k₄?', NULL, 'yₖ₊₁ = yₖ + (h/6)(k₁ + 2k₂ + 2k₃ + k₄)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"É uma média ponderada: as inclinações do meio do passo pesam o dobro (como na Simpson 1/3)."}', 'É uma média ponderada: as inclinações do meio do passo pesam o dobro (como na Simpson 1/3).', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-rk4-media', 'A', 'yₖ₊₁ = yₖ + h·k₁', 0, 'Isso é Euler.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-rk4-media', 'B', 'yₖ₊₁ = yₖ + (h/4)(k₁ + k₂ + k₃ + k₄)', 0, 'Pesos iguais: o RK4 dá peso 2 a k₂ e k₃.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-rk4-media', 'C', 'yₖ₊₁ = yₖ + (h/6)(k₁ + 2k₂ + 2k₃ + k₄)', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-rk4-media', 'D', 'yₖ₊₁ = yₖ + (h/6)(2k₁ + k₂ + k₃ + 2k₄)', 0, 'Os pesos 2 ficam no meio (k₂ e k₃).');
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('bf-rk4-ordem', 'basico', '', 'Perguntas básicas', 'runge-kutta', 1, 'texto', 1, NULL, 'Qual é a ordem do erro global do RK4?', NULL, 'h⁴', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"Dividir h por 2 divide o erro por cerca de 16. Por isso o RK4 é tão usado."}', 'Dividir h por 2 divide o erro por cerca de 16. Por isso o RK4 é tão usado.', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-rk4-ordem', 'A', 'h', 0, 'Ordem 1 é Euler.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-rk4-ordem', 'B', 'h⁸', 0, 'O RK4 clássico é de 4ª ordem.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-rk4-ordem', 'C', 'h²', 0, 'Ordem 2 é Heun ou Taylor de 2ª ordem.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-rk4-ordem', 'D', 'h⁴', 1, NULL);
INSERT INTO questoes (id, lista_id, numero, secao, tema_id, dificuldade, tipo, rapida, origem_id, enunciado, gabarito_lista, resposta, valor, valor_lista, vetor, vetor_lista, matriz, casas, tolerancia, parametros, resolucao, observacao, diverge, casa, iteracoes) VALUES ('bf-rk4-k2', 'basico', '', 'Perguntas básicas', 'runge-kutta', 1, 'texto', 1, NULL, 'RK4 em y′ = y, y(0) = 1, h = 0,1. Com k₁ = 1, qual é k₂ = f(x₀ + h/2, y₀ + (h/2)·k₁)?', NULL, '1,05', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"calc":"texto","resumo":"y₀ + (h/2)·k₁ = 1 + 0,05·1 = 1,05, e f(x, y) = y, então k₂ = 1,05."}', 'y₀ + (h/2)·k₁ = 1 + 0,05·1 = 1,05, e f(x, y) = y, então k₂ = 1,05.', NULL, 0, 'verde', NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-rk4-k2', 'A', '1,05', 1, NULL);
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-rk4-k2', 'B', '1,10', 0, 'Usou h no lugar de h/2.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-rk4-k2', 'C', '1,00', 0, 'Esse é k₁.');
INSERT INTO alternativas (questao_id, letra, texto, correta, explicacao) VALUES ('bf-rk4-k2', 'D', '1,0525', 0, 'Esse é k₃ = f(x₀ + h/2, y₀ + (h/2)·k₂).');
